(window.GIM_TS=window.GIM_TS||{})["Bava Batra.0"]={"from":0,"a":[["\u0003השותפין שרצו לעשות מחיצה\u0004 ביניהם \u0003בחצר\u0004 שהם שותפים בה — \u0003בונין את הכותל\u0004 לצורך המחיצה \u0003באמצע.\u0004 ובמה בונים אותה מחיצה? \u0003מקום שנהגו\u0004 בו \u0003לבנות\u0004 מחיצה שכזו באבני \u0003גויל\u0004 או באבני \u0003גזית\u0004 או ב\u0003כפיסין\u0004 (אריחים, חצי לבנים) או ב\u0003לבינין\u0004 — \u0003בונין, הכל כמנהג המדינה.\u0004","אם בונים ב\u0003גויל\u0004 — שותף \u0003זה נותן שלשה טפחים\u0004 מחלקו בקרקע, \u0003ו\u0004שותף \u0003זה נותן שלשה טפחים,\u0004 שכן עובי כותל שכזה הוא ששה טפחים. \u0003בגזית\u0004 — \u0003זה נותן טפחיים ומחצה וזה נותן טפחיים ומחצה; בכפיסין\u0004 — \u0003זה נותן טפחיים וזה נותן טפחיים; בלבינין\u0004 — \u0003זה נותן טפח ומחצה וזה נותן טפח ומחצה. לפיכך, אם נפל הכותל\u0004 — \u0003המקום והאבנים של שניהם\u0004 ומחלקים ביניהם.","\u0003וכן בגינה, מקום שנהגו לגדור\u0004 באמצע הגינה המשותפת — \u0003מחייבין אותו\u0004 לגדור. \u0003אבל בבקעה\u0004 (שדה, כגון שדה תבואה) \u0003מקום שנהגו שלא לגדור\u0004 — \u0003אין מחייבין אותו\u0004 לגדור בינו ובין חבירו,","\u0003אלא\u0004 ש\u0003אם רצה\u0004 אחד מן השותפים לעשות גדר, הריהו \u0003כונס לתוך\u0004 השטח \u0003שלו ובונה, ועושה חזית\u0004 (סימן היכר נראה) \u0003מבחוץ,\u0004 בצד החיצוני של הכותל, הפונה כלפי חלק חבירו, כסימן שהוא בנה הכל בעצמו ובחלקו. \u0003לפיכך, אם נפל הכותל\u0004 שבבקעה, שיש לו סימן כזה — \u0003המקום והאבנים שלו.\u0004","אף במקום שלא נהגו לגדור, \u0003אם עשו\u0004 מחיצה \u0003מדעת שניהם\u0004 — \u0003בונין את הכותל באמצע ועושין חזית מכאן ומכאן. לפיכך, אם נפל הכותל\u0004 — \u0003המקום והאבנים של שניהם.\u0004","בפירוש משנתנו \u0003סברוה\u0004 \u0005[סברו\u0006 הלומדים\u0005]\u0006 כי \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003\"מחיצה\"\u0004 שבמשנה? — \u0003גודא\u0004 \u0005[גדר],\u0006 \u0003כדתניא\u0004 \u0005[\u0006ו\u0005כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מחיצת הכרם\u0004 שבינו לבין שדה תבואה \u0003שנפרצה\u0004 ומעתה הרי זה כאילו יש זרעים בכרם, ואם יישאר כך ייאסר הכל בהנאה משום \"כלאי הכרם\", \u0003אומר לו\u0004 בעל התבואה לבעל הכרם: \u0003\"גדור\u0004 את מחיצתך\". אם עשה כן ו\u0003חזרה ונפרצה\u0004 המחיצה — \u0003אומר לו\u0004 שוב: \u0003\"גדור\",\u0004"],["אם \u0003נתיאש הימנה\u0004 מלגדור את הפירצה הזו \u0003ולא גדרה\u0004 — \u0003הרי זה קידש\u0004 (אוסר) את התבואה משום כלאי הכרם, \u0003וחייב באחריותה\u0004 לשלם לבעל התבואה את נזקו, שהרי הוא אשם בכך שהתבואה נאסרה בהנאה.","ולפי פירוש זה בלשון \"מחיצה\", יש לדייק מן המשנה כי \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 אם \u0003רצו\u0004 שניהם בונים מחיצה, ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא רצו\u0004 — \u0003אין מחייבין אותו,\u0004 למרות ששותפו אינו רוצה שיראה מה הוא עושה בחצירו; \u0003אלמא\u0004 \u0005[מכאן]\u0006 אפשר להסיק כי \u0003היזק ראיה לאו שמיה\u0004 \u0005[אין שמו,\u0006 אינו נקרא\u0005]\u0006 \u0003היזק,\u0004 שמה שאנשים אחרים רואים מה אדם עושה בחצירו אינו נחשב להיזק.","ומקשים על כך: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\u0003\"מחיצה\"\u0004 האמורה במשנתנו פירושה — \u0003פלוגתא\u0004 \u0005[חלוקה],\u0006 וראיה לדרך פירוש זו \u0003כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \u0003\"ותהי מחצת העדה\"\u0004 (במדבר לא, מג), שכוונתו — חלק העדה. \u0003ו\u0004נדייק מן המשנה כך: \u0003כיון\u0004 ש\u0003רצו\u0004 לעשות חלוקה ביניהם בחצר — \u0003בונין את הכותל בעל כרחו, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003היזק ראיה שמיה היזק!\u0004","ודוחים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, אם כן \u0003האי\u0004 \u0005[זו]\u0006 הלשון \u0003\"שרצו לעשות מחיצה\"\u0004 אינה מתאימה, שכן במקומה \u0003\"שרצו לחצות\" מבעי ליה\u0004 \u0005[צריך היה\u0006 לומר\u0005]!\u0006 על כך משיבים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 תפרש שמחיצה היא \u0003גודא\u0004 \u0005[גדר],\u0006 אם כן מדוע נאמר \u0003\"בונין את הכותל\"?\u0004 הרי \u0003\"בונין אותו\" מבעי ליה\u0004 \u0005[צריך היה\u0006 לומר\u0005]!\u0006 ומשיבים: \u0003אי תנא\u0004 \u0005[אם היה שונה]\u0006 רק \u0003\"\u0004בונין \u0003אותו\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003במסיפס\u0004 (סבכה) \u0003בעלמא\u0004 \u0005[סתם]\u0006 כלשהי, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבונים \u0003כותל\u0004 ממש, כפי הנהוג באותו מקום.","על הנאמר במשנה כי אם רצו לעשות מחיצה \u0003בונין את הכותל באמצע,\u0004 שואלים: הרי \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן \u0005מאליו\u0006\u0005]\u0006 שאם הסכימו לבנות כותל — שצריכים לעשותו בשל שניהם!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 להיאמר הלכה זו במשנתנו אלא באופן \u0003דקדים חד ורצייה לחבריה\u0004 \u0005[שקדם האחד וריצה את חבירו]\u0006 שיבנו את הכותל, והוא אכן התרצה לו. \u0003מהו דתימא מצי אמר ליה\u0004 \u0005[שתאמר\u0006 ש\u0005יכול לומר לו]\u0006 השני אחר כך, כשבא הראשון לתבוע ממנו את חלקו: \u0003כי איתרצאי\u0004 \u0005[כאשר התרציתי]\u0006 \u0003לך\u0004 — הרי זה דווקא \u0003באוירא\u0004 \u0005[באויר,\u0006 בחלל\u0005],\u0006 שתעשה מחיצה כלשהי, ואולם \u0003בתשמישתא\u0004 \u0005[בשימוש\u0006 בשטח החצר\u0005]\u0006 — \u0003לא איתרצאי\u0004 \u0005[התרציתי]\u0006 \u0003לך\u0004 ולא הסכמתי שיילקח לשם כך גם חלק מחצרי, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכיון שהסכימו הריהם בונים בשטח של שניהם.","כיון שפירשנו \"מחיצה\" במשנתנו במשמעות כותל, נמצא לדרך זו כי היזק ראיה אינו נחשב היזק, ועל כך מקשים: \u0003ו\u0004האם \u0003היזק ראיה לאו שמיה\u0004 \u0005[אין שמו,\u0006 אינו נקרא\u0005]\u0006 \u0003היזק? (סימן\u0004 להוכחות הבאות נגד הנחה זו הוא: \u0003גינה, כותל, כופין, וחולקין, חלונות, דרב נחמן).\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנה: \u0003וכן בגינה\u0004 מחייבים אותו לגדור, ומשמע שיש בזה היזק ראיה!","ומשיבים: \u0003גינה שאני\u0004 \u0005[שונה]\u0006 בדין זה של היזק ראיה, ו\u0003כ\u0004דברי \u0003ר' אבא,\u0004 ש\u0003אמר ר' אבא אמר רב הונא אמר רב: אסור לאדם לעמוד\u0004 (להיעצר ולהתבונן) \u0003בשדה חבירו בשעה שהיא עומדת בקמותיה\u0004 (בזמן שיש בה יבול), משום שעל ידי שהוא מסתכל בה הוא מזיק לה, והוא הדין בגינה. אבל בחצר שאין בה כל גידול קרקע אין דין היזק ראיה.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"וכן\" קתני\u0004 \u0005[שנה\u0006 במשנה\u0005]\u0006, משמע שדין גינה הוא כדין חצר! ומשיבים: מה שנאמר \"וכן\" אינו מתייחס לעצם החובה לבנות גדר, אלא לגבי הדין של \u0003גויל וגזית,\u0004 שאף המחיצה בגינה נעשית מאותם חומרים שמהם נעשית מחיצת החצר, וכמנהג המדינה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר מן המשנה הבאה: \u0003כותל חצר שנפל\u0004 — \u0003מחייבין אותו לבנות עד ארבע אמות.\u0004 משמע שיש בזה חיוב, והטעם בוודאי משום היזק ראיה! ודוחים: מקרה זה ש\u0003נפל\u0004 הוא \u0003שאני\u0004 \u0005[שונה],\u0006 כיון שכבר היתה מחיצה, ולכן חייב לשוב ולבנות.","ותוהים: \u0003ודקארי לה מאי קארי לה\u0004 \u0005[ומי שהקשה אותה\u0006 קושיה, \u0005מה הקשה אותה\u0006 כלל\u0005]?\u0006 הרי בפירוש מדובר שם בכותל שנפל, ומשמע — משום שכבר הוסכם ביניהם בעבר לעשות כותל! ומשיבים: סבור הוא כי אף במקום שלא היה כותל לפני כן מחייבים אותו לבנות, ומשום היזק ראיה. ולא לעצם חובת הבניה הובא דין זה, אלא \u0003סיפא איצטריכא ליה\u0004 \u0005[סופו\u0006 של הדין \u0005הוצרך לו\u0006 לומר\u0005]\u0006 מה שנאמר שם הלאה, שאף במקרה שהיה שם קיר גבוה — \u0003מארבע אמות ולמעלה אין מחייבין אותו\u0004 לבנות, משום שאין כאן עוד היזק ראיה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת לכך שיש דין היזק ראיה, ממה ששנינו להלן: \u0003כופין\u0004 בני החצר \u0003אותו,\u0004 את אחד מהם שאינו רוצה בכך \u0003לבנות\u0004 עימם \u0003בית שער\u0004 (מבנה שדרכו נכנסים לחצר) \u0003ודלת לחצר\u0004 המשותפת, על מנת שלא תהיה החצר פרוצה לרשות הרבים. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003היזק ראיה שמיה\u0004 \u0005[שמו]\u0006 \u0003היזק!\u0004 ומשיבים: אין מכאן ראיה לענייננו שכן \u0003הזיקא\u0004 \u0005[היזק]\u0006 ראיה של \u0003רבים\u0004 שמסתכלים בחצר \u0003שאני\u0004 \u0005[שונה],\u0006 שזה וודאי נחשב היזק.","ושואלים: \u0003ו\u0004היזק של \u0003יחיד\u0004 \u0003לא\u0004 נחשב כהיזק? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה לכך שהוא נחשב היזק ממה ששנינו: \u0003אין חולקין את החצר\u0004 המשותפת \u0003עד שיהא בה ארבע אמות לזה וארבע אמות לזה;\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יש בה\u0004 שטח מספיק \u0003כדי לזה וכדי לזה\u0004 — \u0003חולקין, מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003בכותל\u0004 באופן שלא יוכלו לראות זה את זה? ומשיבים: \u0003לא, במסיפס\u0004 (בסבכה) \u0003בעלמא\u0004 \u0005[סתם]\u0006","ואפילו היא כזו שאפשר לראות דרכה. ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו: אם בונה אדם כותל כנגד \u0003החלונות\u0004 של חבירו, \u0003בין מלמעלה בין מלמטה ובין מכנגדן\u0004 (ממולם) — מרחיק את הכותל מהם \u0003ארבע אמות. ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה]:\u0006 אם היה הכותל \u0003מלמעלן\u0004 מגביה ארבע אמות — \u0003כדי שלא יציץ\u0004 למטה \u0003ויראה, מלמטן\u0004 משאיר הפרש גובה של ארבע אמות, יותר מקומת אדם — \u0003כדי שלא יעמוד\u0004 על הכותל \u0003ויראה, מכנגדן\u0004 מרחיק — \u0003כדי שלא יאפיל\u0004 את האור בבית. משמע שאנו חוששים משום היזק ראיה!","ודוחים: \u0003הזיקא\u0004 \u0005[היזק]\u0006 ראיה של \u0003בית\u0004 הוא \u0003שאני\u0004 \u0005[שונה]\u0006 כי בבית ודאי אנשים עושים דברים שבצינעה, ואינם רוצים שאחרים יראו אותם. אבל החצר היא מקום פתוח, ושמא אינם מקפידים על כך.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ש\u0003אמר רב נחמן אמר שמואל: גג הסמוך לחצר חבירו\u0004 — \u0003עושין לו\u0004 לגג \u0003מעקה גבוה ארבע אמות,\u0004 משמע שדנים דין היזק ראיה בחצר! ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 \u0003בעל החצר לבעל הגג: לדידי קביעה לי תשמישי\u0004 \u0005[לי קבוע שימושי]\u0006 בחצר, שהרי אנשים רגילים להיכנס בחצר בכל עת, \u0003לדידך\u0004 \u0005[לך]\u0006 \u0003לא קביעה\u0004 \u0005[קבוע]\u0006 \u0003לך תשמישתך\u0004 \u0005[שימושך]\u0006 בגג, שהרי אנשים משתמשים בגג רק לעיתים מזדמנות, \u0003ולא ידענא בהי עידנא סליקא ואתית\u0004 \u0005[ואיני יודע באיזה זמן עולה ובא אתה\u0006 לגג\u0005]\u0006"],["\u0003דאיצטנע מינך\u0004 \u0005[שאסתתר ממך]\u0006 באותה שעה, אם אני רוצה לעשות אז דבר שאינני רוצה שתראהו.","עד כאן היתה שיטה אחת של הדיון בפירושה של המשנה. \u0003לישנא אחרינא אמרי לה\u0004 \u0005[לשון אחרת אומרים אותה\u0006 כך\u0005]:\u0006 \u0003סברוה\u0004 \u0005[חשבו]\u0006 הלומדים כי \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"מחיצה\"\u0004 האמורה במשנה — \u0003פלוגתא\u0004 \u0005[חלוקה],\u0006 וראיה לדבר \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותהי מחצת העדה\"\u0004 (במדבר לא, מג), \u0003ו\u0004פירוש המשנה לפי זה הוא ש\u0003כיון\u0004 ש\u0003רצו\u0004 לחצות, לחלק — \u0003בונין את הכותל בעל כורחן.\u0004 ומעירים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003היזק ראיה שמיה\u0004 \u0005[שמו\u0006 נקרא\u0005]\u0006 \u0003היזק.\u0004","ומקשים: \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מחיצה\"? גודא\u0004 \u0005[גדר],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מחיצת הכרם שנפרצה\u0004 — \u0003אומר לו \"גדור\", נפרצה\u0004 — \u0003אומר לו \"גדור\", נתיאש הימנה ולא גדרה\u0004 — \u0003הרי זה קידש\u0004 (אוסר) את התבואה משום כלאי הכרם, \u0003וחייב באחריותה.\u0004 והרי ש\"מחיצה\" — כותל היא.","\u0003ו\u0004לפי זה \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 במקרה ש\u0003רצו\u0004 בונים כותל, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא רצו\u0004 לעשות כותל — \u0003אין מחייבין אותו; אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003היזק ראיה לאו שמיה\u0004 \u0005[אין שמו,\u0006 אינו נקרא\u0005]\u0006 \u0003היזק!\u0004","על כך משיבים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 ש\"מחיצה\" פירושה כותל, הלשון \u0003\"בונין את הכותל\"\u0004 אינה נכונה, ובמקומה \u0003\"בונין אותו\" מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ומקשים מן הצד השני: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אתה מפרש ש\"מחיצה\" פירושה \u0003פלוגתא\u0004 \u0005[חלוקה]?\u0006 \u0003אי הכי\u0004 \u0005[אם כך],\u0006 הלשון \u0003\"שרצו לעשות מחיצה\"\u0004 אינה מדוייקת, \u0003\"שרצו לחצות\" מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ומשיבים: דבר זה הוא \u0003כדאמרי אינשי\u0004 \u0005[כפי שאומרים האנשים]:\u0006 \u0003תא נעביד פלוגתא\u0004 \u0005[בוא נעשה חלוקה],\u0006 ואם כן אפשר לומר גם בלשון משנתנו שרצו לעשות חלוקה ביניהם.","ולפי הבנה זו, ש\"מחיצה\" משמעה חלוקה, שואלים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003היזק ראיה שמיה\u0004 \u0005[שמו,\u0006 נקרא\u0005]\u0006 \u0003היזק, מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 אם \u0003רצו\u0004 בונים כותל? \u0003אפילו לא רצו נמי\u0004 \u0005[גם כן]\u0006 יעשו כותל ביניהם! \u0003אמר רב אסי אמר ר' יוחנן: משנתנו\u0004 — \u0003כשאין בה\u0004 בחצר \u0003דין חלוקה\u0004 מצד עצמה, ששותף אינו יכול לחייב את חבירו לחלקה ביניהם, לפי שהיא קטנה מן השיעור הראוי לחלוקה לכל שותף (ארבע אמות רבועות). ולכן דווקא \u0003והוא\u0004 במקרה ש\u0003רצו\u0004 חולקים את החצר.","ושואלים: לפי פירוש זה \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 — \u0003דכי לית ביה\u0004 \u0005[שכאשר אין בו,\u0006 במקום\u0005]\u0006 \u0003דין חלוקה\u0004 בכל זאת \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003רצו פליגי\u0004 \u0005[חולקים]?\u0006 אולם דבר זה \u0003תנינא\u0004 \u0005[שנינו\u0006 כבר\u0005]\u0006 במשנה אחרת: \u0003אימתי\u0004 אין מחלקים בפחות משיעור? \u0003בזמן שאין שניהם רוצים, אבל בזמן ששניהם רוצים\u0004 — \u0003אפילו פחות מכאן חולקין!\u0004 ודוחים: \u0003אי מהתם, הוה אמינא\u0004 \u0005[אם משם\u0006 בלבד \u0005הייתי אומר]\u0006 \u0003אפילו פחות מכאן\u0004 חולקים \u0003במסיפס\u0004 (בסבכה) \u0003בעלמא\u0004 \u0005[בלבד]\u0006 שאינה מונעת היזק ראיה, ועל כן \u0003קא משמע לן הכא\u0004 \u0005[השמיע לנו כאן]\u0006 שאם רצו לחלוק, בונים דווקא \u0003כותל.\u0004","ושואלים: אם כן, \u0003וליתני הא ולא ליתני הך\u0004 \u0005[ושישנה\u0006 את \u0005זו ושלא ישנה\u0006 את \u0005ההיא]?\u0006 שהרי ממשנתנו למדים יותר מאשר מן המשנה ההיא! ומשיבים: באמת לא היה צריך לשנות אותה לגופה, אלא \u0003סיפא\u0004 \u0005[סופה]\u0006 של אותה משנה \u0003איצטריכא ליה\u0004 \u0005[הוצרכה לו],\u0006 ששנה שם: \u0003וכתבי הקדש\u0004 של שותפים הכתובים כולם על כרך אחד, \u0003אף על פי ששניהם רוצים\u0004 לחלק — \u0003לא יחלוקו.\u0004","\u0003(לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 יש לחלקה האחרון של שמועה זו: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003רצו\u0004 לחלוק \u0003מאי הוי\u0004 \u0005[מה בכך]?\u0006 מה האילוץ הנוצר משום כך שיבנו כותל? \u0003ליהדר ביה\u0004 \u0005[שיחזור בו]\u0006 כל אחד מהם שהתחרט ואינו רוצה לחלוק! \u0003אמר רב אסי אמר ר' יוחנן:\u0004 מדובר כאן שלא רק שהסכימו בדברים על כך, אלא גם \u0003בשקנו מידו\u0004 שעשו מעשה של קנין לגבי הסכמה זו, ואז אין הצדדים יכולים עוד לחזור בהם.","ומקשים: \u0003אדאשמעינן\u0004 \u0005[עד ש\u0006הוא \u0005משמיע לנו]\u0006 \u0003בשאין בה דין חלוקה והוא\u0004 במקרה ש\u0003רצו, לישמעינן\u0004 \u0005[שישמיע לנו]\u0006 \u0003ביש בה דין חלוקה ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא רצו!\u0004 ומשיבים: \u0003אי אשמעינן\u0004 \u0005[אם היה משמיע לנו]\u0006 רק \u0003ביש בה דין חלוקה ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא רצו, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 במקרה \u0003שאין בה דין חלוקה אפילו רצו\u0004 לחלוק \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יעשו מחיצה בעל כרחו של אחד מהם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכן.","ושואלים: \u0003ומי מצית אמרת הכי\u0004 \u0005[והאם יכול אתה לומר כך]?\u0006 \u0003והא קתני סיפא\u0004 \u0005[והרי שנינו בסוף,\u0006 במשנה להלן\u0005]:\u0006 \u0003אימתי?\u0004 — \u0003בזמן שאין שניהם רוצים, אבל בזמן ששניהם רוצים\u0004 — \u0003יחלוקו. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר על \u0003כותל\u0004 שיכולים לכפות זה את זה לבנות כותל? ודוחים: \u0003לא,\u0004 אפשר לפרש שם \u0003אמסיפס בעלמא\u0004 \u0005[על סבכה בלבד]\u0006 ולא בכותל ממש.","ומקשים: כיוון שאנו מפרשים כך את משנתנו, אם כן \u0003ליתני האי\u0004 \u0005[שישנה\u0006 את \u0005זו,\u0006 משנתנו\u0005]\u0006 \u0003ולא ליתני האי\u0004 \u0005[ישנה\u0006 את \u0005זו],\u0006 שהרי נאמר בה יותר משנאמר באותה משנה! ומשיבים: \u0003סיפא\u0004 \u0005[סופה]\u0006 של אותה משנה \u0003אצטריכא ליה\u0004 \u0005[הוצרכה לו],\u0006 ששנה שם: \u0003ובכתבי הקדש, אף על פי ששניהם רוצים\u0004 — \u0003לא יחלוקו).\u0004","וממשיכים: \u0003במאי אוקימתא למתניתין\u0004 \u0005[במה העמדת\u0006 והסברת, \u0005את משנתנו]?\u0006 — \u0003בשאין בה דין חלוקה, אי\u0004 \u0005[אם]\u0006 \u0003בשאין בה דין חלוקה, כי רצו מאי הוי\u0004 \u0005[כאשר\u0006 הם \u0005רוצים מה יש\u0006 בכך\u0005]?\u0006 כלומר, מדוע יכול כל אחד מהם להכריח את חבירו לבנות כותל? \u0003נהדרו בהו\u0004 \u0005[שיחזרו בהם]!\u0006 \u0003אמר רב אסי אמר ר' יוחנן:\u0004 מדובר כאן באופן \u0003שקנו מידן,\u0004 ואין יכולים לחזור בהם לאחר מעשה קנין.","ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003קנו מידן מאי הוי\u0004 \u0005[מה יש\u0006 בכך\u0005]?\u0006 הלא \u0003קנין דברים בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא\u0004\u0005,\u0006 שהרי לא היה פה קנין של דבר, של חפץ מסויים, אלא הסכמה על תכנית לעתיד, ובדבר כזה אין קנין ממש! ומשיבים: \u0003בשקנו מידן ברוחות\u0004 \u0005[בצדדים],\u0006 כלומר, לא רק הסכימו על חלוקה כעיקרון, אלא אף סיכמו ביניהם איזה צד יהא שייך לכל אחד מהם. ונמצא שהיה הקנין על דבר שיש בו ממש, על חלקת אדמה מסויימת. \u0003רב אשי אמר: כגון שהלך זה בתוך\u0004 החלק \u0003שלו\u0004 \u0003והחזיק\u0004 (עשה על ידי כך מעשה חזקה) \u0003וזה\u0004 הלך \u0003בתוך שלו והחזיק.\u0004","שנינו במשנה: \u0003מקום שנהגו לבנות\u0004 גויל גזית כפיסין לבינין \u0003כו'.\u0004 ומסבירים את המילים: \u0003גויל\u0004 פירושו — \u0003אבני דלא משפיא\u0004 \u0005[אבנים שאינן מסותתות].\u0006 \u0003גזית\u0004 — \u0003אבני דמשפיא\u0004 \u0005[אבנים מסותתות],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כל אלה אבנים יקרת כמדות גזית\u0004 מגוררות במגרה\u0003\"\u0004 (מלכים א' ז, ט). ומכאן למדים שאבני גזית הן אבנים שיישרו ושייפו אותן. \u0003כפיסין\u0004 פירושו — \u0003ארחי\u0004 \u0005[אריחים,\u0006 חצאי לבנים\u0005].\u0006 \u0003לבינין\u0004 פירושו בארמית — \u0003ליבני\u0004 \u0005[לבנים].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: ממאי\u0004 \u0005[ממה],\u0006 מנין יודע אתה ש\u0003גויל אבני דלא משפיא נינהו\u0004 \u0005[אבנים שאינן מסותתות הן]\u0006 \u0003והאי טפח יתירא\u0004 \u0005[וטפח יתר זה]\u0006 של כותל גויל על כותל של גזית \u0003למורשא דקרנתא\u0004 \u0005[לבליטות הקרנות]\u0006 הוא. שמאחר והאבנים אינן מהוקצעות ומיושרות הריהן בולטות קצת החוצה, ולכן רוחב הקיר ששה טפחים? \u0003דילמא פלגא\u0004 \u0005[שמא חצי]\u0006 של \u0003גזית הוא,\u0004 שאבני גויל הן דווקא אבנים מסותתות שעוביין הוא רק שני טפחים וחצי (מחצית ממידת אבני גזית), \u0003והאי\u0004 \u0005[וזה]\u0006 ה\u0003טפח יתירא\u0004 \u0005[היתר]\u0006 בכותל של גויל, \u0003לביני אורבי\u0004 \u0005[לבין השורות]\u0006 \u0003הוא,\u0004 שבונים מכל צד באבנים דקות, ומשאירים טפח אחד באמצע למלא אותו בטיט ומלט להחזיקן.","והוכחה לאפשרות של הסבר זה היא \u0003כדקאמרינן\u0004 \u0005[כפי שאנו אומרים]:\u0006 \u0003כפיסין\u0004 פירושו — \u0003ארחי\u0004 \u0005[אריחים]\u0006 שעוביין רק כחצי לבינה\u0005,\u0006 \u0003לבינין\u0004 פירושו — \u0003ליבני\u0004 \u0005[לבנים],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 ה\u0003טפח יתירא\u0004 \u0005[היתר]\u0006 שעושים בכותל של כפיסים \u0003לביני אורבי\u0004 \u0005[לבין שורות\u0006 האריחים\u0005]\u0006 הוא!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 ש\u0003כפיסין\u0004 הם \u0003ארחי\u0004 \u0005[אריחין]\u0006 \u0003מנלן\u0004 \u0005[מנין לנו\u0006 זאת\u0005]?\u0006 \u0003אלא גמרא גמירי לה\u0004 \u0005[במסורת למודים\u0006 אנו \u0005אותה].\u0006 \u0003גויל נמי\u0004 \u0005[גם כן]\u0006 שהם \u0003אבני דלא משפיא\u0004 \u0005[אבנים שאינן מסותתות]\u0006 — \u0003גמרא גמירי לה\u0004 \u0005[במסורת למודים\u0006 אנו \u0005אותה].\u0006 זו היתה לשון אחת.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי: ממאי\u0004 \u0005[מנין]\u0006 יודע אתה \u0003דהאי כפיסין ארחי נינהו\u0004 \u0005[שכפיסין אלה אריחים הם]\u0006 ברוחב חצי לבינה, \u0003והאי\u0004 \u0005[וזה]\u0006 ה\u0003טפח יתירא\u0004 \u0005[היתר]\u0006 שעושים בכותל של כפיסים \u0003לביני אורבי\u0004 \u0005[לבין השורות]\u0006 הוא? \u0003דילמא מאי\u0004 \u0005[שמא מה\u0006 פירוש\u0005]\u0006 \u0003כפיסין\u0004 — \u0003אבני דלא משפיין\u0004 \u0005[אבנים שאינן מסותתות],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 ה\u0003טפח יתירא\u0004 \u0005[היתר]\u0006 \u0003למורשא דקרנתא\u0004 \u0005[\u0006\u0005לבליטת הקרנות],\u0006 \u0003כדקאמרינן\u0004 \u0005[כפי שאנו אומרים]:\u0006 \u0003גויל\u0004 — \u0003אבני דלא משפיין\u0004 \u0005[אבנים שלא מסותתות],\u0006 \u0003גזית\u0004 — \u0003אבני דמשפיין\u0004 \u0005[אבנים מסותתות],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 ה\u0003טפח יתירא\u0004 \u0005[היתר]\u0006 \u0003למורשא דקרנתא\u0004 \u0005[לבליטת הקרנות]\u0006 הוא?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 ש\u0003גויל\u0004 הוא \u0003אבני\u0004 \u0005[אבנים]\u0006 ש\u0003לא משפיין מנלן\u0004 \u0005[מסותתות, מנין לנו]?\u0006 \u0003אלא גמרא גמירי לה\u0004 \u0005[במסורת למודים\u0006 אנו \u0005אותה],\u0006 \u0003הכא נמי גמרא גמירי לה\u0004 \u0005[כאן גם כן במסורת למודים\u0006 אנו \u0005אותה].\u0006","\u0003אמר אביי, שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003כל\u0004 שעושים \u0003ביני אורבי\u0004 \u0005[בין השורות]\u0006 — הוא רוחב \u0003טפח.\u0004 ומעירים: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים דווקא\u0005]\u0006 \u0003בטינא\u0004 \u0005[בטיט],\u0006 אם מניח בין שורות האריחים מילוי של טיט, \u0003אבל בריכסא בעי טפי\u0004 \u0005[ב\u0006מילוי של \u0005אבנים קטנות צריך יותר].\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003הני מילי בריכסא\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005באבנים קטנות],\u0006 \u0003אבל בטינא\u0004 \u0005[בטיט]\u0006 \u0003לא בעי כולי האי\u0004 \u0005[צריך כל כך]\u0006 ויכול לעשות פחות מעובי טפח.","אגב כך שואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003בגזית\u0004 ש\u0003כל ארבע אמות גובה, אי הוי פותיא חמשא\u0004 \u0005[אם היה הרוחב חמישה]\u0006 טפחים — \u0003קאי\u0004 \u0005[עומד],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא קאי\u0004 \u0005[עומד],\u0006 שזה היחס שצריך להיות בין גובה הקיר ועוביו? \u0003והא,\u0004 \u0005[והרי]\u0006 קיר של \u0003אמה טרקסין\u0004 שהיתה במקדש \u0003דהואי\u0004 \u0005[שהיה]\u0006 \u0003גבוה תלתין אמהתא\u0004 \u0005[שלושים אמות],\u0006 \u0003ולא הוה פותיא\u0004 \u0005[היה רחב]\u0006 \u0003אלא שית פושכי, וקם\u0004 \u0005[ששה טפחים, והיה עומד]!\u0006 ומשיבים: \u0003כיון דאיכא\u0004 \u0005[שיש\u0006 שם\u0005]\u0006 \u0003טפח יתירא\u0004 \u0005[יתר]\u0006 — הרי זה \u0003קאי\u0004 \u0005[עומד]\u0006 אפילו בגובה רב.","ושואלים: \u0003ובמקדש שני מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא עבוד\u0004 \u0005[עשו]\u0006 \u0003אמה טרקסין\u0004 כמו במקדש ראשון? ומשיבים: \u0003כי קאי\u0004 \u0005[כאשר עומד]\u0006 ברוחב זה — \u0003בתלתין קאי\u0004 \u0005בשלושים\u0006 אמה הוא \u0005עומד],\u0006 \u0003טפי לא קאי\u0004 \u0005[ביותר\u0006 מזה \u0005אינו עומד],\u0006 ומקדש שני גבוה היה יותר ממקדש ראשון, והיו צריכים לעשות מחיצה גבוהה יותר.","ומעירים: \u0003ומנלן דהוה\u0004 \u0005[ומנין לנו שהיה]\u0006 בית מקדש שני \u0003גבוה טפי\u0004 \u0005[יותר]\u0006 מהראשון? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"גדול יהיה כבוד הבית הזה האחרון מן הראשון\"\u0004 (חגי ב, ט), ובפירושו של פסוק זה נחלקו \u0003רב ושמואל, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שנחלקו בכך \u0003ר' יוחנן ור' אלעזר, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר:\u0004 הכוונה שגדול יהיה כבודו \u0003בבנין\u0004 — שהבנין השני היה גבוה יותר מן הראשון, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר:\u0004"],["\u0003בשנים,\u0004 שבית המקדש השני עמד על תילו זמן רב יותר מהראשון. ומעירים: \u0003ואיתא להא ואיתא להא\u0004 \u0005[ויש לזה ויש לזה],\u0006 ששני הדברים היו בו.","ושואלים: \u0003וניעבדו תלתין אמין\u0004 \u0005[ושיעשו שלושים אמה]\u0006 \u0003בבנין,\u0004 \u0003ואידך ניעביד\u0004 \u0005[ו\u0006את \u0005השאר יעשו]\u0006 ב\u0003פרוכת!\u0004 ומשיבים: \u0003כי קאי תלתין אמהתא נמי\u0004 \u0005[כאשר עומדות שלושים אמות גם כן]\u0006 — \u0003אגב תקרה ומעזיבה הוה קאי\u0004 \u0005[היו עומדות],\u0006 שהתקרה היתה מחזיקה את הכותל מצדו העליון. אבל \u0003בלא תקרה ומעזיבה לא הוה קאי\u0004 \u0005[היה עומד].\u0006","וממשיכים לשאול: \u0003וליעביד\u0004 \u0005[ושיעשו]\u0006 \u0003מה\u0004 ש\u0003אפשר בבנין\u0004 באותו גובה שיעמוד היטב, \u0003וליעביד אידך\u0004 \u0005[ושיעשה\u0006 את \u0005השאר]\u0006 ב\u0003פרוכת! אמר אביי, גמירי\u0004 \u0005[למודים\u0006 היו במסורת\u0005]:\u0006 שעושים מחיצה במקדש \u0003אי כולהו\u0004 \u0005[או כולם,\u0006 הכל\u0005]\u0006 \u0003ב\u0004דרך \u0003בנין אי כולהו\u0004 \u0005[או כולם,\u0006 הכל\u0005]\u0006 \u0003בפרוכת.\u0004 וטעמו של דבר: \u0003אי כולהו\u0004 \u0005[או כולם]\u0006 \u0003בבנין\u0004 — למדים זאת \u0003ממקדש\u0004 ראשון שבו היתה מחיצה זו כדרך בנין, \u0003אי כולהו\u0004 \u0005[או כולם]\u0006 \u0003בפרוכת\u0004 — למדים \u0003ממשכן\u0004 שהיתה פרוכת מפרידה. אבל בנין ופרוכת כאחד לא נעשו בשום מקום.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם כל המידות שנאמרו במשנה לגבי רוחב המחיצות השונות, כוללות \u0003הן וסידן,\u0004 עובי המחיצות עצמן והסיד שמסיידין אותן, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003הן בלא סידן? אמר רב נחמן בר יצחק: מסתברא\u0004 \u0005[מסתבר\u0006 לומר\u0005]\u0006 שהכוונה ל\u0003הן וסידן, דאי סלקא דעתך\u0004 \u0005[שאם עולה\u0006 על \u0005דעתך\u0006 לומר\u0005]\u0006 \u0003הן בלא סידן, ליתנייה לשיעוריה\u0004 \u0005[שישנה\u0006 גם \u0005את שיעורו\u0006 של הסיד\u0005]!\u0006 \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]:\u0006 \u0003הן וסידן.\u0004 ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך:\u0004 \u0003הן בלא סידן, וכיון\u0004 שהסיד \u0003לא הוי\u0004 \u0005[אינו]\u0006 בעובי \u0003טפח,\u0004 לכן \u0003לא תני\u0004 \u0005[שנה]\u0006 שיעור קטן כזה.","ומקשים: \u0003והא קתני\u0004 \u0005[והרי שנה]:\u0006 \u0003בלבינין\u0004 — \u0003זה נותן טפח ומחצה וזה נותן טפח ומחצה,\u0004 משמע שמפרט גם מידה שהיא פחותה מטפח! ומשיבים: \u0003התם חזי לאיצטרופי\u0004 \u0005[שם ראוי להצטרף]\u0006 שעל כל פנים הרוחב הכולל הוא שלושה טפחים שלמים.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003הקורה שאמרו\u0004 בהלכות עירובין — צריכה להיות \u0003רחבה כדי לקבל אריח, והאריח\u0004 — הוא \u0003חצי לבינה של שלשה טפחים,\u0004 ושם מדובר בלבינה בלא סיד!","ומשיבים: \u0003התם ברברבתא\u0004 \u0005[שם\u0006 מדובר \u0005ב\u0006לבינים \u0005גדולות]\u0006 שרוחבן הוא שלושה טפחים שלמים, ואילו כאן מדובר בלבנים צרות יותר, שרוחבן קצת פחות משלושה טפחים, ושיעור שלושה טפחים הוא עם הסיד שעליהן. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 לפרש כן, \u0003דקתני\u0004 \u0005[ששנה]\u0006 שם: לבנה \u0003של שלשה טפחים, מכלל דאיכא זוטרא\u0004 \u0005[מכאן שיש\u0006 לבנה \u0005קטנה\u0006 יותר\u0005].\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003אמר רב חסדא: לא ליסתור איניש בי כנישתא\u0004 \u0005[אל יסתור אדם בית כנסת]\u0006 \u0003עד\u0004 \u0003דבני בי כנישתא אחריתי\u0004 \u0005[ש\u0006הוא \u0005בונה\u0006 תחילה \u0005בית כנסת אחר].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים\u0006 בטעם הדבר\u0005]:\u0006 \u0003משום פשיעותא\u0004 \u0005[פשיעה,\u0006 רשלנות\u0005],\u0006 שמא יתרשלו ולא יבנו אחר שהרסו, \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003משום צלויי\u0004 \u0005[תפילה],\u0006 שבינתיים לא יהיה מקום להתפלל.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם],\u0006 בין ההסברים הללו? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 במקום \u0003דאיכא בי כנישתא אחריתי\u0004 \u0005[שיש בית כנסת אחר].\u0006 שאמנם יש מקום להתפלל בו, אבל החשש שמא לא יבנו את זה עומד במקומו. מסופר: \u0003מרימר ומר זוטרא סתרי ובנו בי קייטא בסיתווא, ובנו בי סיתווא בקייטא\u0004 \u0005[היו סותרים ובונים בית\u0006 כנסת של \u0005קיץ בחורף, ו\u0006באותו אופן \u0005בונים בית חורף בקיץ]\u0006 שלא יהיה המקום בלא בית כנסת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: גבו זוזי ומחתי,\u0004 \u0005[\u0006אם \u0005גבויים הכספים ומונחים\u0006 לצורך בניית בית הכנסת החדש \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין\u0005,\u0006 האם על סמך זה מותר לסתור את בית הכנסת הישן? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 יש לחשוש \u0003דילמא מיתרמי להו\u0004 \u0005[שמא יזדמן להם]\u0006 \u0003פדיון שבויים ויהבי להו\u0004 \u0005[ויתנו אותם]\u0006 את הכספים לצורך דחוף זה, ויישאר המקום בלי בית כנסת.","ושאל עוד: אם \u0003שריגי ליבני והדרי הודרי ומחתי כשורי, מאי\u0004 \u0005[מסודרות הלבנים ומוכנים הקרשים ומונחות הקורות, מה\u0006 הדין?\u0005]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אף על פי כן, \u0003זמנין דמתרמי להו\u0004 \u0005[פעמים שמזדמן להם]\u0006 \u0003פדיון שבויים, מזבני ויהבי להו\u0004 \u0005[מוכרים ונותנים אותם].\u0006 והקשה לו: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאתה חושש שיימכרו לצורך פדיון שבויים, \u0003אפילו\u0004 במקרה שכבר \u0003בנו נמי\u0004 \u0005[גם כן]\u0006 נחשוש שמא יצטרכו למכור את המבנה לצורך זה, ולא נסתור את הישן! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דירתיה דאינשי לא מזבני\u0004 \u0005[דירתם של בני אדם אין\u0006 הם \u0005מוכרים].\u0006","ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 במקרה ש\u0003לא חזי\u0004 \u0005[נראה]\u0006 \u0003בה תיוהא\u0004 \u0005[סדק],\u0006 שאז אין סותרים אותו עד שיבנו אחר, \u0003אבל חזי\u0004 \u0005[נראה]\u0006 \u0003בה תיוהא\u0004 \u0005[סדק]\u0006 — \u0003סתרי ובני\u0004 \u0005[סותרים ובונים].\u0006 \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003רב אשי חזא בה תיוהא בכנישתא דמתא מחסיא\u0004 \u0005[ראה סדקים בבית הכנסת של מתא מחסיא]\u0006 עירו, \u0003סתריה ועייל לפורייה להתם\u0004 \u0005[סתר אותו והכניס את מיטתו לשם],\u0006 כדי שלא יתעכבו בבניינו, שהרי הוא עצמו יצטרך למחסה מפני הגשמים, \u0003ולא אפקיה\u0004 \u0005[הוציא אותה]\u0006 \u0003עד דמתקין ליה שפיכי\u0004 \u0005[שהתקינו לו\u0006 לבית הכנסת \u0005מרזבים].\u0006","ושואלים: אם כן, \u0003ובבא בן בוטא היכי אסביה ליה\u0004 \u0005[איך נתן לו]\u0006 \u0003עצה להורדוס למיסתריה\u0004 \u0005[לסתור]\u0006 את \u0003בית המקדש\u0004 ולבנות אחר במקומו, כפי שמסופר להלן? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא: לא ליסתור איניש בי כנישתא\u0004 \u0005[אל יסתור אדם בית כנסת]\u0006 \u0003עד דבני בי כנישתא אחריתא\u0004 \u0005[ש\u0006הוא \u0005בונה בית כנסת אחר]!\u0006 ומשיבים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כי \u0003תיוהא חזא ביה\u0004 \u0005[סדקים ראה בו],\u0006 בבנין המקדש הישן, \u0003איבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003מלכותא שאני, דלא הדרא ביה\u0004 \u0005[המלכות שונה, שאינה חוזרת בה]\u0006 ממה שהחליטה לעשות, ואין חוששים אצלה לרשלנות ולפשיעה כמו באנשים פרטיים. ש\u0003אמר שמואל: אי אמר מלכותא\u0004 \u0005[אם תאמר המלכות]:\u0006 \u0003עקרנא טורי\u0004 \u0005[אני עוקרת הרים]\u0006 — \u0003עקר טורי\u0004 \u0005[תעקור הרים]\u0006 \u0003ולא הדר ביה\u0004 \u0005[תחזור בה].\u0006","הזכרנו את המעשה של בבא בן בוטא, ומעתה מפרטים: \u0003הורדוס עבדא\u0004 \u0005[עבד]\u0006 של \u0003בית חשמונאי הוה\u0004 \u0005[היה],\u0006 \u0003נתן עיניו\u0004 (חשק) \u0003באותה תינוקת\u0004 (ילדה) של בית חשמונאי. \u0003יומא חד\u0004 \u0005[יום אחד]\u0006 \u0003שמע ההוא גברא\u0004 \u0005[אותו אדם,\u0006 הורדוס\u0005]\u0006 \u0003בת קלא דאמר\u0004 \u0005[בת קול שאומרת]:\u0006 \u0003כל עבדא דמריד השתא מצלח\u0004 \u0005[עבד שמורד עכשיו יצליח].\u0006 \u0003קם קטלינהו לכולהו מרותיה ושיירה לההיא ינוקתא\u0004 \u0005[עמד הרג את כל אדוניו והשאיר אותה ילדה].\u0006 \u0003כי חזת ההיא ינוקתא דקא בעי למינסבה\u0004 \u0005[כאשר ראתה אותה ילדה שהוא רוצה לשאת אותה\u0006 לאשה\u0005],\u0006 \u0003סליקא לאיגרא ורמא קלא\u0004 \u0005[עלתה לגג והרימה קולה],\u0006 \u0003אמרה: כל מאן דאתי ואמר\u0004 \u0005[מי שיבוא ויאמר]\u0006 \u0003מבית חשמונאי קאתינא\u0004 \u0005[בא אני]\u0006 — \u0003עבדא\u0004 \u0005[עבד]\u0006 \u0003הוא,\u0004 ש\u0003לא אישתיירא מינייהו\u0004 \u0005[נשארה מהם]\u0006 \u0003אלא ההיא ינוקתא\u0004 \u0005[אותה ילדה],\u0006 \u0003וההיא ינוקתא נפלה מאיגרא לארעא\u0004 \u0005[ואותה ילדה נפלה מהגג לארץ]\u0006 ומתה.","ומסופר כי הורדוס \u0003טמנה שבע שנין בדובשא\u0004 \u0005[שנים בדבש]\u0006 לשמר את גופה שלא יירקב. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003בא עליה\u0004 לאחר מותה, \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003לא בא עליה. דאמרי לה\u0004 \u0005[\u0006לאלה \u0005שאומרים]\u0006 \u0003בא עליה, הא\u0004 \u0005[זה]\u0006 ש\u0003טמנה\u0004 ושימר את גופתה — היה זה על מנת \u0003ליתוביה ליצריה\u0004 \u0005[לספק את יצרו]\u0006 ולכן רצה שגופתה תישאר קיימת. \u0003ודאמרי לה\u0004 \u0005[ו\u0006לאלה \u0005שאומרים]\u0006 ש\u0003לא בא עליה, האי\u0004 \u0005[זה]\u0006 ש\u0003טמנה\u0004 — \u0003כי היכי דנאמרו\u0004 \u0005[כדי שיאמרו]:\u0006 \u0003בת מלך נסב\u0004 \u0005[נשא].\u0006","\u0003אמר\u0004 הורדוס בליבו: \u0003מאן דריש\u0004 \u0005[מי\u0006 הוא זה \u0005שדורש]\u0006 את הכתובים \u0003\"מקרב אחיך תשים עליך מלך\"\u0004 (דברים יז, טו), ומפרש שצריך המלך להיות גם בן משפחה יהודית, ולא עבד משוחרר או גר? — \u0003רבנן\u0004 \u0005[חכמים]\u0006 הם שדורשים כך, והם העומדים על כך שיהיה המלך ממשפחות ישראל. \u0003קם קטלינהו לכולהו רבנן\u0004 \u0005[עמד הרג את כל החכמים],\u0006 \u0003שבקיה\u0004 \u0005[הניח]\u0006 בחיים רק את \u0003בבא בן בוטא\u0004 כדי \u0003למשקל\u0004 \u0005[ליטול]\u0006 \u0003עצה מניה\u0004 \u0005[ממנו].\u0006"],["\u0003אהדר ליה כלילא דיילי\u0004 \u0005[הקיף\u0006 הורדוס את ראשו של בבא בן בוטא \u0005בעטרה של קיפוד],\u0006 \u0003נקרינהו לעיניה\u0004 \u0005[\u0006ו\u0005ניקר את עיניו]\u0006 על ידי כך. \u0003יומא חד אתא ויתיב קמיה\u0004 \u0005[יום אחד בא\u0006 הורדוס \u0005וישב לפניו]\u0006 בלי להודיעו מי הוא, לפי שרצה לבדוק אותו, \u0003אמר: חזי מר האי עבדא בישא מאי קא עביד\u0004 \u0005[יראה אדוני\u0006 את \u0005העבד הרע הזה\u0006 הורדוס, \u0005מה הוא עושה]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי אעביד ליה\u0004 \u0005[מה אעשה לו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נלטייה מר\u0004 \u0005[יקללנו אדוני]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"גם במדעך\u0004 (בסתר) \u0003מלך אל תקלל\"\u0004 (קהלת י, כ). \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003האי לאו\u0004 \u0005[זה לא]\u0006 \u0003מלך הוא,\u0004 שהרי לא כדין הוא מולך! \u0003אמר ליה\u0004 \u0005[לו]\u0006 בבא בן בוטא: \u0003וליהוי\u0004 \u0005[ולו יהיה]\u0006 \u0003עשיר בעלמא\u0004 \u0005[בלבד],\u0006 \u0003וכתיב\u0004 \u0005[\u0006והרי \u0005נאמר]\u0006 בהמשך אותו פסוק: \u0003\"ובחדרי משכבך אל תקלל עשיר\"\u0004 (קהלת י, כ), \u0003ו\u0004אף \u0003לא יהא אלא נשיא\u0004 איני מקללו, \u0003וכתיב\u0004 \u0005[ו\u0006כפי ש\u0005נאמר]:\u0006 \u0003\"ונשיא בעמך לא תאר\"\u0004 (שמות כב, כז).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 הורדוס: דבר זה נאמר \u0003בעושה מעשה עמך,\u0004 שמתנהג כאדם כשר מישראל, \u0003והאי\u0004 \u0005[וזה,\u0006 הורדוס\u0005]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003עושה מעשה עמך! אמר ליה\u0004 \u0005[לו]\u0006 בבא בן בוטא: מכל מקום \u0003מסתפינא מיניה\u0004 \u0005[מפחד אני ממנו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הורדוס: \u0003ליכא איניש דאזיל דלימא ליה, דאנא ואת יתיבנא\u0004 \u0005[אין אדם שילך ויאמר לו, שאני ואתה\u0006 בלבד \u0005יושבים\u0006 כאן\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"כי עוף השמים יוליך את הקול ובעל כנפים יגיד דבר\"\u0004 (קהלת י, כ).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 הורדוס: \u0003אנא\u0004 \u0005[אני]\u0006 \u0003הוא\u0004 הורדוס, \u0003אי הואי ידענא דזהרי רבנן כולי האי\u0004 \u0005[לו הייתי יודע שזהירים חכמים כל כך],\u0006 \u0003לא הוה קטילנא להו\u0004 \u0005[הייתי הורג אותם],\u0006 \u0003השתא מאי תקנתיה דההוא גברא\u0004 \u0005[עכשיו מה תקנתו של אותו אדם],\u0006 כלומר, מה יכול אני לעשות כדי לתקן את מה שחטאתי? \u0003אמר ליה\u0004 \u0005[לו]\u0006 בבא בן בוטא: \u0003הוא\u0004 מי ש\u0003כבה אורו של עולם\u0004 על ידי הריגת חכמי התורה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי נר מצוה ותורה אור\"\u0004 (משלי ו, כג), \u0003ילך ויעסוק באורו של עולם, דכתיב\u0004 \u0005[שנאמר]\u0006 בבית המקדש: \u0003\"ונהרו אליו כל הגוים\"\u0004 (ישעיהו ב, ב), שפירש \"נהרו\" מלשון נהורה, אור. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003הכי אמר ליה\u0004 \u0005[כך אמר לו]:\u0006 \u0003הוא סימא עינו של עולם, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והיה אם מעיני העדה\"\u0004 (במדבר טו, כד), והם החכמים — \u0003ילך ויתעסק בעינו של עולם, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הנני מחלל את מקדשי גאון עזכם מחמד עיניכם\"\u0004 (יחזקאל כד, כא).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 הורדוס: \u0003מסתפינא ממלכותא\u0004 \u0005[מתיירא אני מן המלכות]\u0006 של רומא שלא ירשו לי לעשות כן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 בבא בן בוטא: \u0003שדר שליחא\u0004 \u0005[שלח שליח],\u0006 \u0003וליזיל שתא וליעכב שתא ולהדר שתא\u0004 \u0005[ושילך שנה\u0006 לשם \u0005ושיתעכב שנה\u0006 שם \u0005ויחזור\u0006 \u0005שנה],\u0006 \u0003אדהכי סתרית ליה ובניית ליה\u0004 \u0005[בין כך ובין כך תסתור אותו ותבנה אותו].\u0006 \u0003עבד הכי\u0004 \u0005[עשה כך].\u0006 \u0003שלחו ליה\u0004 \u0005[לו]\u0006 מרומא בתשובה לשאלתו: \u0003אם לא סתרתה אל תסתור, ואם סתרתה אל תבני\u0004 \u0005[תבנה],\u0006 \u0003ואם סתרתה ובנית, עבדי בישא בתר דעבדין מתמלכין\u0004 \u0005[עושי רע אחרי שעושים הם מתייעצים],\u0006 גם \u0003אם זיינך עלך\u0004 \u0005[נשקך עליך],\u0006 שיש בידך כוח צבאי, \u0003ספרך\u0004 מגילת היוחסין שלך, שכתוב בו שאתה עבד, נמצא \u0003כאן, לא רכא\u0004 \u0005[מלך]\u0006 \u0003ולא בר רכא\u0004 \u0005[בן מלך],\u0006 \u0003הורדוס עבדא קלניא מתעביד\u0004 \u0005[העבד, בן חורין נעשה\u0006 מעצמו\u0005].\u0006","ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"רכא\"?\u0004 — \u0003מלכותא\u0004 \u0005[מלכות],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ו\u0003אנכי היום רך ומשוח מלך\"\u0004 (שמואל ב' ג, לט). \u0003ואי בעית אימא, מהכא\u0004 \u0005[ואם תרצה אמור מכאן],\u0006 ממה שנאמר ביוסף, לאחר שנתמנה למשנה לפרעה: \u0003\"ויקראו לפניו אברך\"\u0004 (בראשית מא, מג).","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003מי שלא ראה בנין הורדוס, לא ראה בנין נאה מימיו.\u0004 ושואלים: \u0003במאי בנייה\u0004 \u0005[במה בנה אותו]?\u0006 \u0003אמר רבה: באבני שישא ומרמרא\u0004 \u0005[שיש לבן וירוק].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003באבני כוחלא, שישא ומרמרא\u0004 \u0005[שיש כחול, לבן וירוק].\u0006 \u0003אפיק שפה ועייל שפה, כי היכי דנקביל סידא\u0004 \u0005[הוציא\u0006 קצת \u0005משפת\u0006 האבן \u0005והכניס\u0006 קצת \u0005משפת\u0006 האבן, \u0005כדי שיוכל לקבל\u0006 עליו את \u0005הסיד].\u0006 \u0003סבר למשעייה בדהבא\u0004 \u0005[רצה לטוח אותו בזהב],\u0006 \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]:\u0006 \u0003שבקיה, דהכי שפיר טפי\u0004 \u0005[הנח אותו\u0006 ואל תצפהו, \u0005שכך\u0006 הוא \u0005יפה יותר],\u0006 \u0003דמיחזי כי אידוותא דימא\u0004 \u0005[שנראה כמו גלי ים].\u0006","ושואלים: \u0003ובבא בר בוטא היכי עבד הכי\u0004 \u0005[איך עשה כך]\u0006 לתת עצה להורדוס הרשע? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר רב, ואיתימא\u0004 \u0005[ויש אומרים\u0006 שאמר זאת\u0005]\u0006 \u0003ר' יהושע בן לוי: מפני מה נענש דניאל?\u0004 — \u0003מפני שהשיא עצה לנבוכדנצר, ש\u0004לאחר שניבא לו דברים קשים \u0003נאמר: \"להן מלכא מלכי ישפר עלך וחטאיך בצדקה פרק ועויתך במחן ענין הן תהוה ארכא לשלותך\u0004 \u0005[לכן המלך עצתי תיטב עליך, וחטאיך בצדקה פדה, ו\u0006את \u0005עוונך בחנינת עניים, אז תהיה ארכה לשלותך]\u0006 \u0003\" וגו'\u0004 (דניאל ד, כד), וכתיב \u0005[ונאמר]:\u0006 \u0003\"כלא מטא על נבוכדנצר מלכא\"\u0004 \u0005[הכל הגיע על נבוכדנצר המלך]\u0006 (דניאל ד, כה), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ולקצת ירחין תרי עשר\" וגו'\u0004 (דניאל ד, כו) \u0005[ובסוף שנים עשר חודשים]\u0006 נתקיים הדבר, ולא קודם לכן!","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003שאני עבדא, דאיחייב\u0004 \u0005[שונה עבד ש\u0006הוא \u0005מחוייב]\u0006 \u0003במצו‍ת\u0004 ולכן צריך היה לסייע להורדוס לעשות תשובה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003בית המקדש, דאי\u0004 \u0005[שאם]\u0006 \u0003לא מלכות\u0004 תבנה אותו \u0003לא מתבני\u0004 \u0005[ייבנה].\u0006","ושואלים: \u0003ודניאל מנלן דאיענש\u0004 \u0005[מנין לנו שנענש]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותקרא אסתר להתך\u0004 מסריסי המלך אשר העמיד לפניה\u0003\"\u0004 (אסתר ד, ה), \u0003ואמר רב: התך\u0004 — \u0003זה דניאל, הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 שנקרא התך משום \u0003שחתכוהו מגדולתו\u0004 ועשו אותו פקיד קטן, \u0003אלא למאן דאמר\u0004 \u0005[למי שאומר]\u0006 ומפרש שקראו לו התך משום \u0003שכל דברי מלכות נחתכין על פיו, מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 מה עונש נתנו לו? ומשיבים: \u0003דשדיוהו לגובא דארייוותא\u0004 \u0005[שזרקוהו לגוב אריות].\u0006","שנינו במשנה: מקום שנהגו לבנות גויל וכו' \u0003הכל כמנהג המדינה.\u0004 ושואלים: תוספת זו \u0003\"הכל\u0004 כמנהג המדינה \u0003\"\u0004\u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]\u0006 נאמרה? ומשיבים: \u0003לאתויי אתרא דנהיגי בהוצא ודפנא\u0004 \u0005[להביא מקום שנוהגים\u0006 לעשות מחיצה \u0005בענפי דקל ודפנה],\u0006 שאם כך מנהג המקום, עושים כן.","שנינו במשנה: \u0003לפיכך, אם נפל הכותל\u0004 — \u0003המקום והאבנים של שניהם.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן \u0005מאליו\u0006\u0005]\u0006 שכך הוא, שהרי שניהם היו שותפים בבנייתו! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקום ש\u0003נפל\u0004 הכל \u0003לרשותא דחד מינייהו\u0004 \u0005[לרשותו של אחד מהם],\u0006 \u0003אי נמי דפנינהו חד לרשותא דידיה\u0004 \u0005[או גם כן,\u0006 במקרה \u0005שפינה אותם אחד\u0006 מהם \u0005לרשותו שלו],\u0006 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ניהוי אידך\u0004 \u0005[שיהיה\u0006 נחשב \u0005האחר]\u0006 \u0003המוציא מחבירו\u0004 ו\u0003עליו\u0004 תוטל חובת \u0003הראיה\u0004 להוכיח שהוא שותף, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שחזקתם שהם שותפים, ואינם צריכים הוכחה.","שנינו במשנה: \u0003וכן בגינה, מקום שנהגו לגדור\u0004 — \u0003מחייבין אותו.\u0004 ושואלים: \u0003הא גופא קשיא\u0004 \u0005[זה עצמו קשה],\u0006 \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 מצד אחד: \u0003וכן בגינה, מקום שנהגו לגדור\u0004 — \u0003מחייבין אותו,\u0004 ומכאן משמע: \u0003הא סתמא\u0004 \u0005[אבל סתם]\u0006 אם לא נהגו — \u0003אין מחייבין אותו.\u0004","\u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003אבל בקעה\u0004 (שדה), \u0003מקום שנהגו שלא לגדור\u0004 — \u0003אין מחייבין אותו,\u0004 ונדייק מכאן: \u0003הא סתמא\u0004 \u0005[אבל סתם]\u0006 — \u0003מחייבין אותו.\u0004 ויש לתמוה: \u0003השתא\u0004 \u0005[עכשיו\u0006 הרי\u0005]\u0006 בנוגע ל\u0003סתם גינה אמרת\u0004 ש\u0003לא\u0004 מחייבים לעשות מחיצה, ואם כן \u0003סתם בקעה מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאין מחייבים אותו? והרי בבקעה בוודאי נחוצה הגדר פחות!","\u0003אמר אביי, הכי קאמר\u0004 \u0005[כך אמר]\u0006 התנא: \u0003וכן\u0004 כדין חצר כן דין \u0003סתם גינה\u0004 שמחייבים לבנות מחיצה, \u0003ו\u0004כן \u0003במקום שנהגו לגדור בבקעה\u0004 — \u0003מחייבין אותו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אם כן, מאי\u0004 \u0005[מה]\u0006 לשון \u0003\"אבל\"\u0004 האמורה לאחר מכן לגבי בקעה, שמשמעה שלא נידונה בקעה ככלל הקודם? \u0003אלא אמר רבא, הכי קתני\u0004 \u0005[כך\u0006 \u0005שנה]:\u0006 \u0003וכן סתם גינה כמקום שנהגו לגדור דמי\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 \u0003ומחייבין אותו\u0004 לגודרה. \u0003אבל סתם בקעה כמקום שלא נהגו דמי\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 \u0003ואין מחייבין אותו\u0004 לגודרה.","שנינו במשנה: אבל בבקעה וכו' אין מחייבין אותו, \u0003אלא אם רצה, כונס לתוך שלו ובונה ועושה חזית\u0004 מבחוץ. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חזית\"? אמר רב הונא: אכפיה ליה לקרנא לבר\u0004 \u0005[שכופף את קצות\u0006 הכותל \u0005לחוץ].\u0006 ושואלים: \u0003ונעביד מלגיו\u0004 \u0005[ושיעשה בפנים]!\u0006 ואומרים: \u0003עביד חבריה נמי מלבר\u0004 \u0005[יעשה חבירו גם כן מבחוץ],\u0006 בחלק הפונה לצד החבר כעין זה, \u0003ואמר\u0004 \u0005[ויאמר]:\u0006 \u0003דידי ודידיה\u0004 \u0005[שלי ושלו]\u0006 \u0003הוא.\u0004 ואומרים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאתה חושש לרמאות כזו, \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 כשעושה חזית לחוץ \u0003גייז ליה חבריה\u0004 \u0005[יחתוך אותו חבירו],\u0006 \u0003ואמר\u0004 \u0005[ויאמר]:\u0006 \u0003דידי ודידיה\u0004 \u0005[שלי ושלו]\u0006 \u0003הוא!\u0004 ומשיבים: \u0003גיזוזא מידע ידיע\u0004 \u0005[חיתוך\u0006 כזה \u0005ניכר]\u0006 ואי אפשר לטעות בו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שעל השאלה מהי אותה חזית שנאמרה, \u0003אמר רב הונא: מיכפא לקרנא מלגיו\u0004 \u0005[יכפוף את קצות\u0006 הכותל \u0005מבפנים].\u0006 ושואלים: \u0003ונעבד מלבר\u0004 \u0005[ושיעשה מבחוץ]!\u0006 ומשיבים: \u0003גייז ליה חבריה\u0004 \u0005[יגזוז אותו חבירו],\u0006 \u0003ואמר\u0004 \u0005[ויאמר]:\u0006 \u0003דידי ודידיה\u0004 \u0005[שלי ושלו]\u0006 \u0003הוא.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאתה חושש לרמאות מעין זו, \u0003השתא נמי לייף ליה חבריה\u0004 \u0005[עכשיו גם כן יוסיף,\u0006 יחבר \u0005חבירו\u0006 חזית מצידו\u0005],\u0006 \u0003ואמר\u0004 \u0005[ויאמר]:\u0006 \u0003דידי ודידיה\u0004 \u0005[שלי ושלו]\u0006 \u0003הוא!\u0004 ומשיבים: \u0003ליפופא מידע ידיע\u0004 \u0005[תוספת נודעת,\u0006 ניכרת היא\u0005].\u0006 ושואלים על לשון זו: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"מבחוץ\" קתני\u0004 \u0005[שנה]\u0006 ולא מבפנים! ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","\u0003ר' יוחנן אמר:\u0004"],["\u0003נשעייה באמתא מלבר\u0004 \u0005[שיטוח אותו\u0006 בטיט \u0005באמה\u0006 בראש הכותל \u0005מבחוץ].\u0006 ושואלים: \u0003וניעבד מלגיו\u0004 \u0005[ושיעשה\u0006 זאת \u0005מבפנים]!\u0006 ומשיבים: \u0003עביד חבריה מלבר\u0004 \u0005[יעשה חבירו\u0006 גם כן \u0005מבחוץ],\u0006 בצד הפנימי שלו, \u0003ואמר\u0004 \u0005[ויאמר]:\u0006 \u0003דידי ודידיה\u0004 \u0005[שלי ושלו]\u0006 \u0003הוא.\u0004 ואומרים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003השתא נמי דקפיל ליה חבריה, ואמר: דידי ודידיה\u0004 \u0005[עכשיו גם כן,\u0006 שטח מבחוץ, \u0005הרי יכול\u0006 \u0005חבירו לקלף אותו, ויאמר: שלי ושלו]\u0006 \u0003הוא!\u0004 ומשיבים: \u0003קילופא מידע ידיע\u0004 \u0005[קילוף נודע,\u0006 ניכר הוא\u0005].\u0006","ושואלים: אם עשה את הגדר ב\u0003הוצא\u0004 (בענפי דקל), כיצד עושים חזית? \u0003אמר רב נחמן: סינופי יריכי מלבר\u0004 \u0005[\u0006שם את \u0005ראשי הענפים כלפי חוץ].\u0006 ושואלים: \u0003וניעבד מלגיו\u0004 \u0005[ושיעשה בפנים]!\u0006 ומשיבים: \u0003עביד נמי חבריה מלבר\u0004 \u0005[יעשה גם כן חבירו מבחוץ],\u0006 שהוא הצד הפנימי שלו, \u0003ואמר\u0004 \u0005[ויאמר]:\u0006 \u0003דידי ודידיה\u0004 \u0005[שלי ושלו]\u0006 \u0003הוא.\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה חושש, \u0003השתא נמי\u0004 \u0005[עכשיו גם כן],\u0006 לשיטתך שעושה זאת כלפי חוץ, \u0003גייז ושדי ליה\u0004 \u0005[יגזוז ויזרוק אותו],\u0006 \u0003ואמר\u0004 \u0005[ויאמר]:\u0006 \u0003דידי ודידיה\u0004 \u0005[שלי ושלו]\u0006 \u0003הוא!\u0004 ומשיבים: \u0003משריק ליה טינא\u0004 \u0005[טח אותו בטיט]\u0006 את ראשי ענפי הדקל. ואומרים: \u0003השתא נמי אתי חבריה וקליף ליה\u0004 \u0005[עכשיו גם כן יבוא חבירו ויקלוף אותו]\u0006 את הטיט! ומשיבים: \u0003קילופא מידע ידיע\u0004 \u0005[הקילוף נודע\u0006 הוא\u0005].\u0006","ואילו \u0003אביי אמר:\u0004 גדר של \u0003הוצא\u0004 \u0003לית ליה תקנתא\u0004 \u0005[אין לו תקנה]\u0006 להוכיח מי הקים אותה \u0003אלא בשטרא\u0004 \u0005[בשטר]\u0006 שיכתוב חבירו שטר שהמקום והגדר הם של חבירו ולא שלו.","שנינו: \u0003אבל אם עשו מדעת שניהם\u0004 בונים את הכותל באמצע ועושים חזית מכאן ומכאן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא מפרזיקא לרב אשי: לא יעשו לא זה ולא זה! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקום \u0003דקדים חד מנייהו ועבד דידיה\u0004 \u0005[שקדם אחד מהם ועשה\u0006 את \u0005החזית שלו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא עביד חבריה\u0004 \u0005[יעשה חבירו]\u0006 — \u0003אמר\u0004 \u0005[יאמר]:\u0006 \u0003דידיה\u0004 \u0005[שלו]\u0006 \u0003הוא.\u0004","שאלו רבא מפרזיקא: \u0003ו\u0004כי ה\u0003תנא\u0004 במשנה \u0003תקנתא\u0004 \u0005[תקנה]\u0006 כנגד ה\u0003רמאי\u0004 \u0003קא משמע לן\u0004 \u0005[השמיע לנו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003ו\u0004כי \u0003רישא לאו תקנתא\u0004 \u0005[תחילתו\u0006 של דין זה במשנה \u0005לא תקנה]\u0006 \u0003לרמאי הוא?\u0004 שהרי שנה שם שצריך לעשות חזית להיכר!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בשלמא רישא תנא דינא\u0004 \u0005[נניח\u0006 כי \u0005בראש שנה\u0006 את \u0005הדין]\u0006 שבבקעה אם רוצה בונה משל עצמו ובתוך תחומו, \u0003ומשום דינא\u0004 \u0005[הדין]\u0006 \u0003תנא תקנתא\u0004 \u0005[שנה\u0006 גם את \u0005התקנה\u0006 לרמאים\u0005],\u0006 \u0003אלא סיפא\u0004 \u0005[בסוף]\u0006 \u0003דינא קתני דקתני תקנתא\u0004 \u0005[\u0006וכי \u0005דין שנה\u0006 שם \u0005ששונה\u0006 גם \u0005תקנה]?\u0006 \u0003אמר רבינא: הכא בהוצי עסקינן\u0004 \u0005[כאן ב\u0006גדר של \u0005ענפי דקל אנו עוסקים],\u0006 \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003אביי\u0004 ש\u0003אמר:\u0004 \u0003הוצא לית ליה תקנתא\u0004 \u0005[\u0006גדר של \u0005ענפי דקל אין לו תקנה]\u0006 \u0003אלא בשטרא\u0004 \u0005[בשטר],\u0006 ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003בחזית סגיא\u0004 \u0005[מספיק].\u0006","\u0003המקיף את חבירו משלש רוחותיו,\u0004 שהיו לו חלקות אדמה משלושה צדדים סביב חלקתו של חבירו, \u0003וגדר את הראשונה ואת השניה ואת השלישית\u0004 — \u0003אין מחייבין אותו,\u0004 את בעל החצר הפנימית, להשתתף בבנין הגדר, אם אינו רוצה בכך. \u0003ר' יוסי אומר:\u0004 \u0003אם עמד\u0004 \u0003וגדר את\u0004 הרוח \u0003הרביעית\u0004 — \u0003מגלגלין עליו,\u0004 על המוקף, \u0003את הכל\u0004 שישתתף גם בהוצאות בניית הגדרות האחרות.","\u0003אמר רב יהודה אמר שמואל: הלכה כ\u0004שיטת \u0003ר' יוסי,\u0004 ש\u0003אמר: אם עמד וגדר את הרביעית\u0004 — \u0003מגלגלין עליו את הכל.\u0004 ומעירים: \u0003לא שנא\u0004 \u0005[שונה]\u0006 הדין אם \u0003עמד\u0004 ועשה זאת \u0003ניקף\u0004 (המוקף), ו\u0003לא שנא\u0004 \u0005[שונה]\u0006 אם \u0003עמד\u0004 ועשה זאת ה\u0003מקיף.\u0004","\u0003איתמר\u0004 \u0005[נאמר],\u0006 שנחלקו בענין זה אמוראים, \u0003רב הונא אמר:\u0004 כוונת ר' יוסי שמגלגלים עליו את \u0003הכל\u0004 — \u0003לפי מה שגדר,\u0004 כלומר, צריך הניקף להשתתף בתשלום לפי טיב הגדר שבנה חבירו. \u0003חייא בר רב אמר: הכל\u0004 — \u0003לפי דמי\u0004 גדר עשויה מ\u0003קנים בזול\u0004 ולא יותר. שהמוקף יכול לטעון שלא רצה בגדר חזקה מזו. ומנסים להביא ראיה ממה ששנינו במשנה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003המקיף את חבירו משלש רוחותיו, וגדר את הראשונה ואת השניה ואת השלישית\u0004 — \u0003אין מחייבין אותו,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם גדר גם את ה\u0003רביעית\u0004 — \u0003מחייבין אותו. אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005],\u0006 \u0003ר' יוסי אומר: אם עמד וגדר את הרביעית\u0004 — \u0003מגלגלין עליו את הכל;\u0004 ומעתה","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לרב הונא\u0004 ש\u0003אמר\u0004 ש\u0003הכל לפי מה שגדר בה, היינו דאיכא\u0004 \u0005[זהו\u0006 ההבדל \u0005שיש]\u0006 \u0003בין\u0004 שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003ו\u0004שיטת \u0003ר' יוסי,\u0004 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003הכל לפי דמי קנים בזול\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 משלם, \u0003ומה שגדר\u0004 בפועל, שהיה יותר מזה — \u0003לא, ו\u0004אילו \u0003ר' יוסי סבר\u0004 \u0005[סבור]:\u0006 משלם \u0003הכל לפי מה שגדר.\u0004","\u0003אלא לחייא בר רב\u0004 ש\u0003אמר: הכל לפי דמי קנים בזול, מאי איכא\u0004 \u0005[מהו\u0006 ההבדל\u0005]\u0006 \u0003בין\u0004 שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003ל\u0004שיטת \u0003ר' יוסי? אי\u0004 \u0005[אם]\u0006 לדעת התנא הראשון \u0003דמי קנים בזול לא קיהיב ליה\u0004 \u0005[אינו נותן לו],\u0006 \u0003מאי קיהיב ליה\u0004 \u0005[מה הוא נותן לו]?\u0006","ומשיבים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003אגר נטירא איכא בינייהו\u0004 \u0005[שכר שמירה יש ביניהם],\u0006 ובאופן זה נחלקו: ה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003אגר נטירא\u0004 \u0005[שכר שמירה]\u0006 — \u0003אין\u0004 \u0005[כן],\u0006 שכיון שחלקתו נשמרת על ידי הגדר שמסביב, יכול בונה הגדר לתבוע ממנו תשלום עבור שמירה זו, אבל עבור עצם בניית הגדר אפילו \u0003דמי קנים בזול\u0004 — \u0003לא, ו\u0004אילו \u0003ר' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003דמי קנים בזול.\u0004","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 ביחס לרוח \u0003ראשונה שניה ושלישית איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 עבור הרוח ה\u0003רביעית הוא דיהיב ליה\u0004 \u0005[שנותן לו],\u0006 \u0003אבל\u0004 עבור ה\u0003ראשונה שניה ושלישית\u0004 — \u0003לא יהיב ליה\u0004 \u0005[אינו נותן לו],\u0006 \u0003ו\u0004אילו \u0003ר' יוסי סבר\u0004 \u0005[סבור]\u0006 שעבור \u0003ה\u0004\u0003ראשונה שנייה ושלישית נמי יהיב ליה\u0004 \u0005[גם כן נותן לו].\u0006","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 ביחס ל\u0003מקיף וניקף איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סובר: טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה ש\u0003עמד ניקף\u0004 הוא ש\u0003מגלגלין עליו את הכל,\u0004 שהרי במעשיו מוכיח שהוא רוצה במחיצה זו ביניהם, \u0003אבל\u0004 אם \u0003עמד מקיף\u0004 וגדר — \u0003אינו נותן לו אלא דמי רביעית.\u0004","\u0003ור' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003לא שנא\u0004 \u0005[שונה]\u0006 \u0003ניקף ולא שנא\u0004 \u0005[שונה]\u0006 \u0003מקיף, אם עמד וגדר\u0004 אחד מהם את הרוח הרביעית — \u0003מגלגלין עליו את הכל.\u0004","\u0003לישנא אחרינא\u0004 \u0005[\u0006ב\u0005לשון אחרת]\u0006 אמרו כך: לענין \u0003מקיף וניקף איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003אם גדר\u0004 ה\u0003מקיף את הרביעית נמי יהיב ליה\u0004 \u0005[גם כן נותן לו],\u0006 \u0003ו\u0004אילו \u0003ר' יוסי סבר\u0004 \u0005[סבור]:\u0006 דווקא \u0003אם עמד ניקף וגדר את הרביעית הוא דיהיב ליה\u0004 \u0005[שנותן לו],\u0006 ומדוע? — משום \u0003דגלי דעתיה דניחא ליה\u0004 \u0005[שגילה דעתו\u0006 בכך \u0005שנוח לו]\u0006 בגדר, \u0003אבל אם גדר מקיף\u0004 — \u0003לא יהיב ליה מידי\u0004 \u0005[אינו נותן לו דבר],\u0006 שהרי הוא יכול להמשיך ולטעון שאינו מעונין בגדר."],["מסופר: איש אחד בשם \u0003רוניא, אקפיה\u0004 \u0005[הקיף אותו]\u0006 \u0003רבינא\u0004 בגדר \u0003מארבע רוחותיו,\u0004 שהיו לרבינא שדות מכל צידי שדהו של רוניא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי כמה דגדרי\u0004 \u0005[שגדרתי],\u0006 כלומר, שלם את מחצית ההוצאות שהוצאתי לגידור. \u0003לא יהיב ליה\u0004 \u0005[נתן לו].\u0006 אמר לו רבינא: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי\u0004 לפחות \u0003לפי\u0004 דמי \u0003קנים בזול. לא יהיב ליה\u0004 \u0005[נתן לו].\u0006 אמר לו: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי אגר נטירותא\u0004 \u0005[שכר שמירה],\u0006 \u0003לא יהיב ליה\u0004 \u0005[נתן לו].\u0006","\u0003יומא חד הוה קא גדר דיקלי\u0004 \u0005[יום אחד היה\u0006 רוניא \u0005קוצץ דקלים],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא \u0003לאריסיה\u0004 \u0005[לאריסו]:\u0006 \u0003זיל שקול מניה קיבורא דאהיני\u0004 \u0005[לך קח ממנו אשכול של תמרים].\u0006 \u0003אזל לאתויי\u0004 \u0005[הלך\u0006 האריס \u0005להביא\u0006 אותם\u0005],\u0006 \u0003רמא ביה קלא\u0004 \u0005[הרים\u0006 רוניא \u0005קול עליו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003גלית דעתך דמינח ניחא\u0004 \u0005[גילית דעתך שנוח]\u0006 \u0003לך\u0004 בשמירה זו, \u0003לא יהא אלא עיזא בעלמא\u0004 \u0005[עז בלבד]\u0006 שבאה לשם, \u0003מי לא בעי נטירותא\u0004 \u0005[האם אינה צריכה שמירה]\u0006 שלא תאכל מהתמרים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רוניא: \u0003עיזא בעלמא לאו לאכלויי בעיא\u0004 \u0005[עז בלבד האם לא צריך\u0006 רק \u0005לגרש אותה]?\u0006 ואין צורך בגדר. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ולא גברא בעית דמיכלי לה\u0004 \u0005[ואין אתה צריך אדם שיגרש אותה]?\u0006 ואם כן, צריך אתה לשלם שכר עבור זה!","\u0003אתא לקמיה\u0004 \u0005[בא\u0006 לדין \u0005לפני]\u0006 \u0003רבא, אמר ליה\u0004 \u0005[לו]\u0006 רבא לרוניא: \u0003זיל פייסיה במאי דאיפייס\u0004 \u0005[לך פייס אותו\u0006 את רבינא \u0005במה שהתפייס],\u0006 בדמי שמירה בלבד, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 תרצה לשלם כלל, \u0003דאיננא\u0004 \u0005[אדון]\u0006 \u0003לך דינא\u0004 \u0005[דין]\u0006 \u0003כ\u0004דעת \u0003רב הונא אליבא\u0004 \u0005[לפי\u0006 שיטת\u0005]\u0006 \u0003ר' יוסי,\u0004 שתצטרך לשלם דמי מחצית הגדר כפי הסכום שהוציא רבינא.","אגב כך מספרים עוד מעשה ברבינא ורוניא: \u0003רוניא זבן ארעא אמיצרא\u0004 \u0005[קנה קרקע על המצר,\u0006 הגבול\u0005]\u0006 של \u0003רבינא.\u0004 \u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רבינא לסלוקי\u0004 \u0005[לסלק אותו]\u0006 \u0003משום דינא דבר מצרא\u0004 \u0005[דין של בר מצר],\u0006 שהרי רבינא היתה לו קרקע בסמוך לזה, ויש זכות קדימה לבן המצר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ספרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב ייבא לרבינא: אמרי אינשי\u0004 \u0005[אומרים אנשים]\u0006 בפתגם עממי: \u0003ארבעה\u0004 דינרים \u0003לצלא\u0004 \u0005[לעור גדול],\u0006 \u0003ארבעה לצללא\u0004 \u0005[לעור קטן]\u0006 וכיון שגם רוניא היה בר מצר אין אתה יכול לסלק אותו, למרות שהיתה לו רק חלקה קטנה.","\u0003כותל חצר\u0004 שבין שותפים \u0003שנפל\u0004 — \u0003מחייבין אותו,\u0004 את כל אחד מהשותפים, \u0003לבנותו עד\u0004 גובה \u0003ארבע אמות.\u0004 אם לאחר שנבנה הכותל, טוען אחד השותפים שהוא לבדו בנה מכספו ולא רצה השותף השני להשתתף עימו, הרי השני \u0003בחזקת שנתן\u0004 את חלקו, \u0003עד שיביא\u0004 התובע \u0003ראיה\u0004 על חבירו \u0003שלא נתן.\u0004","\u0003מארבע אמות ולמעלן\u0004 — \u0003אין מחייבין אותו,\u0004 את השותף להשתתף בבניה. אבל אם \u0003סמך\u0004 (בנה בסמוך) \u0003לו,\u0004 לכותל שנבנה למעלה מארבע אמות, \u0003כותל אחר\u0004 על מנת לבנות תקרה על גבם, \u0003אף על פי ש\u0004עדיין \u0003לא נתן עליו את התקרה\u0004 — \u0003מגלגלין עליו את הכל\u0004 שכיון שהוא מראה על רצונו להשתמש במה שבנה חבירו, צריך הוא להשתתף בהוצאות בנייתו. ובמקרה של דיון לאחר זמן, הריהו \u0003בחזקת שלא נתן\u0004 את חלקו, \u0003עד שיביא ראיה שנתן\u0004 דמי הוצאות הכותל.","\u0003אמר ריש לקיש:\u0004 מלווה \u0003הקובע זמן לחבירו\u0004 שלווה ממנו, שיפרע לו חובו, \u0003ו\u0004משהגיע הזמן \u0003אמר לו\u0004 הלווה למלווה: \u0003\"פרעתיך בתוך זמני\"\u0004 — \u0003אינו נאמן,\u0004 שאין דרכם של אנשים לשלם לפני המועד, \u0003ולואי שיפרע בזמנו.\u0004 ואילו \u0003אביי ורבא\u0004 חולקים בדבר זה, \u0003דאמרי תרוייהו\u0004 \u0005[שאומרים שניהם]:\u0006 \u0003עביד איניש דפרע בגו זימניה\u0004 \u0005[עשוי אדם שיפרע\u0006 חוב אפילו \u0005בתוך זמנו],\u0006 שכן \u0003זימנין דמתרמו ליה זוזי\u0004 \u0005[פעמים שמזדמנים לו זוזים,\u0006 דינרים\u0005],\u0006 ואז \u0003אמר\u0004 \u0005[אומר]\u0006 הלווה בליבו: \u0003איזיל איפרעיה\u0004 \u0005[אלך ואפרע לו],\u0006"],["\u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ליטרדן\u0004 \u0005[יטריד אותי]\u0006 אחר כך בתביעות ממון כל הזמן.","ומנסים להביא לכך ראיה ממשנתנו, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 כותל חצר שנפל וחייבוהו לבנות עם חבירו — הרי זה \u0003בחזקת שנתן\u0004 את חלקו באבנים, \u0003עד שיביא ראיה שלא נתן.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"פרעתיך בזמני\",\u0004 כלומר, משהושלם הכותל — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שהוא \u0003בחזקת שנתן! אלא לאו דאמר ליה\u0004 \u0005[האם לא\u0006 מדובר \u0005שאומר לו]:\u0006 \u0003\"פרעתיך בתוך זמני\",\u0004 כלומר, תוך כדי הבניה, ועל כך אמרה המשנה שחזקתו שנתן. \u0003אלמא עביד איניש דפרעיה\u0004 \u0005[מכאן\u0006 ש\u0005עשוי אדם שיפרע]\u0006 חוב \u0003בתוך זמניה\u0004 \u0005[זמנו],\u0006 וכשיטת אביי ורבא! ודוחים: \u0003שאני הכא\u0004 \u0005[שונה כאן],\u0006 ש\u0003כל שפא ושפא זימניה\u0004 \u0005[נדבך ונדבך זמנו]\u0006 \u0003הוא,\u0004 שאין זמן קבוע לתשלום זה דווקא בהשלמת העבודה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר מהמשך המשנה: למעלה מארבע אמות, אם סמך לו כותל אחר — מחייבים אותו; \u0003בחזקת שלא נתן, עד שיביא ראיה שנתן.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא דאמר ליה\u0004 \u0005[אם תאמר שאומר לו]:\u0006 \u0003\"פרעתיך בזמני\"\u0004 לאחר שנבנה, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יהא נאמן? \u0003אלא לאו דאמר ליה\u0004 \u0005[האם לא\u0006 מדובר באופן \u0005שאומר לו]:\u0006 \u0003\"פרעתיך בתוך זמני\",\u0004 ולכן אינו נאמן; \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003לא עביד איניש דפרע בגו זימניה\u0004 \u0005[\u0006ש\u0005אין אדם עשוי שיפרע בתוך זמנו]!\u0006 ודוחים: \u0003שאני הכא דאמר\u0004 \u0005[שונה כאן ש\u0006הוא \u0005אומר]:\u0006 \u0003מי יימר דמחייבו לי רבנן\u0004 \u0005[מי יאמר שיחייבו אותי חכמים]\u0006 לשלם עבור כותל זה. ומסתבר שלא פרע כלל\u0005,\u0006 ולכן אינו נאמן.","ולענין הלכה: \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע עבדי\u0004 \u0005[\u0006היו \u0005עושים\u0006 נוהגים\u0005]\u0006 בענין זה \u0003כאביי ורבא. מר בר רב אשי עבד\u0004 \u0005[עשה]\u0006 \u0003כריש לקיש.\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כריש לקיש\u0004 שאין אדם נאמן לומר \"פרעתיך בתוך זמני\", \u0003ו\u0004גובים \u0003אפילו מיתמי\u0004 \u0005[מיתומים]\u0006 על סמך הנחה זו. \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003הבא ליפרע מנכסי יתומים\u0004 — \u0003לא יפרע אלא בשבועה,\u0004 מכל מקום \u0003חזקה\u0004 היא: \u0003לא עביד איניש דפרע בגו זימניה\u0004 \u0005[אין אדם עשוי שיפרע\u0006 חובו \u0005בתוך זמנו].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]\u0006 שאלה זו: אם המלווה, שקבע זמן ללווה לפרעון, \u0003תבעו לאחר זמן\u0004 ולא בזמן הפרעון, \u0003ואמר לו\u0004 הלווה: \u0003\"פרעתיך בתוך זמני\", מהו,\u0004 מה דינו? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 גם \u0003במקום\u0004 (שיש) \u0003חזקה\u0004 כנגד טענתו של אדם, כגון זו שאדם אינו עשוי לפרוע בתוך זמנו, \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 וסומכים על הנימוק של \u0003\"מה לי לשקר\",\u0004 שהרי אם היה רוצה לשקר יכול לומר \"פרעתיך בזמני\", והיה נאמן."],["\u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003במקום חזקה לא אמרינן\u0004 \u0005[אין אנו אומרים,\u0006 סומכים\u0005]\u0006 על הנימוק של \u0003\"מה לי לשקר\"?\u0004 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו שמי שחייבוהו להשתתף בבניית כותל שנפל הריהו \u0003בחזקת שנתן\u0004 חלקו בכותל, \u0003עד שיביא\u0004 זה שתבעו לשלם \u0003ראיה שלא נתן.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 במקרה \u0003שתבעו לאחר זמן\u0004 השלמת בניית הכותל, \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"פרעתיך בזמני\",\u0004 בהשלמת הכותל, \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שהוא בחזקת שנתן! \u0003אלא לאו דאמר ליה\u0004 \u0005[האם לא\u0006 במקרה \u0005שאומר לו]:\u0006 \u0003\"פרעתיך בתוך זמני\"; אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003אפילו במקום חזקה\u0004 שאדם אינו פורע בתוך זמנו \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003\"מה לי לשקר\"!\u0004 ודוחים: \u0003שאני הכא\u0004 \u0005[שונה כאן],\u0006 ש\u0003כל\u0004 בניית \u0003שפא ושפא זמניה\u0004 \u0005[נדבך ונדבך זמנו]\u0006 \u0003הוא,\u0004 שאין זמן הפרעון בסוף הבניה, אלא בכל שלב ושלב חלה עליו חובה להשתתף בהוצאות, והרי זה כאומר \"פרעתיך בזמני\".","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לצד השני, ממה ששנינו בהמשך המשנה: \u0003מארבע אמות ולמעלה\u0004 — \u0003אין מחייבין אותו. סמך לו כותל אחר\u0004 — מחייבים אותו, והריהו בחזקת שלא נתן \u0003עד שיביא ראיה שנתן.\u0004","ויש לברר: \u0003היכי דמי\u0004 \u0005[כיצד היה הדבר בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שתבעו לאחר זמנו, ואמר לו: \"פרעתיך בזמני\", אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 יאמינו לו? \u0003אלא לאו דאמר\u0004 \u0005[האם לא שאומר]:\u0006 \u0003\"פרעתיך בתוך זמני\",\u0004 ועל כך אומרת המשנה שאינו נאמן; \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003במקום חזקה לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003\"מה לי לשקר\"!\u0004 ודוחים: \u0003שאני הכא\u0004 \u0005[שונה כאן],\u0006 \u0003דאמר\u0004 \u0005[שאומר]\u0006 האיש לעצמו: \u0003מי יימר דמחייבי לי רבנן\u0004 \u0005[יאמר שיחייבו אותי חכמים]\u0006 לשלם עבור כותל זה? ובמקרה זה ודאי אינו משלם לפני הזמן. ונמצא שאין הוכחה לשאלה זו ממשנתנו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במסכת שבועות, אמר לחבירו: \u0003\"מנה לי בידך\u0004 שאתה חייב לי \u0003\",\u0004 \u0003אמר לו\u0004 בפני עדים: \u0003\"הין\"\u0004 (כן), \u0003למחר אמר\u0004 \u0003לו: \"תנהו לי\", אם אמר\u0004 הנטען: \u0003\"נתתיו לך\"\u0004 — \u0003פטור,\u0004 אם אמר: \u0003\"אין לך בידי\"\u0004 — \u0003חייב.\u0004","ונברר: \u0003מאי לאו\u0004 \u0005[האם אין\u0006 הכוונה\u0005]\u0006 שמה שאמר \u0003\"נתתיו לך\"\u0004 — \u0003דאמר ליה\u0004 \u0005[שאומר לו]:\u0006 \u0003\"פרעתיך בזמני\",\u0004 ומה שאמר \u0003\"אין לך בידי\"\u0004 — \u0003דאמר ליה\u0004 \u0005[שאומר לו]:\u0006 \u0003\"פרעתיך בתוך זמני\", וקתני\u0004 \u0005[ושנה]:\u0006 \u0003חייב; אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003במקום חזקה לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003\"מה לי לשקר\"!\u0004 ודוחים: \u0003לא, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין לך בידי\"?\u0004 הכוונה היא שאומר: \u0003\"לא היו דברים מעולם\",\u0004 שמעולם לא לויתי, וטעם הדבר שחייב — כמו ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל האומר \"לא לויתי\"\u0004 — \u0003כאומר \"לא פרעתי\" דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 ואם ידוע לנו שלווה — חייב לשלם.","שנינו במשנה: למעלה מארבע אמות אין מחייבים אותו להשתתף בבניית הכותל. אבל אם \u0003סמך\u0004 (בנה בסמוך) \u0003לו כותל אחר\u0004 — \u0003מגלגלין עליו את הכל. אמר רב הונא:\u0004 אם \u0003סמך לפלגא\u0004 \u0005[לחצי]\u0006 הכותל, באורכו או בגובהו — כאילו \u0003סמך לכולה\u0004 \u0005[לכולו]\u0006 ועליו לשלם מחצית הכותל כולו. \u0003ורב נחמן אמר: למאי\u0004 \u0005[למה]\u0006 ש\u0003סמך\u0004 — \u0003סמך, למאי\u0004 \u0005[למה]\u0006 ש\u0003לא סמך\u0004 — \u0003לא סמך.\u0004","ומעירים: \u0003ומודה רב הונא בקרנא ולופתא\u0004 \u0005[בחיבור שבקרן זוית]\u0006 שאם סמך כותלו באופן זה — אינו נחשב כסומך לכל, שאינו עומד להוסיף על מה שסמך. \u0003ו\u0004מן הצד השני \u0003מודה רב נחמן באפריזא ובקבעתא דכשורי\u0004 \u0005[ב\u0006מניח \u0005קורה ומקום שקובעים בו קורות],\u0006 שגם אם אינו משתמש מיד בכל גובה הכותל, הרי זה מורה שרוצה לסמוך לכולו.","ובאשר למה ששנינו במשנה, שלמעלה מארבע אמות הריהו בחזקת שלא נתן את חלקו, \u0003אמר רב הונא: בי כוי\u0004 \u0005[בית חלונות],\u0006 כלומר, החוקק חורים בכותל לצד חבירו כדי שישמשו אותו להניח בהם קורות — \u0003לא הוי\u0004 \u0005[אינו נחשב]\u0006 \u0003חזקה,\u0004 שלמרות שחורים אלה נעשו כדי שיוכל חבירו להניח בהם קורות, אין זו הוכחה שחבירו שילם עבור בנייתו של כותל זה, \u0003ואף על גב דעבד ליה הימלטי\u0004 \u0005[ואף על פי שעשה לו\u0006 מי שבנה את הכותל \u0005תיקון]\u0006 לחלונות אלה. משום \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בונה הכותל: \u0003אמינא\u0004 \u0005[אמרתי]\u0006 בלבי: \u0003לכי פייסת לי\u0004 \u0005[כאשר תפייס אותי]\u0006 ותשלם לי עבור בניית הכותל ותרצה לקבוע בו קורות \u0003לא ליתרע אשיתאי\u0004 \u0005[יתקלקלו היסודות שלי]\u0006 אם תצטרך לעשות בכותל חורים חדשים, ולכן מראש עשיתי שם חורים.","ובענין דומה, הנוגע לזכות שימוש בכותל חבירו, \u0003אמר רב נחמן: אחזיק להורדי\u0004 \u0005[החזיק,\u0006 היתה לו חזקה, \u0005ל\u0006שים במקום \u0005קורות דקות],\u0006 שהניח השכן על גבי הכותל קורות קטנות, והיתה לו חזקה של זכות שימוש זו — \u0003לא אחזיק לכשורי\u0004 \u0005[החזיק לקורות גדולות],\u0006 שלזה לא נתן לו חבירו רשות, ואינו יכול לטעון שכבר יש לו חזקת שימוש בכותל. אבל אם \u0003אחזיק\u0004 \u0003לכשורי\u0004 \u0005[החזיק לקורות גדולות]\u0006 — \u0003אחזיק להורדי\u0004 \u0005[החזיק לקורות דקות].\u0006 \u0003ו\u0004אילו \u0003רב\u0004 \u0003יוסף אמר: אחזיק להורדי\u0004 \u0005[החזיק לקורות דקות]\u0006 — \u0003אחזיק לכשורי\u0004 \u0005[החזיק\u0006 אף \u0005לקורות עבות].\u0006","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, ש\u0003אמר רב נחמן: אחזיק להורדי\u0004 \u0005[החזיק לקורות דקות]\u0006 — \u0003אחזיק לכשורי\u0004 \u0005[החזיק לקורות גדולות],\u0006 החזיק \u0003לכשורי\u0004 \u0005[לקורות גדולות]\u0006 — \u0003אחזיק להורדי\u0004 \u0005[החזיק לקורות דקות].\u0006","ובאותו ענין \u0003אמר רב נחמן: אחזיק לנטפי\u0004 \u0005[\u0006אם \u0005החזיק\u0006 להשתמש בחצר חבירו \u0005למים הנוטפים\u0006 לשם מגגו\u0005]\u0006 — \u0003אחזיק לשפכי\u0004 \u0005[החזיק\u0006 גם \u0005לשופכים]\u0006 לעשות שם מרזב, שאם לא מחה השכן במים היורדים מן הגג לחצירו שלו, כל שכן שהוא מסכים שיעשה השכן מרזב וירדו מים אלו במקום אחד בלבד. אבל אם \u0003אחזיק לשפכי\u0004 \u0005[החזיק לשופכים]\u0006 — \u0003לא אחזיק לנטפי\u0004 \u0005[החזיק לנוטפים].\u0006 \u0003ורב יוסף אמר: אפילו\u0004 אם \u0003אחזיק לשפכי\u0004 \u0005[החזיק לשופכים]\u0006 — \u0003אחזיק לנטפי\u0004 \u0005[החזיק לנוטפים].\u0006","וכדרך שנאמר לענין הקורות, גם בענין זה \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר רב נחמן:\u0004 אם \u0003אחזיק לשפכי\u0004 \u0005[החזיק לשופכים]\u0006 — \u0003אחזיק לנטפי\u0004 \u0005[החזיק\u0006 גם \u0005לנוטפים],\u0006 ואם החזיק \u0003לנטפי\u0004 \u0005[לנוטפים]\u0006 — \u0003אחזיק לשפכי\u0004 \u0005[החזיק לשופכים],\u0006 \u0003אבל לצריפא דאורבני\u0004 \u0005[לגג משופע של ענפי ערבה]\u0006 שהמים נוטפים ממנו לחצר שכינו — \u0003לא\u0004 החזיק. \u0003רב יוסף אמר: אפילו צריפא דאורבני\u0004 \u0005[לגג משופע של ענפי ערבה]\u0006 יכול לעשות. ומעירים: \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003רב יוסף עובדא\u0004 \u0005[מעשה]\u0006 ופסק \u0003בצריפא דאורבני\u0004 \u0005[בגג משופע של ענפי ערבה]\u0006 שמותר לו לעשות, מאחר שכבר הוא מוחזק בזכות לעשות מרזב.","\u0003אמר רב נחמן אמר רבה בר אבוה: המשכיר בית לחבירו\u0004"],["\u0003בבירה גדולה\u0004 (בנין גדול) שיש בו דירות רבות, \u0003משתמש בזיזיה ובכתליה\u0004 של בירה זו \u0003עד\u0004 מרחק \u0003ארבע אמות\u0004 מהדירה שלו, \u0003ו\u0004משתמש \u0003בעובי הכותל במקום שנהגו, אבל בתרבץ אפדני\u0004 \u0005[בגינת נוי]\u0006 שעושים סמוך לבנין — \u0003לא. ורב נחמן דידיה\u0004 \u0005[\u0006משל \u0005עצמו]\u0006 \u0003אמר: אפילו בתרבץ אפדני\u0004 \u0005[בגינת נוי]\u0006 משתמש. \u0003אבל\u0004 ב\u0003רחבה שאחורי הבתים\u0004 — \u0003לא\u0004 משתמש. \u0003ורבא אמר: אפילו רחבה שאחורי הבתים\u0004 משתמש בה.","ועוד בענין חזקת שימוש בכותל שבין שכנים. \u0003אמר רבינא: האי כשורא דמטללתא\u0004 \u0005[קורה זו ש\u0006שימושה לתמוך עליה כיסוי \u0005לצל],\u0006 אם היתה מונחת בכותלו של אחר, \u0003עד תלתין יומין\u0004 \u0005[שלושים יום]\u0006 — \u0003לא הוי\u0004 \u0005[אינה נחשבת]\u0006 \u0003חזקה,\u0004 שסבור בעל המקום שאינה מונחת אלא בדרך ארעי, ולכן לא מחה על דבר זה. \u0003בתר תלתין יומין\u0004 \u0005[אחרי שלושים יום]\u0006 — \u0003הוי\u0004 \u0005[הריהי]\u0006 \u0003חזקה. ואי\u0004 \u0005[ואם]\u0006 \u0003סוכה\u0004 של \u0003מצוה היא, עד שבעה יומין\u0004 \u0005[ימים]\u0006 — \u0003לא הוי\u0004 \u0005[אינה נחשבת]\u0006 \u0003חזקה,\u0004 שידוע בו שהוא מקיים אותה רק לצורך המצוה ואחר כך יהרסנה. \u0003בתר\u0004 \u0005[אחרי]\u0006 \u0003שבעה יומין\u0004 \u0005[ימים]\u0006 — \u0003הוי\u0004 \u0005[הריהי]\u0006 \u0003חזקה. ואי חבריה בטינא\u0004 \u0005[ואם חיבר אותה בטיט]\u0006 — \u0003לאלתר הוי\u0004 \u0005[מיד הריהי]\u0006 \u0003חזקה.\u0004","אגב הדיון במשנתנו בחיוב לבנות כותל בין שכנים \u0003אמר אביי:\u0004 היו \u0003שני בתים בשני צדי רשות הרבים\u0004 — \u0003זה עושה מעקה לחצי גגו וזה עושה מעקה לחצי גגו,\u0004 ועושים את המעקה \u0003זה שלא כנגד זה, ומעדיף\u0004 (ומוסיף) כל אחד מהם עוד קצת יותר מחצי, כדי שלא יוכלו לראות זה את הנעשה על גגו של זה.","ושואלים: \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע מדובר דווקא\u0005]\u0006 \u0003ברשות הרבים? אפילו\u0004 היתה בין שני הגגות \u0003רשות היחיד נמי\u0004 \u0005[גם כן]\u0006 חייבים לעשות אותו דבר! ומשיבים: \u0003רשות הרבים איצטריכא ליה\u0004 \u0005[הוצרכה לו\u0006 לומר\u0005],\u0006 שכן \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003נימא ליה\u0004 \u0005[שיאמר לו]\u0006 אחד לחבירו: \u0003סוף סוף הא בעית לאצטנועי\u0004 \u0005[הרי צריך אתה להיסתר]\u0006 \u0003מבני רשות הרבים,\u0004 ולכן אתה צריך בין כה וכה לבנות מחיצה, ואינך יכול לחייבני לבנות מעקה לגגי, על כן","\u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין זה כך, משום \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בתשובה על כך: \u0003רבים\u0004 — \u0003ביממא חזו לי\u0004 \u0005[ביום\u0006 שהולכים שם \u0005רואים אותי],\u0006 \u0003בליליא לא חזו לי\u0004 \u0005[בלילה אין רואים אותי],\u0006 ואילו \u0003את\u0004 \u0005[אתה]\u0006 \u0003בין ביממא\u0004 \u0005[ביום]\u0006 \u0003בין בליליא\u0004 \u0005[בלילה]\u0006 \u0003חזית לי\u0004 \u0005[רואה אתה אותי].\u0006 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 נימוק אחר: \u0003רבים\u0004 — רק \u0003כי קאימנא חזו לי\u0004 \u0005[כאשר אני עומד רואים\u0006 הם \u0005אותי]\u0006 מן הרחוב, אבל \u0003כי יתיבנא לא חזו לי\u0004 \u0005[כאשר אני יושב אין\u0006 הם \u0005רואים אותי],\u0006 ואילו \u0003את חזית לי\u0004 \u0005[אתה רואה אותי]\u0006 \u0003בין כי קאימנא\u0004 \u0005[כאשר אני עומד]\u0006 \u0003בין כי יתיבנא\u0004 \u0005[כאשר אני יושב].\u0006 ועוד נימוק: \u0003רבים\u0004 — \u0003כי מעיינו חזו לי, כי לא מעיינו לא חזו לי\u0004 \u0005[כאשר\u0006 הם \u0005מתבוננים רואים\u0006 הם \u0005אותי,\u0006 ואילו \u0005כאשר אינם מתבוננים אינם רואים אותי],\u0006 שהרי סתם אדם אינו מרים עיניו לראות מה מתרחש על הגגות, ואילו \u0003את ממילא נמי חזית לי\u0004 \u0005[אתה מאליך גם כן רואה אותי]\u0006 שהרי אתה שוכן ממולי.","ומעתה דנים בעיקר הדברים ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 אביי: \u0003זה עושה מעקה לחצי גגו וזה עושה מעקה לחצי גגו, זה שלא כנגד זה, ומעדיף.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שזה עושה מחצה וזה מחצה!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דקדים חד מנייהו ועבד\u0004 \u0005[שהקדים אחד מהם ועשה]\u0006 חצי מעקה בעצמו; \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003נימא ליה אידך\u0004 \u0005[\u0006ש\u0005יאמר לו האחר]:\u0006 \u0003שקול אוזינקא ועבדיה את כוליה\u0004 \u0005[טול\u0006 ממני את ההשתתפות ב\u0005הוצאות ועשה אתה\u0006 את \u0005הכל]\u0006 ואז לא נזיק זה לזה בראיה, על כן \u0003קא משמע לן דאמר ליה\u0004 \u0005[השמיע לנו\u0006 שיכול השכן \u0005לומר לו]:\u0006 \u0003את מאי טעמא לא עבדת\u0004 \u0005[אתה מה טעם אינך עושה\u0006 מעקה\u0005]?\u0006 — \u0003משום\u0004 \u0003דמיתרע אשיתך\u0004 \u0005[שמתקלקל יסוד ביתך]\u0006 על ידי כך, \u0003אנא נמי מיתרע ליה אשיתאי\u0004 \u0005[אני גם כן מתקלקל לי יסודי]\u0006 אם אני מוסיף לבנות על הגג.","\u0003אמר רב נחמן אמר שמואל: גג הסמוך לחצר חבירו\u0004 — \u0003עושה לו\u0004 לגג \u0003מעקה גבוה ארבע אמות, אבל בין גג לגג\u0004 — \u0003לא\u0004 צריך לעשות מעקה כלל. \u0003ורב נחמן דידיה\u0004 \u0005[\u0006משל \u0005עצמו]\u0006 \u0003אמר:\u0004 אמנם \u0003אינו זקוק\u0004 לבנות כותל גבוה \u0003ארבע אמות\u0004 בין גג לגג, \u0003אבל זקוק\u0004 הוא \u0003ל\u0004בנות \u0003מחיצת עשרה.\u0004","ושואלים: \u0003למאי\u0004 \u0005[למה]\u0006 הוא עושה זאת? \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004צורך מניעת \u0003היזק ראיה\u0004 — הלא מחיצה בגובה \u0003ארבע אמות בעינן\u0004 \u0005[צריכים אנו].\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004ענין שלא יהיה \u0003נתפס עליו כגנב,\u0004 שצריך לעשות מחיצה כדי שידע עד היכן רשותו, ואם ייכנס האחר שלא ברשות, הריהו בכך נחשב כנכנס לגנוב — \u0003במסיפס בעלמא סגיא\u0004 \u0005[בסבכה\u0006 נמוכה \u0005בלבד די].\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לגדיים וטלאים\u0004 שלא יעברו מגג לגג — הלא במחיצה קטנה \u0003בכדי שלא יזדקר בבת ראש\u0004 (יקפוץ בבת אחת) \u0003סגי\u0004 \u0005[די]!\u0006 ומשיבים: \u0003לעולם\u0004 הוא עושה זאת \u0003ל\u0004צורך שלא יהיה \u0003נתפס עליו כגנב,\u0004 ואולם \u0003במסיפס מצי משתמיט ליה\u0004 \u0005[\u0006כשיש \u0005סבכה\u0006 נמוכה יכול \u0005להשתמט ממנו],\u0006 \u0003אמר\u0004 \u0005[אומר\u0006 הוא\u0005]:\u0006 \u0003ממצורי קממצירנא\u0004 \u0005[מתמתח אני],\u0006 \u0003במחיצת עשרה לא מצי משתמיט ליה\u0004 \u0005[אינו יכול להשתמט ממנו]\u0006 בטענה כזו.","ועל עצם חיוב המחיצה בין חצר לגג \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003אם היה חצרו למעלה מגגו של חבירו\u0004 — \u0003אין נזקקין לו. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא ש\u0003אין נזקקין לו כלל,\u0004 שאינו צריך לעשות מחיצה כלל? ומשיבים: \u0003לא,\u0004 הכוונה היא ש\u0003אין נזקקין ל\u0004עשות מחיצה בגובה \u0003ארבע אמות, אבל נזקקין למחיצת עשרה,\u0004 כדברי רב נחמן.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 היו \u0003שתי חצרות זו למעלה מזו\u0004 — \u0003אמר רב הונא: תחתון בונה מכנגדו ועולה\u0004 בבנין המחיצה עד לגובה חצר חבירו, \u0003ו\u0004כן \u0003עליון בונה מכנגדו ועולה. ורב חסדא אמר: עליון מסייע מלמטה ובונה\u0004 אף במה שהוא כנגד התחתון.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב חסדא: שתי חצרות זו למעלה מזו, לא יאמר העליון: \"הריני בונה מכנגדי ועולה\", אלא מסייע\u0004 גם \u0003מלמטה ובונה. ואם היתה חצרו למעלה מגגו של חבירו\u0004 — \u0003אינו זקוק לו,\u0004 שאין בעל החצר צריך לעשות מחיצה, לפי שאין הגג קבוע לשימוש בני אדם.","מסופר: \u0003הנהו בי תרי דהוו דיירי\u0004 \u0005[שנים שהיו דרים]\u0006 בבית אחד בן שתי קומות, \u0003חד הוה דייר עילאי וחד הוה דייר תתאי\u0004 \u0005[אחד היה דר למעלה ואחד היה דר למטה]\u0006 בבית זה. \u0003איתבר תתאי\u0004 \u0005[נשברה,\u0006 קרסה הקומה \u0005התחתונה],\u0006 ואף שהיא עדיין קיימת מכל מקום הריהי נמוכה עד שלא ניתן לדור תחתיה. \u0003אמר ליה תתאי לעילאי\u0004 \u0005[לו התחתון לעליון]:\u0006 בא נהרוס את הבית כולו ולאחר מכן \u0003תא ונבנייה\u0004 \u0005[בוא ונבנה אותו\u0006 יחד\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא שפיר קא דאירנא\u0004 \u0005[אני יפה אני דר]\u0006 נוח לי, ואיני צריך לבנות את הדירה שלך."],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 התחתון: \u0003איסתריה אנא ואבנייה\u0004 \u0005[אסתור אני\u0006 את הבנין \u0005ואבנהו],\u0006 \u0003אמר\u0004 העליון: \u0003לית לי דוכתא למידר בה\u0004 \u0005[אין לי מקום לדור בו]\u0006 באותו זמן שאתה הורס ובונה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 הדייר של קומת הקרקע: \u0003אנא אוגר\u0004 \u0005[אני אשכיר]\u0006 \u0003לך דוכתא\u0004 \u0005[מקום]\u0006 לגור בו באותו הזמן. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא טרחנא\u0004 \u0005[איני\u0006 רוצה \u0005לטרוח].\u0006 אמר לו התחתון: סוף סוף הלא \u0003לא קא מתדר לי\u0004 \u0005[איני\u0006 יכול \u0005לדור\u0006 שם בדירתי\u0005],\u0006 ששקעה באדמה, ומפני הקומה שאתה גר בה דחוק לי המקום. אמר לו: \u0003שוף אכריסך ועול, ושוף אכריסך ופוק\u0004 \u0005[זחול על כריסך והיכנס, וזחול על כריסך וצא].\u0006","\u0003אמר רב חמא: בדינא קא מעכב\u0004 \u0005[בדין הוא מעכב]\u0006 העליון, ואי אפשר לכפותו. ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים דווקא ש\u0003לא מטו כשורי\u0004 \u0005[הגיעו הקורות\u0006 של הגג\u0005]\u0006 של הקומה התחתונה, שהם בסיס הקומה העליונה, \u0003למטה מעשרה\u0004 טפחים מן הקרקע, \u0003אבל\u0004 אם \u0003מטו כשורי\u0004 \u0005[הגיעו הקורות]\u0006 \u0003למטה מעשרה\u0004 טפחים, \u0003מצי אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 התחתון: \u0003למטה מעשרה רשותא דידי\u0004 \u0005[רשות שלי היא]\u0006 \u0003הוא ולא משעבד\u0004 \u0005[משועבדת]\u0006 \u0003לך\u0004 רשותי להחזיק את דירתך.","ועוד מעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 שיכול העליון לעכב אמורים דווקא בזמן ש\u0003לא אתנו גבי הדדי\u0004 \u0005[התנו זה עם זה]\u0006 שאם ישקע הבית צריכים לבנותו מחדש. \u0003אבל\u0004 אם \u0003אתנו גבי הדדי\u0004 \u0005[התנו זה עם זה]\u0006 — \u0003סתרי ובנו\u0004 \u0005[סותרים ובונים].\u0006","ושואלים: \u0003וכי אתנו בהדי הדדי\u0004 \u0005[וכאשר מתנים זה עם זה]\u0006 \u0003עד כמה\u0004 בונים את הדירה התחתונה? \u0003אמרו רבנן\u0004 \u0005[חכמים]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבה משמיה\u0004 \u0005[משמו]\u0006 של \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן\u0004 ש\u0003אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן, כאותה ששנינו:\u0004 המקבל על עצמו לבנות בית לחבירו, צריך שיהא \u0003רומו\u0004 (גובהו) \u0003כחצי ארכו וכחצי רחבו\u0004 יחד. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבה, לאו אמינא לכו\u0004 \u0005[האם לא אמרתי לכם]:\u0006 \u0003לא תיתלו ביה בוקי סריקי\u0004 \u0005[אל תתלו בו בקבוקים ריקים]\u0006 \u0003ברב נחמן,\u0004 כלומר, אל תתלו בו דברים שאין בהם ממש, שלא אמרם! \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב נחמן: כי דדיירי אינשי\u0004 \u0005[כמו שגרים בני אדם]\u0006 ואין צורך במידות מיוחדות אלה. \u0003וכמה\u0004 הוא שיעור זה? \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: כי היכי דעיילי איסוריתא\u0004 \u0005[כדי שייכנסו\u0006 לתוך הדירה התחתונה \u0005צרורות קנים]\u0006 שעושים ב\u0003מחוזא והדר\u0004 \u0005[ו\u0006אפשר \u0005להסתובב\u0006 בה\u0005]\u0006 וזהו שיעור גובה מספיק.","ועוד מסופר: \u0003ההוא גברא דהוה בני אשיתא אחורי כווי דחבריה\u0004 \u0005[אדם אחד בנה קיר אחורי החלונות של חבירו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קא מאפלת\u0004 \u0005[אתה מאפיל,\u0006 מחשיך\u0005]\u0006 \u0003עלי\u0004 על ידי החומה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003סכרנא\u0004 \u0005[אסתום]\u0006 \u0003לך הכא\u0004 \u0005[כאן]\u0006 את החלונות \u0003ועבידנא\u0004 \u0005[ואעשה]\u0006 \u0003לך כווי\u0004 \u0005[חלונות]\u0006 בקיר שלך \u0003לעיל מאשיתאי\u0004 \u0005[למעלה מהקיר\u0006 שאני עושה\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קא מרעת ליה לאשיתאי\u0004 \u0005[אתה מקלקל\u0006 על ידי פתיחת החלונות \u0005את הקיר שלי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003סתרנא לך לאשיתך\u0004 \u0005[אסתור את קירך]\u0006 \u0003עד דוכתא דכווי\u0004 \u0005[מקום החלונות],\u0006 \u0003ובנינא לה ועבידנא\u0004 \u0005[ואבנה אותו\u0006 מחדש \u0005ואעשה]\u0006 \u0003לך כווי בבנינא לעיל מאשיתאי\u0004 \u0005[חלונות בבנין למעלה מן הקיר שלי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אשיתא מתתאה עתיקא ומלעיל חדתא לא קיימא\u0004 \u0005[קיר שהוא מלמטה ישן ומלמעלה חדש אינו מתקיים]\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003סתרנא לה\u0004 \u0005[אסתור אותו,\u0006 את הקיר\u0005],\u0006 \u0003עד לארעא\u0004 \u0005[הקרקע],\u0006 \u0003ובנינא לה, ועבידנא\u0004 \u0005[ואבנה אותו, ואעשה]\u0006 \u0003לך כווי בגוה\u0004 \u0005[חלונות בו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 השני: \u0003חדא אשיתא חדתא בכוליה ביתא עתיקא לא קיימא\u0004 \u0005[קיר אחד חדש בבית ישן כולו אינו מתקיים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003סתרנא לה לכוליה ביתא, ובנינא\u0004 \u0005[אסתור אותו, את כל הבית, ואבנה]\u0006 \u0003לך כווי בבנינא\u0004 \u0005[חלונות בבנין].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לית\u0004 \u0005[אין]\u0006 \u0003לי דוכתא למידר בה\u0004 \u0005[מקום לדור בו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אגירנא\u0004 \u0005[אשכור]\u0006 \u0003לך דוכתא\u0004 \u0005[מקום]\u0006 לדור בו בינתיים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא טרחנא\u0004 \u0005[איני\u0006 רוצה \u0005לטרוח\u0006 בכך\u0005].\u0006 \u0003אמר רב חמא: בדין קא מעכב\u0004 \u0005[הוא מעכב]\u0006 ואי אפשר לכפותו.","ומתקשים: \u0003היינו הך\u0004 \u0005[הרי זה\u0006 אותו דבר\u0005],\u0006 כעין הענין הקודם בבעל העליה שמעכב מלסתור ולבנות, \u0003והא תו\u0004 \u0005[וזו גם]\u0006 \u0003למה לי\u0004 לחזור ולשנות? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 \u0003דאף על גב דלא\u0004 \u0005[שאף על פי שאינו]\u0006 \u0003משתמש\u0004 באותו בית \u0003אלא תיבנא ובי ציבי בעלמא\u0004 \u0005[\u0006ל\u0005תבן ו\u0006ל\u0005עצים בלבד]\u0006 עדיין יכול לומר שהאפלת החלונות היא נזק לגביו, ובכוחו למנוע מהשני לעשות זאת.","ועוד מעשה: \u0003הנהו בי תרי אחי דפלגי בהדי הדדי\u0004 \u0005[שני אחים שחלקו את\u0006 נכסי אביהם \u0005זה עם זה],\u0006 \u0003חד מטייה אספלידא וחד מטייה תרביצא\u0004 \u0005[האחד הגיע לו טרקלין\u0006 בחלקו \u0005והאחד הגיעה לו הגינה],\u0006 \u0003אזל ההוא דמטייה תרביצא וקא בני אשיתא אפומא דאספלידא\u0004 \u0005[הלך זה שהגיעה\u0006 בחלקו \u0005הגינה ובנה קיר על פי הטרקלין].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אחיו: \u0003קא מאפלת עלי\u0004 \u0005[מאפיל אתה עלי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בדידי קא בנינא\u0004 \u0005[בשלי אני בונה].\u0006 \u0003אמר רב חמא: בדין קאמר ליה\u0004 \u0005[אומר לו]\u0006 ומותר לו לעשות כן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי, מאי שנא מהא דתניא\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 הדבר \u0005מזו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003שני אחין שחלקו\u0004 את נכסי אביהם, \u0003אחד מהן נטל שדה כרם ואחד מהן נטל שדה לבן\u0004 (שדה תבואה) — \u0003יש לו לבעל הכרם ארבע אמות בשדה לבן\u0004 לצורך עבודת הכרם, \u0003שעל מנת כן חלקו.\u0004 מדוע כאן אין לו זכות לבעל הטרקלין להשתמש באור המגיע דרך הגינה?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם דעלו להדדי\u0004 \u0005[שם\u0006 מדובר \u0005שהעריכו\u0006 עשו אומדן \u0005זה לזה]\u0006 בשווי השדות, וחלק מן החישוב הוא מקום העבודה. ושאל רבינא: \u0003אבל הכא מאי\u0004 \u0005[כאן מה],\u0006 האם מדובר באופן ש\u0003לא עלו להדדי\u0004 \u0005[העריכו זה עם זה]?\u0006 \u0003וכי בשופטני עסקינן\u0004 \u0005[בשוטים אנו עוסקים]\u0006 \u0003דהאי שקיל אספלידא והאי שקיל תרביצא ולא עלו להדדי\u0004 \u0005[שזה לוקח טרקלין\u0006 יקר \u0005וזה לוקח גינה\u0006 שהיא זולה בשוויה \u0005ואינם מעריכים זה עם זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נהי דעלו להדדי\u0004 \u0005[אם אמנם שהעריכו זה עם זה]\u0006 את \u0003דמי ליבני כשורי והודרי\u0004 \u0005[הלבנים הקורות והמעזיבה],\u0006 מכל מקום את \u0003דמי אוירא\u0004 \u0005[האויר]\u0006 \u0003לא עלו להדדי\u0004 \u0005[העריכו זה לזה]\u0006 ובענין זה כל אחד יש לו זכות מלאה על שלו.","ואומרים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 בעל הטרקלין: \u0003מעיקרא אספלידא פלגת\u0004 \u0005[מתחילה טרקלין חלקת]\u0006 \u0003לי, השתא משוית לי אידרונא\u0004 \u0005[עכשיו אתה עושה אותו קיטון]!\u0006 \u0003אמר רב שימי בר אשי: שמא בעלמא פלג ליה\u0004 \u0005[שם בלבד חלק לו],\u0006 כלומר, מקום שנקרא טרקלין, אף על פי שאינו משמש עוד ככזה.","\u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר\u0004 לחבירו \u0003\"\u0004שטח של \u0003בית כור עפר אני מוכר לך\", אף על פי שאינו אלא לתך\u0004 (שהוא חצי כור) — \u0003הגיעו,\u0004 כלומר, תפסו בדבריו, ואין המקח בטל, \u0003שלא מכר לו אלא שמא\u0004 \u0005[שם],\u0006 \u0003והוא דמיתקרי\u0004 \u0005[שנקרא]\u0006 מקום זה \u0003\"\u0004\u0003בית כור\".\u0004 וכן אם אומר לו \u0003\"פרדס אני מוכר לך\", אף על פי שאין בו רמונים\u0004 — \u0003הגיעו, שלא מכר לו אלא שמא\u0004 \u0005[שם],\u0006 \u0003והוא דמיתקרי\u0004 \u0005[שנקרא]\u0006 המקום \u0003\"פרדס\".\u0004 וכן אם הוא אומר לו \u0003\"כרם אני מוכר לך\", אף על פי שאין בו גפנים\u0004 — \u0003הגיעו, שלא מכר לו אלא שמא\u0004 \u0005[שם],\u0006 \u0003והוא דמיתקרי \"כרמא\"\u0004 \u0005[שנקרא \"כרם\"]!\u0006","ודוחים: \u0003מי דמי\u0004 \u0005[האם דומים]\u0006 הדברים? \u0003התם מצי אמר ליה\u0004 \u0005[שם יכול לומר לו]\u0006 \u0003מוכר ללוקח\u0004 (לקונה): \u0003שמא זביני\u0004 \u0005[שם מכרתי]\u0006 \u0003לך,\u0004 \u0003הכא מצי אמר ליה\u0004 \u0005[כאן יכול לומר לו]\u0006 בעל הטרקלין: \u0003אדעתא דהכי פלגי, דדאירנא ביה כי היכי דדרו אבהתן\u0004 \u0005[על דעת כך חלקתי\u0006 ולקחתי חלק זה, \u0005שאגור בו כמו שגרו\u0006 בו \u0005אבותינו],\u0006 ולא תשנה אותו על ידי האפלת החלונות.","על דברי רב חמא, שהאח שנטל את החצר רשאי לבנות כותל על פתח הטרקלין, \u0003אמרו ליה\u0004 \u0005[לו]\u0006"],["\u0003מר ינוקא ומר קשישא בריה\u0004 \u0005[בניו]\u0006 של \u0003רב חסדא לרב אשי: נהרדעי לטעמייהו\u0004 \u0005[חכמי נהרדעא\u0006 הולכים \u0005לטעמם,\u0006 לשיטתם\u0005],\u0006 שרב חמא מנהרדעא הולך בשיטת שמואל שהיה גם הוא בן עיר זו. ש\u0003אמר רב נחמן אמר שמואל: האחין שחלקו\u0004 את רכוש אביהם — \u0003אין להן לא\u0004 זכות \u0003דרך זה על זה\u0004 אף שכך השתמשו במקום לפני החלוקה.","\u0003ולא\u0004 זכות \u0003חלונות זה על זה\u0004 למנוע מן האחר לבנות מולם, \u0003ולא\u0004 זכות שימוש ב\u0003סולמות זה על זה, ולא\u0004 להעביר \u0003אמת המים זה על זה\u0004 דרך חלק האח, \u0003והזהרו בהן שהלכות קבועות הן.\u0004 וכשיטה זו סבר גם רב חמא, שכל אחד מהאחים עושה בשלו ואין לשני זכות למנוע בעדו. \u0003ו\u0004אילו \u0003רבא אמר: יש להן\u0004 בכל אלה. מתוך שהוזכרו פסקיו של רב חמא מביאים עוד פסק הלכה בשמו.","\u0003ההוא שטרא דיתמי דנפיק עליה תברא\u0004 \u0005[שטר\u0006 חוב \u0005של יתומים\u0006 שחייבים להם כסף, \u0005שיצא עליו שובר]\u0006 שהוא פרוע, \u0003אמר רב חמא: אגבויי לא מגבינן ליה ומיקרע לא קרעינן ליה\u0004 \u0005[לגבות אין אנו גובים בו\u0006 עבורם \u0005ולקרוע אין אנו קורעים אותו].\u0006 ומסבירים: \u0003אגבויי\u0004 \u0005[לגבות]\u0006 \u0003לא מגבינן ליה\u0004 \u0005[מגבים אנו בו],\u0006 משום \u0003דנפק תברא עליה\u0004 \u0005[שיצא שובר עליו].\u0006 \u0003מיקרע\u0004 \u0005[לקרוע]\u0006 \u0003לא קרעינן ליה\u0004 \u0005[קורעים אנו אותו],\u0006 \u0003דכי גדלי יתמי דילמא מייתו\u0004 \u0005[שכאשר יגדלו היתומים שמא יביאו]\u0006 \u0003ראיה\u0004 שהשובר מזוייף \u0003ומרעי ליה\u0004 \u0005[\u0006\u0005וירעו,\u0006 יבטלו, \u0005אותו],\u0006 את השובר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרבינא: הלכתא מאי\u0004 \u0005[מה ההלכה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בכולהו\u0004 \u0005[בכל]\u0006 המקרים שבסוגייתנו \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרב חמא, לבר מתברא\u0004 \u0005[חוץ מ\u0006ענין \u0005השובר],\u0006 משום \u0003דסהדי בשקרי לא מחזקינן\u0004 \u0005[שעדים כשקרנים אין אנו מחזיקים]\u0006 וכיון שיש עדים החתומים על השובר הזה — סומכים עליהם, וקורעים את השטר.","\u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי אמר: בהא נמי הלכתא\u0004 \u0005[בזו גם כן הלכה]\u0006 \u0003כרב חמא,\u0004 משום שיש כאן צד של ספק חשש לכשרות השובר, \u0003דאם איתא דתברא מעליא\u0004 \u0005[שאם יש\u0006 לומר שאכן \u0005שטר מעולה]\u0006 \u0003הוא\u0004 — \u0003איבעי ליה לאפוקי בחיי אבוהון\u0004 \u0005[היה צריך\u0006 הלווה \u0005להוציא\u0006 אותו עוד \u0005בחיי אביהם],\u0006 \u0003ומ\u0004כיון ש\u0003לא אפקיה\u0004 \u0005[הוציא אותו]\u0006 בשעתו, \u0003שמע מינה זיופי זייפיה\u0004 \u0005[למד מכאן\u0006 ש\u0005זייף אותו],\u0006 ואף שאין זו ראיה גמורה, על כל פנים יש לחשוש לכך.","בני החצר \u0003כופין אותו\u0004 (את כל אחד מבני החצר) \u0003לבנות\u0004 יחד עמם \u0003בית שער\u0004 (מבנה בפתח החצר, בו נמצא השומר) \u0003ודלת לחצר.\u0004 ואילו \u0003רבן שמעון בן גמליאל אומר: לא כל החצרות ראויות לבית שער,\u0004 ויש לדון לפי צורך החצר. וכן בני העיר \u0003כופין אותו\u0004 את כל אחד מבני העיר לשלם מממונו כדי \u0003לבנות לעיר חומה ודלתים ובריח. רבן שמעון בן גמליאל אומר: לא כל העיירות ראויות לחומה.\u0004","ולענין זה, \u0003כמה\u0004 זמן \u0003יהא\u0004 אדם גר \u0003בעיר ויהא\u0004 נידון \u0003כאנשי העיר\u0004 להתחייב להשתתף בהוצאות אלה? — \u0003שנים עשר חדש.\u0004 אבל אם \u0003קנה בה בית דירה\u0004 באותה עיר — \u0003הרי הוא כאנשי העיר מיד.\u0004","על האמור במשנה שואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 מכאן שעשיית \u0003בית שער מעליותא\u0004 \u0005[מעלה\u0006 דבר טוב\u0005]\u0006 \u0003היא? והא ההוא חסידא דהוה\u0004 \u0005[והרי אותו חסיד שהיה]\u0006 \u0003רגיל אליהו דהוה משתעי בהדיה\u0004 \u0005[שהיה מדבר איתו],\u0006 \u0003עבד\u0004 \u0005[עשה]\u0006 אותו חסיד \u0003בית שער, ותו\u0004 \u0005[ושוב]\u0006 \u0003לא משתעי בהדיה\u0004 \u0005[היה מדבר איתו],\u0006 משום שעל ידי כך גורם שהעניים לא יוכלו להיכנס! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 כשעושה בית שער \u0003מגואי\u0004 \u0005[מבפנים]\u0006 בתוך החצר\u0005]\u0006 ואז יכול העני להגיע עד פתח החצר, \u0003הא\u0004 \u0005[זה]\u0006 כשעושה אותו \u0003מבראי\u0004 \u0005[מבחוץ]\u0006 וחוסם לעני את הגישה לפתח החצר.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא מבראי\u0004 \u0005[זה וזה מבחוץ],\u0006 \u0003ולא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא דאית ליה\u0004 \u0005[זה שיש לו\u0006 לבית השער\u0005]\u0006 \u0003דלת, הא דלית ליה\u0004 \u0005[זה שאין לו]\u0006 \u0003דלת. אי בעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003הא והא דאית ליה\u0004 \u0005[זה וזה שיש לו]\u0006 \u0003דלת, ולא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא דאית ליה\u0004 \u0005[זה שיש לו]\u0006 \u0003פותחת\u0004 (מפתח) שרק על ידה ניתן לפתוח את הדלת, \u0003הא דלית ליה\u0004 \u0005[זה שאין לו]\u0006 \u0003פותחת. אי בעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003הא והא דאית ליה\u0004 \u0005[זה וזה שיש לו]\u0006 \u0003פותחת, ולא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שה\u0003פותחת דידיה מגואי\u0004 \u0005[מבפנים]\u0006 ואין העני יכול לפתוח, \u0003הא\u0004 \u0005[\u0006ו\u0005זה]\u0006 שה\u0003פותחת דידיה מבראי\u0004 \u0005[\u0006\u0005שלו מבחוץ].\u0006","שנינו במשנה ש\u0003כופין אותו לבנות בית שער ודלת לחצר. תניא\u0004 \u0005[\u0006\u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: לא כל\u0004 ה\u0003חצרות ראויות לבית שער, אלא, חצר הסמוכה לרשות הרבים\u0004 — היא \u0003ראויה לבית שער,\u0004 שיש טעם בדבר, שלא יהו רבים מסתכלים שם. \u0003ושאינה סמוכה לרשות הרבים\u0004 — \u0003אינה ראויה לבית שער.\u0004 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מדוע אף הם אינם מחלקים כך? ומשיבים: אף כשאין החצר סמוכה לרשות הרבים \u0003זימנין דדחקי\u0004 \u0005[פעמים שנדחקים]\u0006 \u0003בני רשות הרבים ועיילו ואתו\u0004 \u0005[ובאים ונכנסים]\u0006 לחצר.","שנינו במשנה: \u0003כופין אותו לבנות לעיר\u0004 חומה ודלתיים ובריח. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003כופין אותו לעשות לעיר דלתים ובריח. ורבן שמעון בן גמליאל אומר: לא כל העיירות ראויות לחומה, אלא עיר הסמוכה לספר\u0004 — \u0003ראויה לחומה, ושאינה סמוכה לספר\u0004 — \u0003אינה ראויה לחומה.\u0004 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מדוע אף הם אינם מחלקים כך? ומשיבים: אף בעיר שאינה סמוכה לספר \u0003זימנין דמקרו ואתי גייסא\u0004 \u0005[פעמים שמזדמן ובא גיס,\u0006 גדוד צבא\u0005],\u0006 ולכן טוב לעיר שתהיה לה חומה.","ובענין זה \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אלעזר מר' יוחנן: כשהן,\u0004 בני העיר, \u0003גובין\u0004 עבור חומות העיר, \u0003לפי נפשות\u0004 (מספר האנשים) \u0003גובין, או דילמא\u0004 \u0005[שמא]\u0006 \u0003לפי שבח ממון\u0004 (גובה הכסף, הרכוש) שיש לכל אחד מבני העיר \u0003גובין?\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לפי ממון גובין, ואלעזר בני, קבע בה מסמרות,\u0004 כלומר, שכך הלכה פסוקה, ואין להזיזה ממקומה.","\u0003איכא דאמרי בעא מיניה\u0004 \u0005[יש שאומרים\u0006 ש\u0005שאל אותו]\u0006 \u0003ר' אלעזר מר' יוחנן\u0004 כך: \u0003כשהן גובין, לפי קירוב בתים\u0004 לחומה \u0003הן גובין,\u0004 וככל שהבית קרוב יותר לחומה משלם יותר, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003לפי ממון גובין? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לפי קירוב בתים הן גובין,\u0004 \u0003ואלעזר בני, קבע בה מסמרות.\u0004","מסופר: \u0003ר' יהודה נשיאה רמא דשורא אדרבנן\u0004 \u0005[הטיל\u0006 את התשלומים עבור \u0005החומה\u0006 גם \u0005על החכמים],\u0006 \u0003אמר\u0004 לו \u0003ריש לקיש: רבנן לא צריכי נטירותא\u0004 \u0005[חכמים אינם צריכים שמירה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ולי מה יקרו רעיך אל... \u0003אספרם מחול ירבון\"\u0004 (תהלים קלט, יז–יח), ויש לשאול: \u0003אספרם למאן\u0004 \u0005[למי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לצדיקים\u0004 ובא הכתוב לומר \u0003דנפישי מחלא\u0004 \u0005[ש\u0006הם \u0005מרובים מן החול],\u0006 \u0003השתא כולהו\u0004 \u0005[הרי כל]\u0006 \u0003ישראל כתיב בהו\u0004 \u0005[נאמר בהם]:\u0006 \u0003\"כחול אשר על שפת הים\"\u0004 (בראשית כב, יז), \u0003צדיקים עצמם\u0004 שהם חלק מעם ישראל \u0003מחול ירבון?!\u0004 כיצד ייתכן שהם יהיו מרובים יותר?","\u0003אלא הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אספרם למעשיהם של צדיקים\u0004 — \u0003מחול ירבון, ו\u0004מכאן תלמד \u0003קל וחומר: ומה חול ש\u0004הוא \u0003מועט\u0004 — \u0003מגין על\u0004 היבשה מפני \u0003הים,\u0004 שאין הים נכנס ליבשה, \u0003מעשיהם של צדיקים שהם מרובים\u0004 — \u0003לא כל שכן שמגינים עליהם,\u0004 ולפיכך אינם צריכים שמירה.","\u0003כי אתא לקמיה\u0004 \u0005[כאשר בא\u0006 ריש לקיש \u0005לפני]\u0006 \u0003ר' יוחנן\u0004 סיפר לו אותו המעשה, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא תימא ליה מהא\u0004 \u0005[אמרת לו מ\u0006פסוק \u0005זה],\u0006 שנאמר: \u0003\"אני חומה ושדי כמגדלות\"\u0004 (שיר השירים ח, י), וכך פירשוהו: \u0003\"אני חומה\"\u0004 — \u0003זו תורה, \"ושדי כמגדלות\"\u0004 —"],["\u0003אלו תלמידי חכמים?\u0004 ומעירים: \u0003וריש לקיש\u0004 שלא דרש מכאן \u0003סבר לה\u0004 \u0005[סבור\u0006 שיש לפרש \u0005זאת]\u0006 \u0003כ\u0004מו ש\u0003דרש רבא: \"אני חומה\"\u0004 (שיר השירים ח, י) — \u0003זו כנסת ישראל, \"ושדי כמגדלות\"\u0004 (שיר השירים ח, י) — \u0003אלו בתי כנסיות ובתי מדרשות.\u0004","ועל מעשה כגון זה מסופר: \u0003רב נחמן בר רב חסדא רמא כרגא ארבנן\u0004 \u0005[הטיל\u0006 את \u0005תשלום מס הקרקע\u0006 גם \u0005על החכמים],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק: עברת אדאורייתא ואדנביאי ואדכתובי\u0004 \u0005[על התורה ועל הנביאים ועל הכתובים].\u0006","\u0003אדאורייתא\u0004 \u0005[על התורה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אף חבב עמים כל קדשיו בידך\"\u0004 (דברים לג, ג), וכך פירושו, \u0003אמר משה לפני הקדוש ברוך הוא:\u0004 \u0003רבונו של עולם, אפילו בשעה שאתה מחבב עמים\u0004 ונותן להם ממשלה על ישראל — \u0003כל קדושיו\u0004 של ישראל, כלומר, תלמידי החכמים, \u0003יהיו בידך\u0004 בלבד, והם אינם נחשבים תחת שליטת העמים, ופטורים מלהשתתף במס. ויש לפרש כך את המשך הפסוק כעוסק בתלמידי חכמים: \u0003\"והם תכו לרגלך\"\u0004 (דברים לג, ג) — \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: אלו תלמידי חכמים, שמכתתים רגליהם מעיר לעיר וממדינה למדינה ללמוד תורה, \"ישא מדברתיך\"\u0004 (דברים לג, ג) — \u0003לישא וליתן בדבורותיו\u0004 (בדבריו) \u0003של מקום.\u0004","ועוד עברת \u0003אדנביאי\u0004 \u0005[על\u0006 דברי \u0005הנביאים],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"גם כי יתנו בגוים עתה אקבצם ויחלו מעט ממשא מלך ושרים\"\u0004 (הושע ח, י), ועל כך \u0003אמר עולא: פסוק זה בלשון ארמית נאמר,\u0004 ש\"יתנו\" משמעו כמו בארמית: ישנו, ילמדו. וכך צריך להבין אותו: \u0003\"אי תנו\" כולהו\u0004 \u0005[אם ילמדו כולם,\u0006 כל ישראל\u0005]\u0006 — \u0003עתה אקבצם, ואם מעט מהם\u0004 ילמדו — \u0003יחלו\u0004 (יפטרו) \u0003ממשא מלך ושרים\u0004 משמע שאלה שלומדים אין עליהם משא המלך.","ועוד עברת \u0003אדכתובי\u0004 \u0005[על\u0006 דברי \u0005הכתובים],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מנדה בלו והלך לא שליט למרמא עליהם\"\u0004 \u0005[\u0006מיסי \u0005מנדה בלו והלך לא ישלוט להטיל עליהם]\u0006 (עזרא ז, כד) על הכהנים והלויים משמשי המקדש. \u0003ואמר רב יהודה:\u0004 \u0003מנדה\u0004 — \u0003זו מנת המלך,\u0004 מס שנותנים למלך, \u0003בלו\u0004 — \u0003זו כסף גולגלתא\u0004 \u0005[גולגולת],\u0006 \u0003והלך\u0004 — \u0003זו ארנונא,\u0004 מס שמשלמים מפעם לפעם.","מסופר: \u0003רב פפא רמא כריא חדתא איתמי\u0004 \u0005[הטיל\u0006 דמי \u0005כריית\u0006 באר \u0005חדשה\u0006 גם \u0005על היתומים],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי לרב פפא: ודילמא\u0004 \u0005[ושמא]\u0006 \u0003לא מידויל\u0004 \u0005[יישאבו\u0006 שם \u0005מים]\u0006 ונמצא שהיתה זו הוצאה לחינם. ושאר בני העיר שהם מבוגרים יכולים למחול, אבל יתומים אינם מוחלים! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מישקל שקילנא מנייהו\u0004 \u0005[לקחת אני לוקח מהם\u0006 מהיתומים\u0005],\u0006 \u0003אי מידויל\u0004 \u0005[אם יישאבו\u0006 מים\u0005]\u0006 — \u0003מידויל\u0004 \u0005[יישאבו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003מהדרנא לה ניהלייהו\u0004 \u0005[אחזיר אותו,\u0006 את הכסף, \u0005להם].\u0006","\u0003אמר רב יהודה: הכל\u0004 משלמים \u0003לאגלי גפא\u0004 \u0005[ל\u0006בניית \u0005שערי החומות],\u0006 \u0003אפילו מיתמי\u0004 \u0005[מיתומים]\u0006 גובים, \u0003אבל רבנן לא צריכי נטירותא\u0004 \u0005[חכמים אינם צריכים שמירה]\u0006 ולכן הם פטורים מתשלום זה. \u0003הכל\u0004 משלמים \u0003לכריא פתיא\u0004 \u0005[לכריית בורות]\u0006 מים, \u0003אפילו מרבנן\u0004 \u0005[מחכמים]\u0006 דורשים דבר זה, שגם הם נזקקים למים, ולכן צריכים להשתתף בכך. ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא דלא נפקי באכלוזא\u0004 \u0005[שאין יוצאים\u0006 לצורך חפירת הבאר \u0005בהמון]\u0006 לעשות בעצמם את החפירה, אלא רק אוספים כסף, \u0003אבל\u0004 אם \u0003נפקי באכלוזא\u0004 \u0005[יוצאים בהמון]\u0006 לעשות זאת — \u0003רבנן לאו\u0004 \u0005[חכמים לא]\u0006 \u0003בני מיפק באכלוזא נינהו\u0004 \u0005[בני יציאה בהמון הם]\u0006 והם פטורים מעבודה זו.","מסופר: \u0003רבי פתח אוצרות\u0004 שלו \u0003בשני בצורת\u0004 לחלק, \u0003אמר: יכנסו בעלי מקרא, בעלי משנה, בעלי תלמוד, בעלי הלכה, בעלי הגדה\u0004 ויקבלו ממני, \u0003אבל עמי הארץ אל יכנסו. דחק ר' יונתן בן עמרם\u0004 שלא הכירו רבי היטב \u0003ונכנס, אמר לו: רבי, פרנסני! אמר לו\u0004 רבי: \u0003בני, קרית\u0004 במקרא? \u0003אמר לו\u0004 בלשון ענוה: \u0003לאו\u0004 \u0005[לא].\u0006 \u0003שנית? אמר לו: לאו.\u0004 אמר לו רבי: \u0003אם כן, במה\u0004 (בזכות מה) \u0003אפרנסך? אמר לו\u0004 \u0005[לו]:\u0006 \u0003פרנסני ככלב וכעורב\u0004 שגם הם מקבלים אוכל אף כי אינם לומדים. התרגש רבי מן הדברים ו\u0003פרנסיה\u0004 \u0005[פרנס אותו].\u0006","\u0003בתר דנפק\u0004 \u0005[אחרי שיצא]\u0006 ר' יונתן \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבי וקא\u0004 \u0005[והיה]\u0006 \u0003מצטער ואמר: אוי לי שנתתי פתי לעם הארץ!\u0004 \u0003אמר לפניו ר' שמעון בר רבי: שמא יונתן בן עמרם תלמידך הוא, שאינו רוצה ליהנות מכבוד תורה מימיו? בדקו ואשכח\u0004 \u0005[ומצאו]\u0006 שכך באמת היה. ואז \u0003אמר רבי: יכנסו הכל,\u0004 שמא מי שאינו נראה כתלמיד חכם הריהו באמת תלמיד חכם.","ולעצם שיטתו של רבי בענין זה מעירים: \u0003רבי\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבי: אין פורענות בא לעולם אלא בשביל\u0004 (בגלל) \u0003עמי הארץ. כההוא\u0004 \u0005[\u0006כמעשה \u0005זה]\u0006 של \u0003דמי כלילא\u0004 \u0005[מס הכתר]\u0006 \u0003דשדו אטבריא\u0004 \u0005[שהטילו על\u0006 העיר \u0005טבריה],\u0006 \u0003אתו לקמיה\u0004 \u0005[באו\u0006 ראשי העיר \u0005לפני]\u0006 \u0003רבי ואמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ליתבו רבנן בהדן\u0004 \u0005[שיתנו\u0006 גם \u0005החכמים איתנו],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ערוקינן\u0004 \u0005[בורחים אנו]\u0006 ואז יפול התשלום על תלמידי החכמים, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ערוקו\u0004 \u0005[ברחו].\u0006 \u0003ערקו פלגיהון\u0004 \u0005[ברחו מחציתם\u0006 של בני העיר\u0005],\u0006 \u0003דליוה פלגא\u0004 \u0005[ביטלו\u0006 את \u0005חצי\u0006 המס\u0005]\u0006 משאר בני העיר.","\u0003אתו הנהו פלגא קמי\u0004 \u0005[באו אותם חצי\u0006 שנשארו בעיר \u0005לפני]\u0006 \u0003רבי, אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ליתבו רבנן בהדן\u0004 \u0005[שיתנו חכמים איתנו],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא.\u0004 אמרו לו: \u0003ערוקינן\u0004 \u0005[בורחים אנו],\u0006 אמר להם: \u0003ערוקו\u0004 \u0005[ברחו].\u0006 \u0003ערקו כולהו\u0004 \u0005[ברחו כולם],\u0006 \u0003פש ההוא כובס\u0004 \u0005[נשאר כובס אחד]\u0006 שם בעיר, \u0003שדיוה\u0004 \u0005[הטילו]\u0006 את כל המס על ה\u0003כובס.\u0004 \u0003ערק\u0004 \u0005[ברח]\u0006 \u0003כובס, פקע כלילא\u0004 \u0005[בטל\u0006 מס \u0005הכתר].\u0006 \u0003אמר רבי: ראיתם, שאין פורענות בא לעולם אלא בשביל עמי הארץ,\u0004 שהרי משיצאו מן העיר, בטל המס לגמרי.","שנינו במשנה: \u0003וכמה\u0004 זמן \u0003יהא בעיר ויהא כאנשי העיר\u0004 — שנים עשר חודש. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003החמרת והגמלת\u0004 (שיירת חמורים ושיירת גמלים) \u0003העוברת ממקום למקום, ולנה בתוכה\u0004 של עיר הנידחת \u0003והודחה עמהן\u0004 עם בני העיר, שאף הם עבדו עבודה זרה — \u0003הן,\u0004 בני השיירה, \u0003בסקילה,\u0004 כדין כל עובדי עבודה זרה יחידים, \u0003וממונן פלט\u0004 (ניצל) ואינם נידונים כיושבי עיר הנדחת, שדין אנשי עיר הנדחת בסייף, וגם ממונם הולך לאיבוד.","\u0003ואם נשתהו\u0004 בני השיירה \u0003שם\u0004 באותה העיר \u0003שלשים יום\u0004 — הרי \u0003הן\u0004 נידונים \u0003בסייף וממונן אבד\u0004 כשאר בני העיר, והרי שדי בישיבה בעיר שלושים יום כדי להיחשב כבן העיר!","\u0003אמר רבא, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא לבני מתא\u0004 \u0005[זה\u0006 כדי \u0005ל\u0006היחשב לאחד מ\u0005בני העיר]\u0006 — שנים עשר חודש, \u0003הא ליתובי מתא\u0004 \u0005[זה ל\u0006היחשב כאחד מ\u0005תושבי העיר]\u0006 — שלושים יום. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003המודר הנאה מ\"אנשי העיר\", כל שנשתהא שם שנים עשר חדש\u0004 — \u0003אסור ליהנות ממנו,\u0004 נשתהה \u0003פחות מכאן\u0004 — \u0003מותר.\u0004 אם נדר \u0003מ\"יושבי העיר\", כל שנשתהא שם שלשים יום\u0004 — \u0003אסור ליהנות ממנו, פחות מכאן\u0004 — \u0003מותר ליהנות ממנו.\u0004","ושואלים: \u0003ולכל מילי\u0004 \u0005[דבר]\u0006 \u0003מי בעינן\u0004 \u0005[האם צריכים אנו]\u0006 שישב בעיר \u0003שנים עשר חדש? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 היושב בעיר \u0003שלשים יום\u0004 — צריך לשלם \u0003לתמחוי,\u0004 לקערת אוכל שנותנים לעניים, ישב שם \u0003שלשה חדשים\u0004 — נותן כסף \u0003לקופה\u0004 של צדקה, ישב \u0003ששה\u0004 חדשים — נותן \u0003לכסות\u0004 לעניים, ישב \u0003תשעה\u0004 חדשים — נותן \u0003לקבורה\u0004 של עניים, ישב \u0003שנים עשר\u0004 חודש — נותן \u0003לפסי\u0004 (עמודי) \u0003העיר,\u0004 כלומר, הקמת גדירות וכיוצא בזה, להגנה! \u0003אמר ר' אסי אמר ר' יוחנן: כי תנן נמי מתניתין\u0004 \u0005[כאשר שנינו גם כן במשנתנו]\u0006 \u0003שנים עשר חדש\u0004 — \u0003לפסי העיר תנן\u0004 \u0005[שנינו]\u0006 שגובים לצורך חיזוק ושמירה, ולא לדברים אחרים.","\u0003ואמר ר' אסי אמר ר' יוחנן: הכל\u0004 משלמים \u0003לפסי העיר ואפילו מיתמי\u0004 \u0005[מיתומים]\u0006 גובים, \u0003אבל רבנן\u0004 \u0005[חכמים]\u0006 — \u0003לא\u0004 ישלמו, משום \u0003דרבנן לא צריכי נטירותא\u0004 \u0005[שהחכמים אינם צריכים שמירה].\u0006 \u0003אמר רב פפא: לשורא ולפרשאה ולטרזינא\u0004 \u0005[לחומה ולפרש\u0006 בשביל העיר \u0005ולשומר\u0006 הנשק\u0005]\u0006 — \u0003אפילו מיתמי\u0004 \u0005[מיתומים]\u0006 גובים, \u0003אבל רבנן לא צריכי נטירותא\u0004 \u0005[חכמים אינם צריכים שמירה].\u0006 \u0003כללא דמילתא\u0004 \u0005[כללו של הדבר]:\u0006 \u0003כל מילתא דאית להו\u0004 \u0005[דבר שיש להם]\u0006 \u0003הנאה מיניה\u0004 \u0005[ממנו]\u0006 — גובים \u0003אפילו מיתמי\u0004 \u0005[מן היתומים].\u0006","מסופר: \u0003רבה רמא\u0004 \u0005[הטיל]\u0006 בתוך השאר גם תשלום \u0003צדקה\u0004 מסויים \u0003איתמי דבי\u0004 \u0005[על היתומים של בית]\u0006 \u0003בר מריון, אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי, והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רב שמואל בר יהודה: אין פוסקין צדקה על היתומים אפילו לפדיון שבוים\u0004 כיון שאינם חייבים במצוות! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא לאחשובינהו קא עבידנא\u0004 \u0005[אני להחשיב אותם עשיתי]\u0006 כדי שיבואו לכבדם שהם אנשים חשובים הנותנים צדקה הרבה, ולא לטובת העניים.","אגב כך מספרים: \u0003איפרא הורמיז אימיה\u0004 \u0005[אימו]\u0006 של \u0003שבור מלכא\u0004 \u0005[מלך\u0006 פרס\u0005]\u0006 \u0003שדרה ארנקא דדינרי לקמיה\u0004 \u0005[שלחה ארנק דינרים לפני]\u0006 \u0003רב יוסף, אמרה\u0004 לו: \u0003ליהוי\u0004 \u0005[שיהיה]\u0006 \u0003למצוה רבה\u0004 \u0005[גדולה].\u0006 \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב יוסף וקא מעיין\u0004 \u0005[והיה מעיין]\u0006 \u0003בה\u0004 בשאלה זו, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מצוה רבה\"\u0004 \u0005[גדולה]\u0006 שיוכל לקיים בה את התנאי במתנה זו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מדתני\u0004 \u0005[מ\u0006מה \u0005ששנה]\u0006 \u0003רב שמואל בר יהודה: אין פוסקין צדקה על היתומים אפילו לפדיון שבוים, שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי"],["\u0003פדיון שבוים מצוה רבה היא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מנא הא מילתא דאמור רבנן\u0004 \u0005[מנין דבר זה שאמרו חכמים]\u0006 ש\u0003פדיון שבוים מצוה רבה היא? אמר ליה\u0004 \u0005[לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והיה כי יאמרו אליך אנה נצא ואמרת אליהם כה אמר ה' אשר למות למות ואשר לחרב לחרב ואשר לרעב לרעב ואשר לשבי לשבי\"\u0004 (ירמיה טו, ב). \u0003ואמר ר' יוחנן: כל המאוחר בפסוק זה קשה מחבירו.\u0004","\u0003חרב קשה ממות\u0004 רגיל — \u0003אי בעית אימא קרא, ואי בעית אימא סברא\u0004 \u0005[אם תרצה אמור\u0006 מן ה\u0005כתוב, ואם תרצה אמור\u0006 מן ה\u0005סברה].\u0006 \u0003אי בעית אימא סברא\u0004 \u0005[אם תרצה אמור\u0006 מן ה\u0005סברה]:\u0006 \u0003האי קא מינוול והאי לא קא מינוול\u0004 \u0005[זה\u0006 במיתת חרב \u0005מתנוול, וזה\u0006 במיתה רגילה, \u0005אינו מתנוול].\u0006 \u0003ואיבעית אימא קרא\u0004 \u0005[ואם תרצה אמור\u0006 מן ה\u0005כתוב],\u0006 שנאמר: \u0003\"יקר בעיני ה' המותה לחסידיו\"\u0004 (תהילים קטז, טו).","\u0003רעב קשה מחרב\u0004 — \u0003איבעית אימא סברא\u0004 \u0005[אם תרצה אמור סברה\u0006 בדבר\u0005],\u0006 שכן \u0003האי קא\u0004 \u0005[זה]\u0006 \u0003מצטער\u0004 הרבה קודם לכן, \u0003והאי לא קא\u0004 \u0005[וזה אינו]\u0006 \u0003מצטער. איבעית אימא קרא\u0004 \u0005[אם תרצה אמור\u0006 מן ה\u0005כתוב],\u0006 שנאמר: \u0003\"טובים היו חללי חרב מחללי רעב\"\u0004 (איכה ד, ט). \u0003שבי קשה מכולם, דכולהו איתנהו ביה\u0004 \u0005[שכולם נמצאים בו]\u0006 שהרי בשבי יש רעב וחרב ומוות.","אגב הדברים שדיברנו על חלוקת צדקה וכיוצא בהם מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003קופה של צדקה נגבית בשנים\u0004 (על ידי שני אנשים) \u0003ומתחלקת בשלשה\u0004 (על ידי שלושה). \u0003נגבית בשנים\u0004 — \u0003שאין עושים\u0004 שום \u0003שררות\u0004 (מינוי שיש בו שלטון ותוקף) \u0003על הצבור פחות משנים, ומתחלקת בשלשה\u0004 — שצריכים לדון בזה \u0003כדיני ממונות,\u0004 שהרי הגבאים קובעים מי מקבל ומי אינו מקבל, וכמה מקבל כל אחד.","\u0003תמחוי נגבית בשלשה ומתחלקת בשלשה,\u0004 לפי \u0003שגבויה וחלוקה שוים,\u0004 שגובים ומחלקים מן ה\u0003תמחוי בכל יום\u0004 וצריך שיהא השלישי מזומן לחלוקת האוכל. ואילו \u0003קופה\u0004 — מחלקים \u0003מערב שבת לערב שבת,\u0004 פעם בשבוע.","ועוד בהבדלים שביניהם: \u0003תמחוי\u0004 — מתחלק \u0003לעניי עולם,\u0004 כלומר, לכל עני שבא לעיר, \u0003קופה\u0004 — מחלקים רק \u0003לעניי העיר. ורשאים בני העיר לעשות,\u0004 כלומר, להשתמש בכסף ה\u0003קופה\u0004 עבור \u0003תמחוי\u0004 להאכיל לעניים, \u0003ו\u0004לעשות מן ה\u0003תמחוי\u0004 ממה שהם גובים במזונות בפועל \u0003קופה, ו\u0004בכלל הם רשאים \u0003לשנותה לכל מה שירצו\u0004 לשם צדקה לפי הצורך.","\u0003ו\u0004כיוצא בזה \u0003רשאין בני העיר להתנות על המדות\u0004 (סוג המידות) \u0003ועל השערים\u0004 (מחירים קצובים לכל מצרך), \u0003ועל שכר פועלים\u0004 שינתן בעיר זו, \u0003ולהסיע על קיצתן,\u0004 כלומר, לכפות על אותם דברים שהם קוצבים וקובעים זה לזה. עד כאן הברייתא, ומעתה דנים בפרטיה.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אין עושין שררות על הצבור פחות משנים.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב נחמן, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והם יקחו את הזהב\" וגו'\u0004 (שמות כח, ה), ונאמר בלשון רבים \"הם\", ללמדנו שעושים זאת דווקא בשניים.","ומעירים: ענין של \u0003שררות הוא\u0004 ש\u0003לא עבדי\u0004 \u0005[עושים]\u0006 בפחות משנים, \u0003הא הימוני מהימן\u0004 \u0005[אבל לנאמנות נאמן]\u0006 גם יחיד להיות גזבר, שלא נאמר הדבר משום חשש של חוסר נאמנות (שצריכים שישגיחו זה על זה), אלא כלל הוא שלא יהא יחיד עושה שררה על הציבור. \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר הזה \u0003לר' חנינא,\u0004 ש\u0003אמר ר' חנינא: מעשה ומינה רבי שני אחין על הקופה,\u0004 שאף שהם קרובים זה לזה ואינם נאמנים להעיד זה כנגד זה, מכל מקום לא חשש לכך ומינה אותם.","ושואלים: \u0003מאי שררותא\u0004 \u0005[מה השררה]\u0006 בקופה של צדקה? ומשיבים: ש\u0003אמר רב נחמן אמר רבה בר אבוה: לפי שממשכנין על הצדקה,\u0004 כלומר, גובים מאנשים בכוח לצורך צדקה, \u0003ואפילו בערב שבת\u0004 כאשר אנשים טרודים ויכולים לטעון שאין להם זמן וכסף. ומקשים: \u0003איני\u0004 \u0005[האם כן הוא]?\u0006 \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ופקדתי על כל לחציו\"\u0004 (ירמיהו ל, כ), \u0003ואמר ר' יצחק בר שמואל בר מרתא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: ואפילו על גבאי צדקה,\u0004 שאם עושים בכפייה גם הם נקראים \"לוחציו\"!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא דאמיד\u0004 \u0005[זה ש\u0006הוא \u0005עשיר]\u0006 גובים ממנו אפילו בכוח, \u0003הא\u0004 \u0005[זה]\u0006 שהוא \u0003לא אמיד\u0004 \u0005[עשיר]\u0006 ואז הגובה ממנו בכוח הרי הוא בגדר לוחצי ישראל. \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רבא אכפיה\u0004 \u0005[כפה אותו]\u0006 \u0003לרב נתן בר אמי,\u0004 שהיה עשיר, \u0003ושקיל מיניה ארבע מאה זוזי\u0004 \u0005[ולקח ממנו ארבע מאות זוז]\u0006 \u0003לצדקה.\u0004 מתוך שנידונה גביית צדקה מביאים ממה שדרשו חכמים בענין.","נאמר: \u0003\"והמשכלים יזהרו כזהר הרקיע\u0004 ומצדיקי הרבים ככוכבים\u0003\"\u0004 (דניאל יב, ג). \u0003\"המשכלים יזהרו כזהר הרקיע\"\u0004 — \u0003זה דיין שדן דין אמת לאמתו,\u0004 שמכוח הבנתם והשכלתם דנים כראוי, \u0003\"ומצדיקי הרבים ככוכבים לעולם ועד\"\u0004 — \u0003אלו גבאי צדקה\u0004 הגורמים לרבים לעשות צדקה.","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 מה שנאמר \u0003\"והמשכלים יזהרו כזהר הרקיע\"\u0004 — \u0003זה דיין שדן דין אמת לאמתו וגבאי צדקה,\u0004 ומה שנאמר: \u0003\"ומצדיקי הרבים ככוכבים לעולם ועד\"\u0004 — \u0003אלו מלמדי תינוקות.\u0004 ושואלים: \u0003כגון מאן\u0004 \u0005[מי]?\u0006 שהרי לא כל מלמד תינוקות אפשר לקרוא לו בתארי כבוד אלה! \u0003אמר רב: כגון רב שמואל בר שילת.\u0004 ומספרים: ש\u0003רב אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003רב שמואל בר שילת דהוה קאי בגינתא\u0004 \u0005[שהיה עומד בגינה],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שבקתיה להימנותך\u0004 \u0005[עזבת את נאמנותך]\u0006 והזנחת את התלמידים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא תליסר שנין דלא חזיא לי\u0004 \u0005[הרי זה שלוש עשרה שנה שלא ראיתי אותה]\u0006 את גינתי, \u0003והשתא נמי דעתאי עלויהו\u0004 \u0005[ועכשיו גם כן דעתי עליהם,\u0006 על התינוקות\u0005]\u0006 ואגב שבחים אלה שואלים:","\u0003ורבנן מאי\u0004 \u0005[וחכמים מה]\u0006 נאמר עליהם? \u0003אמר רבינא:\u0004 עליהם נאמר \u0003\"ואהביו כצאת השמש בגברתו\"\u0004 (שופטים ה, לא). ושבים לדון בהלכות גביית צדקה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גבאי צדקה אינן רשאין לפרוש זה מזה\u0004 ולגבות כל אחד לעצמו במקום אחר, \u0003אבל פורש\u0004 גבאי מחבירו באותו מקום, כגון \u0003זה\u0004 הולך \u0003לשער\u0004 של הבית \u0003וזה לחנות. מצא\u0004 הגבאי \u0003מעות בשוק\u0004 — \u0003לא יתנם בתוך כיסו\u0004 הפרטי, \u0003אלא נותנן לתוך ארנקי של צדקה, ולכשיבא לביתו יטלם\u0004 משם, כדי שלא יבואו לחשוד בו שלקח לעצמו מכספי הצדקה. \u0003כיוצא בו,\u0004 אם \u0003היה\u0004 גבאי הצדקה \u0003נושה בחבירו מנה\u0004 (מאה דינר) \u0003ופרעו\u0004 חבירו \u0003בשוק\u0004 — \u0003לא יתננו\u0004 את הכסף שהוא מקבל \u0003לתוך כיסו, אלא נותנן לתוך ארנקי של צדקה, ולכשיבא לביתו יטלם.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גבאי צדקה שאין להם עניים לחלק\u0004 ונשאר הכסף בידם — \u0003פורטין,\u0004 כלומר, את פרוטות הנחושת שדרכן להחליד מחליפים בדינרי כסף \u0003לאחרים, ואין פורטין לעצמן\u0004 מפני החשד. וכן \u0003גבאי תמחוי שאין להם עניים לחלק\u0004 להם את המזונות — \u0003מוכרין\u0004 את המזונות \u0003לאחרים ואין מוכרין לעצמן\u0004 מטעם זה. \u0003מעות של צדקה אין מונין אותן שתים\u0004 שתים, \u0003אלא אחת אחת\u0004 שמא תהיה טעות בחשבון, וצריך למנות בדקדוק גדול.","\u0003אמר אביי: מריש\u0004 \u0005[מתחילה]\u0006 \u0003לא הוה יתיב מר אציפי דבי כנישתא\u0004 \u0005[היה יושב אדוני\u0006 מורי רבה, \u0005על המחצלות של בית הכנסת]\u0006 משום שנקנו מכספי קופת צדקה, \u0003כיון\u0004 ש\u0003שמעה להא דתניא\u0004 \u0005[את זו ששנינו\u0006 בברייתא\u0005]\u0006 שרשאים לקחת את הצדקה \u0003ולשנותה לכל מה שירצו, הוה יתיב\u0004 \u0005[היה יושב].\u0006 \u0003אמר אביי: מריש הוה עביד מר תרי כיסי\u0004 \u0005[מתחילה היה עושה אדוני,\u0006 רבה, \u0005שני כיסים],\u0006 \u0003חד\u0004 \u0005[אחד]\u0006 \u0003לעניי דעלמא\u0004 \u0005[העולם]\u0006 לעניים בכלל, \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003לעניי דמתא\u0004 \u0005[העיר],\u0006 \u0003כיון\u0004 ש\u0003שמעה להא דאמר ליה\u0004 \u0005[את זו שאמר לו]\u0006 \u0003שמואל לרב תחליפא בר אבדימי: עביד חד כיסא\u0004 \u0005[עשה כיס אחד\u0006 בלבד\u0005]\u0006"],["\u0003ואתני עלה\u0004 \u0005[והתנה על כך]\u0006 לתת לכל מי שצריך לתת לו, \u0003איהו נמי עבד חד כיסא ואתני עלה\u0004 \u0005[הוא גם כן עשה כיס אחד והתנה עליו].\u0006 \u0003רב אשי אמר: אנא אתנויי נמי לא צריכנא\u0004 \u0005[אני להתנות גם כן איני צריך],\u0006 \u0003דכל דקא אתי אדעתא דידי אתי\u0004 \u0005[שכל שבא\u0006 לתת לקופה זו \u0005על דעתי שלי\u0006 הוא \u0005בא],\u0006 שנותנים לי וסומכים עלי שאחלק כפי שנראה לי, \u0003ולמאן דבעינא יהיבנא ליה\u0004 \u0005[ולמי שאני רוצה אני נותן אותו],\u0006 ואם כן מראש יודעים האנשים שלשם כך הם נותנים.","מסופר: \u0003הנהו בי תרי טבחי דעבדי עניינא בהדי הדדי\u0004 \u0005[שני טבחים,\u0006 שוחטים, \u0005שעשו הסכם זה עם זה],\u0006 ש\u0003כל מאן דעביד ביומא דחבריה נקרעוה למשכיה\u0004 \u0005[מי שיעשה,\u0006 ישחט, \u0005ביום\u0006 השייך \u0005לחבירו\u0006 לפי הימים שקבעו ביניהם, \u0005יקרעו את עורה\u0006 של הבהמה\u0005]\u0006 ששחט באותו יום. \u0003אזל חד מנייהו עבד ביומא דחבריה\u0004 \u0005[הלך אחד מהם\u0006 ו\u0005עשה ביום של חבירו],\u0006 \u0003קרעו למשכיה\u0004 \u0005[את העור שלו].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבא\u0004 לדין, \u0003חייבינהו\u0004 \u0005[חייב אותם]\u0006 \u0003רבא לשלומי\u0004 \u0005[לשלם]\u0006 לזה שקרעו את העור שלו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב יימר בר שלמיא לרבא:\u0004 הרי שנינו שרשאים בני העיר \u0003להסיע על קיצתם,\u0004 כלומר, לקנוס על מה שקבעו! \u0003לא אהדר ליה\u0004 \u0005[השיב לו]\u0006 \u0003רבא\u0004 על כך. \u0003אמר רב פפא: שפיר עבד\u0004 \u0005[יפה עשה]\u0006 ש\u0003לא אהדר ליה מידי\u0004 \u0005[ענה לו דבר],\u0006 כי \u0003הני מילי היכא דליכא\u0004 \u0005[דברים אלה אמורים\u0006 רק במקום \u0005שאין]\u0006 \u0003אדם חשוב\u0004 בעיר, ואז בני העיר רשאים לתקן תקנות לפי דעת עצמם, \u0003אבל היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003אדם חשוב\u0004 — \u0003לאו כל כמינייהו דמתנו\u0004 \u0005[אין זה בכוחם שיתנו],\u0006 אלא צריכים לקבל את הסכמת גדול העיר להתניות אלה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מחשבין בצדקה עם גבאי צדקה\u0004 כמה הכניסו וכמה הוציאו, \u0003ולא בהקדש עם הגזברין\u0004 של ההקדש. \u0003ואף על פי שאין ראיה לדבר\u0004 מן הכתוב — מכל מקום יש \u0003זכר\u0004 (רמז ) \u0003לדבר, שנאמר: \"ולא יחשבו את האנשים אשר יתנו את הכסף על ידם לתת לעשי המלאכה כי באמנה הם עשים\"\u0004 (מלכים ב' יב, טז).","\u0003אמר ר' אלעזר: אף על פי שיש לו לאדם גזבר נאמן בתוך ביתו\u0004 כגזברים אלה שסמכו והאמינו בהם — מכל מקום \u0003יצור\u0004 (יצרור) את הכסף \u0003וימנה\u0004 אותו, \u0003שנאמר\u0004 באותו ענין קודם לכן: \"ויעל סופר המלך והכהן הגדול \u0003ויצרו וימנו\u0004 את הכסף... ונתנו את הכסף המתוכן על ידי עושי המלאכה\" (מלכים ב' יב, יא –יב).","\u0003אמר רב הונא: בודקין\u0004 גבאי צדקה \u0003ל\u0004מי שבא לבקש \u0003מזונות\u0004 אם באמת זקוק הוא לכך, \u0003ואין בודקין לכסות,\u0004 שאם בא אדם שבגדיו קרועים נותנים לו כסות, ואין בודקים. \u0003אי בעית אימא קרא, ואי בעית אימא סברא\u0004 \u0005[אם תרצה אמור\u0006 משום \u0005מקרא, ואם תרצה אמור סברה].\u0006","\u0003אי בעית אימא סברא\u0004 \u0005[אם תרצה אמור סברה],\u0006 \u0003האי קא מבזי והאי לא קא מבזי\u0004 \u0005[זה מבוזה\u0006 בבגדים קרועים \u0005וזה אינו מבוזה].\u0006 \u0003אי בעית אימא קרא\u0004 \u0005[אם תרצה אמור מקרא],\u0006 שנאמר: \u0003\"הלוא פרש לרעב לחמך\"\u0004 (ישעיהו נח, ז), \u0003בשי\"ן כתיב\u0004 \u0005[כתוב],\u0006 שמרמז: \u0003פרש,\u0004 כלומר, חקור ובדוק, \u0003והדר הב ליה\u0004 \u0005[ואחר כך תן לו].\u0006 \u0003והתם כתיב\u0004 \u0005[ושם,\u0006 לענין כסות, \u0005נאמר]:\u0006 \u0003\"כי תראה ערם וכסיתו\"\u0004 (ישעיהו נח, ז), לאמור \u0003\"כי תראה\"\u0004 — \u0003לאלתר\u0004 (מיד) כסהו.","\u0003ו\u0004אילו \u0003רב יהודה אמר:\u0004 להיפך, \u0003בודקין לכסות ואין בודקין למזונות.\u0004 וגם הוא מביא ראיה לדבריו: \u0003אי בעית אימא סברא, ואי בעית אימא קרא\u0004 \u0005[אם תרצה אמור סברה\u0006 בדבר,","\u0005ואם תרצה אמור מקרא].\u0006 \u0003אי בעית אימא סברא\u0004 \u0005[אם תרצה אמור סברה],\u0006 \u0003האי קמצערא ליה והאי לא קמצערא ליה\u0004 \u0005[זה\u0006 הרעב \u0005מצער אותו, וזה,\u0006 הבגד הקרוע, \u0005אינו מצער אותו].\u0006 \u0003אי בעית אימא קרא\u0004 \u0005[אם תרצה אמור מקרא],\u0006 \u0003הכא כתיב\u0004 \u0005[כאן נאמר]:\u0006 \u0003\"הלוא פרס לרעב לחמך\"\u0004 — כוונתו \u0003פרוס לאלתר\u0004 (מיד), \u0003וכדקרינן\u0004 \u0005[וכמו שאנו קוראים]\u0006 פרוס, ולא לפי הכתיב בשי\"ן, \u0003והתם כתיב\u0004 \u0005[ושם נאמר]:\u0006 \u0003\"כי תראה ערם וכסיתו\"\u0004 — \u0003כשיראה לך,\u0004 כשתבדוק את הענין ותראה שמגיע לו. ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב יהודה: אמר\u0004 העני \u0003\"כסוני\u0004 בבגדים \u0003\"\u0004— \u0003בודקין אחריו\u0004 אם אכן הוא צריך לכך, אמר \u0003\"פרנסוני\"\u0004 — \u0003אין בודקין.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם]:\u0006 \u0003אין פוחתין לעני העובר\u0004 \u0003ממקום למקום\u0004 לבקש צדקה, \u0003מ\u0004לתת לו \u0003ככר\u0004 אחת ששווה \u0003פונדיון\u0004 (חלק ארבעים ושמונה בסלע), בזמן שמחיר החטים הוא \u0003ארבע סאין בסלע.\u0004 אם \u0003לן\u0004 העני במקום — \u0003נותנין לו פרנסת לינה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"פרנסת לינה\"? אמר רב פפא: פוריא ובי סדיא\u0004 \u0005[מיטה ומצעות].\u0006 אם \u0003שבת\u0004 במקום — \u0003נותנין לו מזון שלש סעודות\u0004 לשבת. \u0003תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]:\u0006 \u0003אם היה\u0004 העני \u0003מחזיר\u0004 (סובב) \u0003על הפתחים\u0004 עובר מפתח לפתח ומבקש צדקה — \u0003אין נזקקין לו\u0004 לתת לו מן הקופה של צדקה.","מסופר: \u0003ההוא עניא דהוה\u0004 \u0005[עני אחד שהיה]\u0006 \u0003מחזיר על הפתחים דאתא לקמיה\u0004 \u0005[שבא לפני]\u0006 \u0003רב פפא\u0004 שהיה גבאי צדקה, \u0003לא מזדקיק ליה\u0004 \u0005[נזקק,\u0006 נתן \u0005לו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב סמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב ייבא לרב פפא: אי מר\u0004 \u0005[אם אדוני]\u0006 \u0003לא מזדקיק ליה\u0004 \u0005[יזדקק לו],\u0006 כל \u0003אינש אחרינא\u0004 \u0005[אדם\u0006 \u0003אחר]\u0004 גם כן \u0003לא מזדקיק ליה\u0004 \u0005[יזדקק לו],\u0006 וכי \u0003לימות ליה\u0004 \u0005[שימות לו]?!\u0006 ענה לו רב פפא: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אם היה עני המחזיר על הפתחים\u0004 — \u0003אין נזקקין לו! אמר ליה\u0004 \u0005[לו]:\u0006 הכוונה היא ש\u0003אין נזקקין לו למתנה מרובה,\u0004 כיון שהוא מחזיר על הפתחים ומקבל מכל אדם, \u0003אבל נזקקין לו\u0004 על כל פנים \u0003למתנה מועטת.\u0004","\u0003אמר רב אסי: לעולם אל ימנע אדם עצמו מלתת\u0004 לצדקה לפחות \u0003שלישית השקל בשנה, שנאמר: \"והעמדנו עלינו מצו‍ת לתת עלינו שלישית השקל בשנה לעבדת בית אלהינו\"\u0004 (נחמיה י, לג). \u0003ואמר רב אסי: שקולה צדקה כנגד כל המצו‍ת, שנאמר: \"והעמדנו עלינו מצו‍ת\", \"מצוה\" אין כתיב\u0004 \u0005[לא נאמר]\u0006 \u0003כאן, אלא \"מצו‍ת\"\u0004 לשון רבים, לומר שמצוה זו שקולה כנגד כל המצוות.","\u0003(סימן\u0004 להלכות הבאות שנאמרו בשבח הצדקה: \u0003גדול מקדש משה). אמר ר' אלעזר: גדול המעשה,\u0004 כלומר, הגורם לאחרים לעשות, \u0003יותר מן העושה\u0004 עצמו\u0003, שנאמר: \"והיה מעשה הצדקה שלום ועבדת הצדקה השקט ובטח עד עולם\"\u0004 (ישעיהו לב, יז). אם \u0003זכה\u0004 — \u0003\"\u0004\u0003הלוא פרש לרעב לחמך\"\u0004 (ישעיהו נח, ז) שיתן צדקה לעניים בלב טוב, אם \u0003לא זכה\u0004 — \u0003\"ועניים מרודים תביא בית\"\u0004 (ישעיהו נח, ז) שיצטרך להכניס לביתו אנשי צבא שהשלטונות יעמידו בביתו, ויצטרך לפרנסם בעל כרחו.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא לבני מחוזא: במטותא מנייכו, עושו בהדי הדדי\u0004 \u0005[בבקשה מכם, תשתדלו זה עם זה]\u0006 בצדקה ובגמילות חסד, \u0003כי היכי דליהוי לכו שלמא במלכותא\u0004 \u0005[כדי שיהיה לכם שלום במלכות],\u0006 כפי שנאמר כאן שאם אין עושים בצדקה משלמים במקום זה קנסות למלכות. \u0003ואמר ר' אלעזר: בזמן שבית המקדש קיים,\u0004 היה \u0003אדם שוקל שקלו\u0004 לצורך עבודת המקדש \u0003ומתכפר לו, עכשיו שאין בית המקדש קיים, אם עושין צדקה\u0004 — \u0003מוטב, ואם לאו\u0004 — \u0003באין גויים ונוטלין\u0004 את הכסף \u0003בזרוע\u0004 (בכח). ומעירים: \u0003ואף על פי כן נחשב להן\u0004 כסף זה שניטל מהם בכוח \u0003לצדקה, שנאמר: \"ונגשיך צדקה\"\u0004 (ישעיהו ס, יז).","\u0003אמר רבא: האי מילתא אישתעי\u0004 \u0005[דבר זה סיפר]\u0006 \u0003לי עולא\u0004"],["\u0003משגש ארחתיה דאימיה\u0004 \u0005[הצעיר,\u0006 עול הימים, שגרם \u0005לשבש את דרכי אימו]\u0006 \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אלעזר. מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"וילבש צדקה כשרין\"\u0004 (ישעיה נט, יז)? \u0003לומר לך, מה שריון זה\u0004 — \u0003כל קליפה וקליפה\u0004 שממנה נעשה \u0003מצטרפת לשריון גדול, אף צדקה\u0004 — \u0003כל פרוטה ופרוטה\u0004 שנותן \u0003מצטרפת לחשבון גדול. ר' חנינא אמר:\u0004 אותו רעיון נובע \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"וכבגד עדים כל צדקתינו\"\u0004 (ישעיה סד, ה). \u0003מה בגד זה\u0004 — \u0003כל נימא ונימא\u0004 (חוט וחוט) \u0003מצטרפת לבגד גדול, אף צדקה\u0004 — \u0003כל פרוטה ופרוטה מצטרפת לחשבון גדול.\u0004","ומעירים: \u0003אמאי קרו ליה \"עולא משגש ארחתיה דאימיה\"\u0004 \u0005[מדוע קראו לו\u0006 לחכם זה, \u0005הצעיר המשבש את דרכי אימו]?\u0006 — שכך היה מעשה, \u0003דבעא מיניה\u0004 \u0005[ששאל אותו]\u0006 \u0003רב אחדבוי בר אמי מרב ששת: מנין למצורע בימי ספורו,\u0004 בשבעת הימים שהוא סופר לאחר שמתחיל להיטהר, מזמן שמביא צפרים לטהרתו עד שמביא את קרבן הטהרה, \u0003ש\u0004הוא \u0003מטמא אדם? אמר לו: הואיל ומטמא בגדים\u0004 שכן נאמר שביום השביעי לטהרתו מכבס בגדיו (ויקרא יד, ט), \u0003מטמא\u0004 גם \u0003אדם.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אחדבוי: \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003טומאה בחבורים שאני\u0004 \u0005[שונה]\u0006 שבגדים הוא מטמא משום שהם מחוברים לטומאה, אבל אדם שנגע בו לא יטמא. וראיה לדבר: \u0003דהא\u0004 \u0005[שהרי]\u0006 אם \u0003הסיט\u0004 (הזיז ממקומה) \u0003נבילה\u0004 (שנחשב כנושא נבילה ומיטמא, גם אם לא נגע בה) ש\u0003מטמא\u0004 את ה\u0003בגדים ואינו מטמא אדם!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת: \u0003ואלא שרץ\u0004 ש\u0003מטמא אדם מנלן\u0004 \u0005[מנין לנו]\u0006 שהוא מטמא? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 שאנו יודעים ש\u0003מטמא בגדים? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שרץ בהדיא כתיב ביה\u0004 \u0005[בפירוש נאמר בו]:\u0006 \u0003\"או איש אשר יגע בכל שרץ\"\u0004 (ויקרא כב, ה). אמר לו רב ששת: \u0003אלא שכבת זרע\u0004 ש\u0003מטמא אדם מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003הואיל ומטמא בגדים\u0004 הריהו \u0003מטמא אדם? אמר ליה\u0004 \u0005[לו]\u0006 רב אחדבוי: \u0003שכבת זרע נמי בהדיא כתיב ביה\u0004 \u0005[גם כן במפורש כתוב בו],\u0006 שנאמר: \u0003\"או איש\u0004 אשר תצא ממנו שכבת זרע\u0003\"\u0004 (ויקרא כב, ד) — שדרשו חכמים שהמלה \"או\" היא לתוספת, ובאה \u0003לרבות את הנוגע\u0004 בשכבת זרע.","ומספרים: \u0003אהדר ליה בבדיחותא\u0004 \u0005[ענה לו\u0006 רב אחדבוי דברים אלה \u0005בבדיחות\u0006 הדעת\u0005],\u0006 שהיה נראה שהוא כמלגלג על שאינו יודע פסוק. \u0003חלש דעתיה\u0004 \u0005[חלשה דעתו]\u0006 של \u0003רב ששת,\u0004 וכעונש על כך \u0003אישתיק\u0004 \u0005[השתתק,\u0006 נעשה אילם\u0005]\u0006 \u0003רב אחדבוי בר אמי ואתיקר תלמודיה\u0004 \u0005[ונשתכח תלמודו].\u0006 \u0003אתיא אימיה וקא בכיא קמיה\u0004 \u0005[באה אימו\u0006 של רב אחדבוי \u0005ובכתה לפניו],\u0006 לפני רב ששת, \u0003צווחה צווחה ולא אשגח\u0004 \u0005[השגיח]\u0006 \u0003בה. אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003חזי להני חדיי דמצית מינייהו\u0004 \u0005[תראה את אלה השדיים\u0006 שלי \u0005שאתה ינקת מהם],\u0006 שהיא היתה המניקה שלו. כיון ששמע כך \u0003בעא רחמי עליה ואיתסי\u0004 \u0005[ביקש רחמים עליו והתרפא].\u0006 וכיון שגרם רב אחדבוי דבר זה לאימו היו קוראים לו מאז \"הצעיר המשבש אורחות אימו\".","ומעירים: \u0003ודאתאן עלה\u0004 \u0005[\u0006וכיון \u0005ש\u0006כבר \u0005הגענו אליה\u0006 לשאלה זו\u0005],\u0006 \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 שהמצורע בימי ספורו מטמא אדם? — \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן יוחי אומר: נאמר כבוס בגדים בימי ספורו, ונאמר כבוס בגדים בימי חלוטו\u0004 (כשהוא מצורע מוחלט), \u0003מה להלן\u0004 בהיותו מצורע מוחלט \u0003מטמא אדם\u0004 כמפורש בתורה — \u0003אף כאן\u0004 בימי ספורו \u0003מטמא אדם.\u0004","ושוב בענייני צדקה, \u0003אמר ר' אלעזר: גדול העושה צדקה בסתר יותר ממשה רבינו,\u0004 ש\u0003אילו במשה רבינו כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"כי יגרתי מפני האף והחמה\"\u0004 (דברים ט, יט), \u0003ואילו בעושה צדקה כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"מתן בסתר יכפה אף ושחד בחק חמה עזה\"\u0004 (משלי כא, יד). ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 אימרה זו על זו שאמר \u0003ר' יצחק.\u0004 ש\u0003אמר ר' יצחק:\u0004 את ה\u0003אף כופה\u0004 מתן בסתר, אבל \u0003חמה אינו כופה, שנאמר: \"ושחד בחק חמה עזה\",\u0004 לומר: \u0003אף על פי ששוחד בחיק\u0004 שהוא נותן כסף לצדקה בסתר (\"בחיק\") — בכל זאת \u0003חמה עזה\u0004 יכולה להזיק לו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, \u0003אמר ר' יצחק: כל דיין שנוטל שחד\u0004 — \u0003מביא חמה עזה לעולם, שנאמר: \"ושחד בחק\u0004 חמה עזה\u0003\".\u0004","\u0003ואמר ר' יצחק: כל הנותן פרוטה לעני\u0004 — \u0003מתברך בשש ברכות, והמפייסו בדברים,\u0004 שמנחם אותו ומדבר אליו דברים טובים — \u0003מתברך באחת עשרה ברכות.\u0004 ומפרטים: \u0003הנותן פרוטה לעני מתברך בשש ברכות, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הלוא פרש\u0004 לרעב לחמך \u0003ועניים מרודים תביא בית כי תראה ערם\" וגו'\u0004 (ישעיה נח, ז), ונאמר בהמשך \"אז יבקע כשחר אורך, וארוכתך מהרה תצמח, והלך לפניך צדקך, כבוד ה' יאספך. אז תקרא וה' יענה, תשוע ויאמר הנני\" (ישעיה נח, ח–ט).","\u0003והמפייסו בדברים מתברך באחת עשרה ברכות, שנאמר:\u0004 מי שמקיים \u0003\"ותפק לרעב נפשך ונפש נענה תשביע\"\u0004 (ישעיה נח, י) עליו נאמר: \u0003\"וזרח בחשך אורך ואפלתך כצהרים. ונחך ה' תמיד והשביע בצחצחות נפשך\" וגו'\u0004 עד \u0003\"\u0004\u0003ובנו ממך חרבות עולם מוסדי דור ודור תקומם\"\u0004 (ישעיה נח, י–יב).","\u0003ואמר ר' יצחק, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"רודף צדקה וחסד ימצא חיים צדקה וכבוד\"\u0004 (משלי כא, כא)? וכי \u0003משום\u0004 שהוא \u0003רודף צדקה\u0004 לכן הוא \u0003ימצא צדקה?\u0004 שלכאורה משמע שלבסוף ייעשה עני ויעשו אחרים עמו צדקה. \u0003אלא לומר לך: כל הרודף אחר צדקה\u0004 שנותן וגורם לאחרים לתת — \u0003הקדוש ברוך הוא ממציא לו מעות ועושה בהן צדקה.\u0004","\u0003רב נחמן בר יצחק אמר\u0004 באופן אחר: \u0003הקדוש ברוך הוא ממציא לו בני אדם המהוגנים לעשות להן צדקה, כדי לקבל עליהם שכרו.\u0004 ומעירים: הדבר הזה \u0003לאפוקי מאי\u0004 \u0005[להוציא.\u0006 למעט את \u0005מה]\u0006 הוא בא? \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004מה שהוזכר במה ש\u0003דרש רבה\u0004 בענין אחר. ש\u0003דרש רבה, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ויהיו מכשלים לפניך בעת אפך עשה בהם\"\u0004 (ירמיה יח, כג)? — \u0003אמר ירמיה לפני הקדוש ברוך הוא: רבונו של עולם,\u0004 אותם אנשי ענתות שרדפוהו ברשעתם \u0003אפילו בשעה שכופין את יצרן ומבקשין לעשות צדקה לפניך, הכשילם בבני אדם שאינן מהוגנין\u0004 (רמאים), \u0003כדי שלא יקבלו עליהן שכר\u0004 על שנתנו להם צדקה.","\u0003ר' יהושע בן לוי אמר: כל הרגיל לעשות צדקה\u0004 — \u0003זוכה, הויין\u0004 \u0005[יהיו]\u0006 \u0003לו בנים בעלי חכמה, בעלי עושר, בעלי אגדה.\u0004 ומפרשים: \u0003בעלי חכמה, דכתיב\u0004 \u0005[שנאמר]:\u0006"],["\u0003\"\u0004רודף צדקה וחסד \u0003ימצא חיים\"\u0004 (משלי כא, כא), ולענין חכמה כתוב \"כי מוצאי מצא חיים\" (משלי ח, לה). \u0003בעלי עושר, דכתיב\u0004 \u0005[שנאמר\u0006 שם\u0005]:\u0006 \u0003\"צדקה\"\u0004 שיוכלו לתת צדקה. \u0003בעלי אגדה, דכתיב\u0004 \u0005[שנאמר\u0006 שם\u0005]:\u0006 \u0003\"וכבוד\",\u0004 ומנין שהכוונה לבעלי אגדה? \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"וכבוד\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"כבוד חכמים ינחלו\"\u0004 (משלי ג, לה).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003היה ר' מאיר אומר, יש לו לבעל הדין להשיבך ולומר לך: אם אלהיכם אוהב עניים הוא, מפני מה אינו מפרנסן\u0004 בעצמו? \u0003אמור לו: כדי שניצול אנו בהן מדינה של גיהנם\u0004 שאנו זוכים במצוות על ידם, שאנו נעשים שליחיו לפרנס אותם. \u0003וזו שאלה שאל טורנוסרופוס הרשע את ר' עקיבא: אם אלהיכם אוהב עניים הוא, מפני מה אינו מפרנסם? אמר לו: כדי שניצול אנו בהן\u0004 בגלל הצדקה \u0003מדינה של גיהנם.\u0004","\u0003אמר לו: אדרבה, זו\u0004 הצדקה \u0003שמחייבתן\u0004 את ישראל \u0003לגיהנם\u0004 על שהם עושים כן! \u0003אמשול לך משל, למה הדבר דומה? למלך בשר ודם שכעס על עבדו וחבשו בבית האסורין, וצוה עליו\u0004 (אודותיו) \u0003שלא להאכילו ושלא להשקותו, והלך אדם אחד והאכילו והשקהו, כששמע המלך\u0004 וכי \u0003לא כועס עליו? ואתם\u0004 הרי \u0003קרוין עבדים, שנאמר: \"כי לי בני ישראל עבדים\"\u0004 (ויקרא כה, נה), ואם גזר הקדוש ברוך הוא על אדם שיהיה במחסור, נמצא שהנותן לו צדקה עובר על רצון הבורא!","\u0003אמר לו ר' עקיבא: אמשול לך משל\u0004 הפוך: \u0003למה הדבר דומה? למלך בשר ודם שכעס על בנו וחבשו בבית האסורין, וצוה עליו שלא להאכילו ושלא להשקותו, והלך אדם אחד והאכילו והשקהו, כששמע המלך\u0004 על כך, האם כתגובה \u0003לא דורון\u0004 (מתנה) \u0003משגר\u0004 (שולח) \u0003לו? ואנן\u0004 \u0005[ואנו]\u0006 \u0003קרוין בנים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בנים אתם לה' אלהיכם\"\u0004 (דברים יד, א)!","\u0003אמר לו\u0004 טורנוסרופוס: \u0003אתם קרוים בנים וקרוין עבדים, בזמן שאתם עושין רצונו של מקום\u0004 (הקדוש ברוך הוא) \u0003אתם קרוין בנים, ובזמן שאין אתם עושין רצונו של מקום אתם קרוין עבדים, ועכשיו אין אתם עושים רצונו של מקום\u0004 ונמצא שהמשל שאני נתתי מתאים יותר! \u0003אמר לו\u0004 ר' עקיבא, \u0003הרי הוא אומר: \"הלוא פרס לרעב לחמך ועניים מרודים תביא בית\"\u0004 (ישעיהו נח, ז), \u0003אימתי\u0004 מתי מתקיים \u0003\"עניים מרודים תביא בית\"?\u0004 — \u0003האידנא\u0004 \u0005[עכשיו]\u0006 שצריכים להחזיק את החיילים הרומאיים בבתינו, \u0003וקאמר\u0004 \u0005[ונאמר]\u0006 על אותה שעה עצמה: \u0003\"הלוא פרס לרעב לחמך\".\u0004","\u0003דרש ר' יהודה בר' שלום: כשם שמזונותיו של אדם קצובין לו מראש השנה\u0004 בזמן שגוזר הקדוש ברך הוא את דינו לכל השנה, \u0003כך חסרונותיו של אדם קצובין לו מראש השנה\u0004 כמה כסף יפסיד. אם \u0003זכה\u0004 — \u0003\"הלוא פרס לרעב לחמך\"\u0004 הוא מוציא את סכום הכסף שנגזר עליו להוציא לצורך צדקה, \u0003לא זכה\u0004 — \u0003\"ועניים מרודים תביא בית\".\u0004","ומספרים: \u0003כי הא דבני אחתיה\u0004 \u0005[כמו\u0006 מעשה \u0005זה שבני אחותו]\u0006 של \u0003רבן יוחנן בן זכאי חזא להו בחילמא דבעו למיחסר שבע מאה דינרי\u0004 \u0005[ראה עליהם בחלום ש\u0006הם \u0005צריכים להיחסר,\u0006 להפסיד, במשך השנה \u0005שבע מאות דינרים],\u0006 \u0003עשינהו, שקל מינייהו\u0004 \u0005[כפה אותם,\u0006 ו\u0005לקח מהם\u0006 ממון\u0005]\u0006 \u0003לצדקה, פוש גבייהו שיבסר דינרי\u0004 \u0005[נשארו אצלם שבעה עשר דינרים]\u0006 מאותם שבע מאות, שלא לקח מהם. \u0003כי מטא מעלי יומא דכיפורי\u0004 \u0005[כאשר הגיע ערב יום הכיפורים],\u0006 \u0003שדור דבי\u0004 \u0005[שלחו מבית]\u0006 ה\u0003קיסר נקטינהו\u0004 \u0005[ולקחו מהם]\u0006 שבעה עשר דינרים.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבן יוחנן בן זכאי: לא תדחלון\u0004 \u0005[אל תפחדו]\u0006 שמא יקחו מכם עוד, \u0003שיבסר דינרי גבייכו שקלינהו מינייכו\u0004 \u0005[שבעה עשר דינרים\u0006 שנשארו \u0005אצלכם\u0006 אותם \u0005לקחו מכם].\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו ליה]:\u0006 \u0003מנא ידעת\u0004 \u0005[מניין יודע אתה]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003חלמא חזאי לכו\u0004 \u0005[חלום ראיתי עליכם],\u0006 וסיפר להם את חלומו. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003לא אמרת לן דניתבינהו\u0004 \u0005[לנו שהיינו נותנים אותם]\u0006 לצדקה? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אמינא, כי היכי דתעבדו\u0004 \u0005[אמרתי, כדי שתעשו]\u0006 \u0003מצוה לשמה,\u0004 שאם הייתם יודעים מראש לא היתה המצוה לגמרי לשמה.","מסופר: \u0003רב פפא הוה סליק בדרגא\u0004 \u0005[היה עולה בסולם],\u0006 \u0003אישתמיט כרעיה בעי למיפל\u0004 \u0005[נשמטה רגלו\u0006 ו\u0005עמד ליפול],\u0006 \u0003אמר: השתא כן איחייב מאן דסני לן\u0004 \u0005[עכשיו כך התחייב מי ששונא אותנו],\u0006 כלומר, בלשון נקייה, והתכוון לומר: אני, \u0003כמחללי שבתות וכעובדי עבודה זרה\u0004 שמיתתם בסקילה?! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003חייא בר רב מדפתי לרב פפא: שמא עני בא לידך ולא פרנסתו\u0004 ומשום כך הראו לך שאתה ראוי לעונש זה.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהושע בן קרחה אומר: כל המעלים עיניו מן הצדקה\u0004 — \u0003כאילו עובד עבודה זרה,\u0004 ומנין? — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"השמר לך פן יהיה דבר עם לבבך בליעל...\u0004 ורעה עיניך באחיך האביון ולא תתן לו\u0003\"\u0004 (דברים טו, ט), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"יצאו אנשים בני בליעל...\u0004 וידיחו את יושבי עירם לאמר נלכה ונעבדה אלהים אחרים\u0003\"\u0004 (דברים יג, יד), \u0003מה להלן\u0004 \"בני בליעל\" כוונתו עובדי \u0003עבודה זרה, אף כאן\u0004 עובד \u0003עבודה זרה.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' אלעזר בר' יוסי: כל צדקה וחסד שישראל עושין בעולם הזה,\u0004 הריהם עושים בכך \u0003שלום גדול\u0004 \u0003ו\u0004מעמידים \u0003פרקליטין\u0004 (סניגורים) \u0003גדולין בין ישראל לאביהן שבשמים, שנאמר: \"כה אמר ה' אל תבא בית מרזח ואל תלך לספוד ואל תנד להם כי אספתי את שלומי מאת העם הזה\u0004 נאום ה' \u0003את החסד ואת הרחמים\"\u0004 (ירמיה טז, ה), \u0003\"חסד\"\u0004 — \u0003זו גמילות חסדים, \"רחמים\"\u0004 — \u0003זו צדקה.\u0004 ומכאן שכשיש בהם חסד ורחמים — יש עמהם שלום.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: גדולה צדקה שמקרבת את הגאולה, שנאמר: \"כה אמר ה' שמרו משפט ועשו צדקה כי קרובה ישועתי לבוא וצדקתי להגלות\"\u0004 (ישעיה נו, א). \u0003הוא היה אומר: עשרה דברים קשים נבראו בעולם,\u0004 זה קשה מזה. \u0003הר\u0004 שהוא \u0003קשה\u0004 — \u0003ברזל\u0004 שהוא קשה ממנו \u0003מחתכו, ברזל קשה\u0004 — \u0003אור\u0004 (האש) \u0003מפעפעו\u0004 (מתיך אותו), \u0003אור קשה\u0004 — \u0003מים מכבין אותו, מים קשים\u0004 — \u0003עבים\u0004 (עננים) \u0003סובלים\u0004 (נושאים) \u0003אותן, עבים קשים\u0004 — \u0003רוח מפזרתן, רוח קשה\u0004 — \u0003גוף\u0004 האדם \u0003סובלו\u0004 יכול להכילו, \u0003גוף קשה\u0004 — \u0003פחד שוברו, פחד קשה\u0004 — \u0003יין מפיגו, יין קשה\u0004 — \u0003שינה מפכחתו, ומיתה\u0004 — \u0003קשה מכולם\u0004 מכל הדברים הללו. \u0003[וצדקה\u0004 — \u0003מצלת מן המיתה], דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וצדקה תציל ממות\"\u0004 (משלי י, ב. משלי יא, ד).","\u0003דרש ר' דוסתאי בר' ינאי: בוא וראה שלא כמדת הקדוש ברוך הוא מדת בשר ודם; מדת בשר ודם, אדם מביא דורון\u0004 (מתנה) \u0003גדול למלך\u0004 — \u0003ספק מקבלין אותו הימנו, ספק אין מקבלין אותו הימנו, [ואם תמצא לומר מקבלים אותו ממנו] ספק\u0004 לבסוף \u0003רואה פני המלך, ספק אינו רואה פני המלך. והקדוש ברוך הוא אינו כן, אדם נותן\u0004 אפילו \u0003פרוטה לעני\u0004 — \u0003זוכה ומקבל פני שכינה, שנאמר: \"אני בצדק אחזה פניך אשבעה בהקיץ תמונתך\"\u0004 (תהלים יז, טו).","ומסופר: \u0003ר' אלעזר יהיב\u0004 \u0005[היה נותן]\u0006 \u0003פרוטה לעני והדר מצלי\u0004 \u0005[ואחר כך היה מתפלל],\u0006 \u0003אמר, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אני בצדק אחזה פניך\".\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אשבעה בהקיץ תמונתך\"? אמר רב נחמן בר יצחק: אלו תלמידי חכמים ש\u0004בלימודם \u0003מנדדין שינה מעיניהם בעולם הזה\u0004 (\"בהקיץ\"), \u0003והקדוש ברוך הוא משביען מזיו השכינה לעולם הבא\u0004 (\"אשבעה תמונתך\").","\u0003אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"מלוה ה' חונן דל\u0004 וגמולו ישלם לו\u0003\"\u0004 (משלי יט, יז)? \u0003אלמלא מקרא כתוב\u0004 כך \u0003אי אפשר לאומרו\u0004 מדעתנו. \u0003כביכול\u0004 מתקיים כאן מה שנאמר \u0003\"עבד לוה לאיש מלוה\"\u0004 (משלי כב, ז), שהרי מי שחונן דל נחשב כאילו הלוה להקדוש ברוך הוא.","\u0003אמר ר' חייא בר אבא: ר' יוחנן רמי\u0004 \u0005[השליך,\u0006 השווה שני מקראות\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"לא יועיל הון ביום עברה וצדקה תציל ממות\"\u0004 (משלי יא, ד), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"לא יועילו אוצרות רשע וצדקה תציל ממות\"\u0004 (משלי י, ב), \u0003שתי צדקות הללו למה?\u0004 למה נאמר פעמיים \"צדקה תציל ממות\"? \u0003אחת שמצילתו ממיתה משונה\u0004 בעולם הזה, \u0003ואחת שמצילתו מדינה של גיהנם\u0004 בעולם הבא. \u0003ואי זו היא שמצילתו מדינה של גיהנם? ההוא דכתיב ביה\u0004 \u0005[זה שנאמר בו]\u0006 \u0003\"עברה\", דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"יום עברה היום ההוא\"\u0004 (צפניה א, טו). \u0003ואי זו היא שמצילתו ממיתה משונה?\u0004"],["זוהי הצדקה המובחרת, כש\u0003נותנה ואינו יודע למי נותנה,\u0004 וה\u0003נוטלה אינו יודע ממי נוטלה.\u0004 ומסבירים: \u0003נותנה ואינו יודע למי נותנה, לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 \u0003מ\u0004מה שהיה עושה \u0003מר עוקבא\u0004 שהיה בעצמו מחלק צדקה לעניים והם לא ידעו מי הנותן. \u0003נוטלה ואינו יודע ממי נוטלה, לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004מה שהיה עושה \u0003ר' אבא\u0004 שהיה מפקיר את כספו כדי שעניים יבואו ויקחו ממנו, בלא שהוא ידע מי הוא הנוטל, אבל הם ידעו ממי הם נוטלים. ושואלים: \u0003ואלא\u0004 אם רצונו של אדם שלא ידע למי הוא נותן, ולא ידע הנוטל ממי הוא נוטל, \u0003היכי ליעביד\u0004 \u0005[איך יעשה]?\u0006 ומשיבים: \u0003ליתיב לארנקי\u0004 \u0005[שיתן לארנק]\u0006 \u0003של צדקה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנו בברייתא: \u0003מה יעשה אדם ויהיו לו בנים זכרים? ר' אליעזר אומר: יפזר מעותיו לעניים. ר' יהושע אומר: ישמח אשתו ל\u0004פני \u0003דבר מצוה\u0004 של תשמיש. \u0003ר' אליעזר בן יעקב אומר: לא יתן אדם פרוטה לארנקי של צדקה אלא אם כן ממונה עליה\u0004 אדם גדול ונאמן \u0003כר' חנניא בן תרדיון,\u0004 משמע שלתת לארנקי של צדקה אינו תמיד מן המובחר! ומשיבים: \u0003כי קא אמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 שהיא מצוה מן המובחר — הרי זה \u0003דממני עלה\u0004 \u0005[כאשר ממונה עליה]\u0006 אדם \u0003כר' חנניא בן תרדיון.\u0004","ועוד בענייני צדקה, \u0003אמר ר' אבהו, אמר משה לפני הקדוש ברוך הוא: רבונו של עולם, במה תרום קרן ישראל? אמר לו: ב\"כי תשא\".\u0004 כלומר, כיצד מתנשאים ישראל — על ידי תרומה וצדקה, כמפורש שם \"כי תשא את ראש בני ישראל... ונתנו\" (שמות ל, יא).","\u0003ואמר ר' אבהו, שאלו את שלמה\u0004 (המלך) \u0003בן דוד:\u0004 \u0003עד היכן כחה של צדקה? אמר להן: צאו וראו מה פירש דוד אבא\u0004 (אבי): \u0003\"פזר נתן לאביונים צדקתו עומדת לעד קרנו תרום בכבוד\"\u0004 (תהלים קיב, ט). \u0003ר' אבא אמר, מהכא\u0004 \u0005[מכאן]\u0006 נלמד עד היכן כוחה של צדקה: \u0003\"הוא מרומים ישכן מצדות סלעים משגבו לחמו נתן מימיו נאמנים\"\u0004 (ישעיה לג, טז), \u0003מה טעם \"מרומים ישכן מצדות סלעים משגבו\"\u0004 — \u0003משום\u0004 ש\u0003\"לחמו נתן\"\u0004 לעניים \u0003ו\"מימיו נאמנים\"\u0004 ניתנים בנאמנות, וניתן לסמוך עליו בדבר זה.","\u0003ואמר ר' אבהו, שאלו את שלמה: איזהו בן העולם הבא? אמר להם:\u0004 סימן לדבר הוא: \u0003כל\u0004 אלה \u0003ש\u0004נאמר עליהם \u0003\"כנגד זקניו כבוד\"\u0004 (ראה ישעיה כד, כג), כלומר, אלה שחולקים להם כבוד בעולם הזה מפני חוכמתם. \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' יהושע חלש, אינגיד\u0004 \u0005[חלה\u0006 ו\u0005התעלף]\u0006 ולבסוף התרפא. \u0003אמר ליה אבוה\u0004 \u0005[לו אביו]:\u0006 \u0003מאי חזית\u0004 \u0005[מה ראית]\u0006 כשהיית בעלפונך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עולם הפוך ראיתי,\u0004 שבעולם העליון \u0003עליונים,\u0004 אלה שהם חשובים בעולם הזה — נמצאים \u0003למטה, ותחתונים,\u0004 האנשים שנמצאים בעולם הזה במדרגה תחתונה — נמצאים בעולם העליון \u0003למעלה. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עולם ברור ראית,\u0004 כלומר, זהו עולם אמיתי, ושם הדבר הוא כראוי. ושאל אותו עוד: \u0003ואנן היכי חזיתינן\u0004 \u0005[ואותנו\u0006 החכמים \u0005איך ראית אותנו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כי היכי דחשבינן הכא חשבינן התם\u0004 \u0005[כמו שאנו חשובים כאן חשובים אנו שם].\u0006","והוסיף לו הבן: \u0003ושמעתי שהיו אומרים\u0004 שם: \u0003אשרי מי שבא לכאן ותלמודו בידו. ושמעתי שהיו אומרים\u0004 שם: \u0003הרוגי מלכות\u0004 — \u0003אין כל בריה יכולה לעמוד במחיצתן\u0004 מרוב גדולתם. ושואלים: \u0003מאן נינהו\u0004 \u0005[מי הם]\u0006 אותם הרוגי מלכות? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ר' עקיבא וחבריו\u0004 שנהרגו בידי הרומאים, \u0003משום\u0004 שהיו \u0003הרוגי מלכות\u0004 הם גדולים \u0003ותו לא\u0004 \u0005[ולא יותר]?\u0006 \u0003פשיטא\u0004 \u0005[פשוט],\u0006 \u0003בלאו הכי נמי\u0004 \u0005[בלא זה גם כן]\u0006 גדולים הם משאר אנשים! \u0003אלא\u0004 הכוונה היא ל\u0003הרוגי לוד\u0004 שמתו על קידוש ה', ולא היו אנשים גדולים בתורה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר להן רבן יוחנן בן זכאי לתלמידיו: בני, מהו שאמר הכתוב \"צדקה תרומם גוי וחסד לאמים חטאת\"\u0004 (משלי יד, לד)? \u0003נענה ר' אליעזר ואמר: \"צדקה תרומם גוי\"\u0004 — \u0003אלו ישראל, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ומי כעמך ישראל גוי אחד בארץ\"\u0004 (שמואל ב' ז, כג), \u0003\"וחסד לאמים חטאת\"\u0004 — \u0003כל צדקה וחסד שאומות העולם עושין, חטא הוא להן, שאינם עושין\u0004 אותו \u0003אלא\u0004 כדי \u0003להתגדל בו, כמו שנאמר: \"די להון מהקרבין ניחוחין לאלה שמיא ומצלין לחיי מלכא ובנוהי\"\u0004 \u0005[שיהיו מקריבים קרבנות לאלוהי השמים ומתפללים לחיי המלך ובניו]\u0006 (עזרא ו, י). משמע שאף על פי שהם נותנים, הריהם נותנים רק לשם עצמם.","ושואלים: \u0003ודעביד הכי לאו\u0004 \u0005[ו\u0006מי \u0005שעושה כך האם לא]\u0006 \u0003צדקה גמורה היא? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ה\u0004נותן סלע לצדקה ו\u0003אומר \"סלע זה לצדקה בשביל שיחיו בני\",\u0004 או \u0003\"בשביל שאזכה לעולם הבא\",\u0004 אף על פי שהוא מתכוון גם להנאת עצמו — \u0003הרי זה צדיק גמור!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן בישראל\u0004 — זה צדיק גמור, \u0003כאן בגוי\u0004 —","אינו נחשב לצדקה. \u0003נענה ר' יהושע ואמר\u0004 בפירוש הפסוק: \u0003\"צדקה תרומם גוי\"\u0004 — \u0003אלו ישראל, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ומי כעמך ישראל גוי אחד\", \"וחסד לאמים חטאת\"\u0004 — \u0003כל צדקה וחסד שאומות העולם עושין, חטא הוא להן, שאין עושין אלא כדי שתמשך מלכותן, שנאמר\u0004 לנבוכדנצר על ידי דניאל: \u0003\"להן מלכא מלכי ישפר עלך וחטיך בצדקה פרק ועויתך במחן ענין הן תהוי ארכה לשלותך\" וגו'\u0004 \u0005[לכן המלך, עצתי תיטב עליך וחטאיך בצדקה פדה ו\u0006את \u0005עוונך בחנינת עניים, אז תהיה ארכה לשלוותך]\u0006 (דניאל ד, כד), ואם בכך שכנע אותו, משמע שלשם כך הם עושים.","\u0003נענה רבן גמליאל ואמר: \"צדקה תרומם גוי\"\u0004 — \u0003אלו ישראל, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ומי כעמך ישראל\", \"וחסד לאמים חטאת\"\u0004 — \u0003כל צדקה וחסד שאומות העולם עושין, חטא הוא להן, שאין עושין אלא\u0004 כדי \u0003להתיהר\u0004 (להתגאות) \u0003בו, וכל המתיהר נופל בגיהנם, שנאמר: \"זד יהיר לץ שמו עושה בעברת זדון\"\u0004 (משלי כא, כד), \u0003ואין \"עברה\" אלא גיהנם, שנאמר: \"יום עברה היום ההוא\"\u0004 (צפניה א, טו).","\u0003אמר רבן גמליאל: עדיין אנו צריכין למודעי,\u0004 עדיין יש לשמוע את מה שאומר החכם המודעי. וכך \u0003ר' אליעזר המודעי אומר: \"צדקה תרומם גוי\"\u0004 — \u0003אלו ישראל, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ומי כעמך ישראל גוי אחד\", \"וחסד לאמים חטאת\"\u0004 — \u0003כל צדקה וחסד שאומות העולם עושין, חטא הוא להן, שאין עושין אלא לחרף אותנו בו, שנאמר\u0004 שאמר השר הבבלי נבוזראדן: \u0003\"ויבא ויעש ה' כאשר דבר כי חטאתם לה' ולא שמעתם בקולו והיה לכם הדבר הזה\"\u0004 (ירמיה מ, ג).","\u0003נענה ר' נחוניא בן הקנה ואמר: \"צדקה תרומם גוי וחסד\"\u0004 — \u0003לישראל, \"ולאמים\u0004 — \u0003חטאת\". אמר להם רבן יוחנן בן זכאי לתלמידיו: נראין דברי ר' נחוניא בן הקנה\u0004 יותר \u0003מדברי ומדבריכם, לפי שהוא נותן צדקה וחסד לישראל, ולאומות העולם חטאת.\u0004 ושואלים: \u0003מכלל\u0004 הדברים אתה שומע ש\u0003הוא,\u0004 רבן יוחנן בן זכאי, \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אמר\u0004 פירוש לפסוק זה, \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 פירוש זה שאמר? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר להם רבן יוחנן בן זכאי,\u0004 כך צריך לפרש: \u0003כשם ש\u0004קרבן \u0003החטאת מכפרת על ישראל\u0004 — \u0003כך צדקה מכפרת על אומות העולם.\u0004","מסופר: \u0003איפרא הורמיז אימיה\u0004 \u0005[אימו]\u0006 של \u0003שבור מלכא\u0004 \u0005[המלך]\u0006 מלך פרס, \u0003שדרה ארבע מאה דינרי לקמיה\u0004 \u0005[שלחה ארבע מאות דינרים לפני]\u0006 \u0003ר' אמי ולא קבלינהו\u0004 \u0005[קיבל אותם].\u0006 \u0003שדרינהו קמיה\u0004 \u0005[שלחה אותם לפני]\u0006 \u0003רבא, וקבלינהו\u0004 \u0005[וקיבל אותם]\u0006 \u0003משום שלום מלכות. שמע ר' אמי איקפד\u0004 \u0005[הקפיד\u0006 על כך\u0005],\u0006 \u0003אמר:\u0004 וכי רבא \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור\u0005]\u0006 שיש ללמוד מן הכתוב \u0003\"ביבש קצירה תשברנה נשים באות מאירות אותה\"\u0004 (ישעיה כז, יא), שכאשר תכלה מאומה מסויימת כל צדקה (\"ביבוש קצירה\") מגיע זמן הפורענות לאותה אומה, ולכן אין לסייע לגויים לעשות זכות?! ושואלים: \u0003ורבא\u0004 מה טעם קיבל? ומשיבים: \u0003משום שלום מלכות.\u0004","ושואלים: \u0003ור' אמי נמי\u0004 \u0005[גם כן]\u0006 היה צריך להתחשב \u0003משום שלום מלכות!\u0004 ומשיבים: \u0003דאיבעי ליה למפלגינהו\u0004 \u0005[שהיה צריך לו לחלק אותם]\u0006 את הכספים הללו \u0003לעניי גויים\u0004 ולא לעניי ישראל, שיש בזיון לישראל שהם נזקקין לחסד האומות כדי לפרנס את עניי ישראל. ומספרים: \u0003ורבא נמי\u0004 \u0005[גם כן]\u0006 \u0003לעניי גויים יהבינהו\u0004 \u0005[נתן אותם]\u0006 ולא לעניי ישראל, \u0003ור' אמי דאיקפד\u0004 \u0005[שהקפיד]\u0006 על כך \u0003הוא\u0004 משום"],["ש\u0003לא סיימוה קמיה\u0004 \u0005[לפניו]\u0006 ולא סיפרו לו שחילק רבא לעניים גויים.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמרו עליו על בנימין הצדיק שהיה ממונה על קופה של צדקה, פעם אחת באתה\u0004 (באה) \u0003אשה לפניו בשני\u0004 (בשנות) \u0003בצורת, אמרה לו: רבי, פרנסני! אמר לה: העבודה,\u0004 כלומר, נשבע אני בעבודת המקדש, \u0003שאין בקופה של צדקה כלום! אמרה לו: רבי, אם אין אתה מפרנסני, הרי אשה ושבעה בניה מתים! עמד ופרנסה משלו. לימים\u0004 (לאחר זמן) \u0003חלה ונטה למות, אמרו מלאכי השרת לפני הקדוש ברוך הוא: רבונו של עולם, אתה אמרת: כל המקיים נפש אחת מישראל כאילו קיים עולם מלא, ובנימין הצדיק שהחיה אשה ושבעה בניה ימות בשנים מועטות הללו,\u0004 בצעירותו? \u0003מיד קרעו לו גזר דינו. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003הוסיפו לו עשרים ושתים שנה על שנותיו.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה במונבז המלך שבזבז\u0004 (פיזר) \u0003אוצרותיו ואוצרות אבותיו בשני בצורת\u0004 וחילקם לעניים, \u0003וחברו\u0004 (נתאספו) \u0003עליו אחיו ובית אביו\u0004 לטעון כנגדו על כך, \u0003ואמרו לו: אבותיך גנזו\u0004 באוצרותיהם \u0003והוסיפו על\u0004 האוצרות \u0003של אבותם, ואתה מבזבזם! אמר להם:\u0004 לא כן, \u0003אבותי גנזו למטה, ואני גנזתי למעלה, שנאמר: \"אמת מארץ תצמח וצדק משמים נשקף\"\u0004 (תהלים פה, יב), משמע שהצדק שאני עושה נמצא בשמים. \u0003אבותי גנזו במקום שהיד שולטת בו\u0004 ואפשר לגזול אותו מהם, \u0003ואני גנזתי במקום שאין היד שולטת בו, שנאמר: \"צדק ומשפט מכון כסאך\"\u0004 (תהלים פט, טו), כלומר, שהצדק נמצא תחת כסאו של הקדוש ברוך הוא, ולשם בוודאי אין אדם יכול להגיע.","\u0003אבותי גנזו דבר שאין עושה פירות,\u0004 שהרי הממון שבאוצר אינו מתרבה, \u0003ואני גנזתי דבר שעושה פירות, שנאמר: \"אמרו צדיק כי טוב כי פרי מעלליהם יאכלו\"\u0004 (ישעיה ג, י). \u0003אבותי גנזו אוצרות ממון ואני גנזתי אוצרות נפשות, שנאמר: \"פרי צדיק עץ חיים ולקח נפשות חכם\"\u0004 (משלי יא, ל). \u0003אבותי גנזו לאחרים\u0004 — לבניהם ויורשיהם, שהרי הם עצמם עוברים מן העולם, \u0003ואני גנזתי לעצמי, שנאמר: \"ולך תהיה צדקה\"\u0004 (דברים כד, יג). \u0003אבותי גנזו לעולם הזה, ואני גנזתי לעולם הבא, שנאמר: \"והלך לפניך צדקך כבוד ה' יאספך\"\u0004 (ישעיהו נח, ח).","וחוזרים לפירוש המשנה. שנינו: כמה יהא בעיר ויהא כאנשי העיר (לענין מיסים וכיוצא בזה) — שנים עשר חודש, \u0003ואם קנה בה\u0004 בעיר \u0003בית דירה\u0004 — \u0003הרי הוא כאנשי העיר\u0004 מיד. ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא\u0004 \u0003כ\u0004שיטת \u0003רבן שמעון בן גמליאל, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: אם קנה בה\u0004 בעיר \u0003קרקע כל שהוא,\u0004 ולאו דווקא בית דירה — \u0003הרי הוא כאנשי העיר\u0004 מיד.","ומתקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: אם קנה שם קרקע הראויה לבית דירה\u0004 — \u0003הרי הוא כאנשי העיר!\u0004 משמע שהדבר תלוי בקרקע הראויה לדירה, ולא קרקע סתם, כפי שמשמע מן הברייתא הראשונה! ומשיבים: \u0003תרי תנאי\u0004 \u0005[שני תנאים]\u0006 נחלקו בכך, \u0003ו\u0004שניהם \u0003אליבא\u0004 \u0005[על פי שיטת]\u0006 \u0003רבן שמעון בן גמליאל.\u0004","\u0003אין\u0004 השותפים בחצר \u0003חולקין את החצר\u0004 — \u0003עד שיהא\u0004 לאחר החלוקה שיעור \u0003ארבע אמות\u0004 מרובעות \u0003לזה וארבע אמות לזה,\u0004 לכל אחד מן השותפים בה. \u0003ולא\u0004 חולקים \u0003את השדה\u0004 — \u0003עד שיהא בה\u0004 מקום לזריעת \u0003תשעה קבין לזה ותשעה קבין לזה. ר' יהודה אומר: עד שיהא בה תשעת חציי קבין לזה ותשעת חציי קבין לזה. ולא\u0004 חולקים \u0003את הגינה\u0004 — \u0003עד שיהא בה\u0004 מקום לזריעת \u0003חצי קב לזה\u0004 \u0003וחצי קב לזה. ר' עקיבא אומר:\u0004 חצי משיעור זה, \u0003בית רובע\u0004 קב לכל אחד.","ואין חולקים \u0003לא את הטרקלין, ולא את המורן\u0004 (מין ארמון), \u0003ולא את השובך\u0004 של יונים, \u0003ולא את הטלית, ולא את המרחץ, ולא את בית הבד, ולא את בית השלחין\u0004 (שדה מושקה) — \u0003עד שיהא בהן כדי לזה וכדי לזה,\u0004 שכל אחד יוכל להשתמש בו כדרכו. \u0003זה הכלל: כל שיחלק ו\u0004עדיין \u0003שמו עליו,\u0004 שגם לאחר חלוקתו חלקיו גדולים דיים להמשיך ולהיקרא בשם הקודם — \u0003חולקין, ואם לאו\u0004 \u0005[לא],\u0006 שכשחולקים אותו מתבטל שמו ממנו — \u0003אין חולקין.\u0004","\u0003אימתי\u0004 אמרו כללים אלה? \u0003בזמן שאין שניהם רוצים\u0004 בחלוקה, אלא רק אחד מהם רוצה בה, ואז אינו יכול לכפות את שותפו לכך. \u0003אבל בזמן ששניהם רוצים\u0004 — \u0003אפילו\u0004 היה \u0003פחות מכאן\u0004 לכל אחד מהם — \u0003יחלוקו. וכתבי הקדש\u0004 שנפלו לשנים בירושה, \u0003אף על פי ששניהם רוצים\u0004 — \u0003לא יחלוקו,\u0004 שאין זה כבוד לכתבי הקודש שחותכים אותם.","\u0003אמר ר' אסי אמר ר' יוחנן: ארבע אמות שאמרו\u0004 הן \u0003חוץ משל פתחים,\u0004 שיש להוסיף להן גם שטח שלפני הפתח, לצורך טעינה ופריקה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אין חולקים את החצר\u0004 — \u0003עד שיהא בה שמונה אמות לזה ושמונה אמות לזה.\u0004 ויש לשאול: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003ארבע אמות לזה וארבע אמות לזה! אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003כ\u0004דברי \u0003ר' אסי.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006","\u0003ואיכא דרמי להו מירמא\u0004 \u0005[ויש מי שהשליך את הדברים]\u0006, שאמר דבר זה כתירוץ על סתירה בין מקורות, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אין חולקין את החצר עד שיהא בה\u0004 לאחר החלוקה \u0003ארבע אמות לזה וארבע אמות לזה. והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 אין חולקין את החצר עד שיהא בה \u0003שמונה אמות לזה ושמונה אמות לזה!\u0004 על כך \u0003אמר ר' אסי אמר ר' יוחנן: ארבע אמות שאמרו\u0004 במשנה, הכוונה היא \u0003חוץ משל פתחים.\u0004","ועוד בענין חלוקת החצר, \u0003אמר רב הונא: חצר מתחלקת לפי פתחיה,\u0004 שכל מי שיש לו פתחים בחצר מקבל חלק בה לפי מספר הפתחים שיש לו. \u0003ורב חסדא אמר: נותנין ארבע אמות לכל פתח ופתח, והשאר חולקין בשוה.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב חסדא: פתחים שבחצר\u0004 — \u0003יש להן ארבע אמות. היה לזה פתח אחד ולזה שני פתחים, זה שיש לו פתח אחד\u0004 — \u0003נוטל ארבע אמות, וזה שיש לו שני פתחים\u0004 — \u0003נוטל שמונה אמות, והשאר חולקין בשוה. היה לזה פתח רחב שמונה אמות\u0004 — \u0003נוטל שמונה אמות כנגד הפתח וארבע אמות בחצר.\u0004 ותוהים: \u0003ארבע אמות בחצר מאי עבידתייהו\u0004 \u0005[מה מעשיהם]?\u0006 הרי הכל תלוי בגודל החצר! \u0003אמר אביי, הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 כך היא כוונת הדברים: לצורך הפתח \u0003נוטל שמונה אמות באורך החצר וארבע אמות ברוחב החצר,\u0004 כלומר, שטח ברוחב ארבע אמות כנגד כל אורך פתחו.","\u0003אמר אמימר\u0004 \u0005[החכם]:\u0006 \u0003האי פירא דסופלי\u0004 \u0005[החפירה\u0006 שמכניסים בה \u0005מאכל בהמה]\u0006 — \u0003יש לו ארבע אמות לכל רוח ורוח\u0004 (צד), כדי שיהא מקום להעמיד שם את הבהמות. ומוסיפים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 כש\u0003לא מייחד ליה פתחא\u0004 \u0005[מיוחד לה פתח]\u0006 מסויים לחפירה זו אלא מגיעים לשם מכל צד,"],["\u0003אבל\u0004 אם \u0003מייחד ליה פיתחא\u0004 \u0005[מיוחד לו פתח]\u0006 לבור הזה ואינו מגיע אליו מכל צד — \u0003אין לו אלא ארבע אמות לפני פתחו.\u0004","\u0003אמר רב הונא: אכסדרה\u0004 הפתוחה לחצר \u0003אין לה ארבע אמות,\u0004 שכן \u0003טעמא מאי\u0004 \u0005[מה טעם]\u0006 נתנו ארבע אמות לפתח? \u0003משום\u0004 מקום לצורך \u0003פירוק משאו, הכא\u0004 \u0005[כאן]\u0006 \u0003אפשר דעייל לגואי ומפרק\u0004 \u0005[שיכנס פנימה\u0006 לתוך האכסדרה \u0005ויפרוק].\u0006 \u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב ששת\u0004 ממה ששנינו בברייתא: \u0003אחד שערי בתים ואחד שערי אכסדראות\u0004 — \u0003יש להן ארבע אמות!\u0004 ומשיבים: \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 — הרי זה בסוג מיוחד של אכסדרה, \u0003באכסדרה דבי רב\u0004 \u0005[של בית הספר]\u0006 שהיא סגורה ואין פורקים בתוכה. ותוהים: \u0003אכסדרה דבי רב, פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכך הוא, שהרי \u0003אידרונא מעליא\u0004 \u0005[חדר מעולה,\u0006 שלם\u0005]\u0006 \u0003הוא! אלא באכסדרה רומייתא\u0004 \u0005[רומאית]\u0006 שפרוצה יותר מאכסדרה דבי רב, אבל גם בה אין פורקים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בית שער\u0004 (מבנה שדרכו נכנסים לחצר) \u0003אכסדרה, ומרפסת\u0004 שיש לה גרם מדרגות לחצר — \u0003יש להן ארבע אמות.\u0004 אם \u0003היו\u0004 אפילו \u0003חמשה בתים פתוחין למרפסת\u0004 — \u0003אין להן אלא ארבע אמות בלבד\u0004 בכניסה לגרם המדרגות עבור המרפסת. \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' יוחנן מר' ינאי: לול של תרנגולין\u0004 שאף לו יש גרם מדרגות, \u0003יש לו ארבע אמות\u0004 בפתחו, \u0003או אין לו ארבע אמות? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003טעמא מאי\u0004 \u0005[מה טעם]\u0006 נתנו ארבע אמות? \u0003משום פירוק משאו, הכא\u0004 \u0005[כאן]\u0006 אינו זקוק לכך אלא התרנגול \u0003מטפס ועולה\u0004 לתוך הלול, \u0003מטפס ויורד\u0004 ממנו החוצה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן:\u0004 אם היה \u0003בית\u0004 ש\u0003חציו מקורה וחציו אינו מקורה, יש לו ארבע אמות או אין לו ארבע אמות? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין לו ארבע אמות; לא מבעיא\u0004 \u0005[נצרכה]\u0006 לומר כשהיה \u0003קירויו מלגיו\u0004 \u0005[מבפנים],\u0006 ש\u0003אפשר דעייל לגואי ומפרק\u0004 \u0005[שייכנס פנימה ויפרוק]\u0006 את משאו, \u0003אלא אפילו\u0004 היה \u0003קירויו כלפי חוץ,\u0004 שהרי \u0003אפשר דעייל לגואי ומפרק\u0004 \u0005[שייכנס פנימה ויפרוק]\u0006 שם משאו.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב הונא מר' אמי: אחד מבני מבוי,\u0004 שפתוחות אליו מספר חצירות, \u0003שבקש להחזיר פתחו למבוי אחר,\u0004 שרצונו לפתוח פתח לחצירו בצד הפונה למבוי אחר, האם \u0003בני\u0004 ה\u0003מבוי\u0004 האחר \u0003מעכבין עליו,\u0004 רשאים למונעו מלפתוח פתח זה, \u0003או אין מעכבין עליו?\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בני מבוי מעכבין עליו.\u0004","ועוד שאל: \u0003אכסניא,\u0004 כאשר המלך מטיל על אנשי החצר לאכסן את אנשי הצבא בביתם, האם \u0003לפי בני אדם,\u0004 מספר האנשים בכל בית אב, היא \u0003מתחלקת, או לפי\u0004 מספר \u0003פתחים\u0004 שיש לכל אחד לחצר היא \u0003מתחלקת? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לפי\u0004 מספר \u0003בני אדם\u0004 היא \u0003מתחלקת.\u0004 ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003זבל שבחצר\u0004 שרוצים בני החצר להשתמש בו \u0003מתחלקת לפי\u0004 מספר ה\u0003פתחים\u0004 הפתוחים לחצר, \u0003אכסניא\u0004 — \u0003לפי\u0004 מספר \u0003בני אדם\u0004 הדרים בה.","\u0003אמר רב הונא: אחד מבני מבוי שבקש לסתום כנגד פתחו\u0004 כלומר, לבנות מבנה במבוי כנגד פתח חצירו — \u0003בני מבוי מעכבין עליו\u0004 ואינם מניחים לו לעשות כן, מדוע? — מפני \u0003שמרבה עליהן את הדרך,\u0004 שצריכים להקיף את המבנה הזה בדרכם מביתם ולביתם.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: היו \u0003חמש חצרות פתוחות למבוי\u0004 — \u0003כולן משתמשות עם החיצונה,\u0004 שבני החצרות האחרות משתמשים בשטח הסמוך לפתח החצר החיצונה הקרובה יותר לפתח המבוי, \u0003והחיצונה משתמשת\u0004 רק \u0003לעצמה\u0004 בשטח שמול פתחה. \u0003ו\u0004כן \u0003השאר משתמשות עם השניה,\u0004 כלומר, הסמוכה לחיצונה, \u0003והשניה משתמשת לעצמה ומשתמשת עם\u0004 השטח שכנגד החצר \u0003החיצונה.\u0004","\u0003נמצאת פנימית\u0004 שבכולן \u0003משתמשת לעצמה\u0004 בלבד \u0003ומשתמשת עם כל\u0004 השטר שכנגד כל \u0003אחת ואחת\u0004 מהחיצוניות לה.","משמע שבעל החצר הפנימית יכול לסתום לפני פתחו, שהרי רק הוא משתמש לעצמו! ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד מבני מבוי שבקש להחזיר פתחו למבוי אחר\u0004 — \u0003בני\u0004 ה\u0003מבוי\u0004 האחר \u0003מעכבין עליו\u0004 ומונעים אותו מלעשות כן. \u0003היה\u0004 שם פתח קודם לכן, ועכשיו הוא \u0003סתום ובקש לפותחו\u0004 מחדש — \u0003אין בני מבוי מעכבין עליו,\u0004 אלו \u0003דברי רבי. ר' שמעון בן אלעזר אומר: חמש חצרות הפתוחות למבוי\u0004 — \u0003כולן משתמשות במבוי זו עם זו.\u0004","ותוהים: \u0003חצרות מאן דכר שמייהו\u0004 \u0005[מי הזכיר את שמן],\u0006 הרי אין אנו עוסקים כאן בדיני חצירות, ומדוע הוזכרו כאן? ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך היא שנויה]:\u0006 \u0003וכן חמש חצרות הפתוחות למבוי\u0004 — \u0003כולן משתמשות עם החיצונה, והחיצונה משתמשת לעצמה,\u0004 אלו \u0003דברי רבי. ר' שמעון בן אלעזר אומר: חמש חצרות הפתוחות למבוי\u0004 — \u0003כולם משתמשות במבוי.\u0004","ושבים לדון בפרטי הברייתא, \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003היה\u0004 פתחו \u0003סתום ובקש לפותחו\u0004 — \u0003אין בני מבוי מעכבין עליו. אמר רבא: לא שנו אלא שלא פרץ את פצימיו,\u0004 כלומר, שכאשר סתם את הפתח לא הסיר את המזוזות משם, \u0003אבל\u0004 אם לצורך סתימת הפירצה \u0003פרץ את פצימיו,\u0004 ומראה בכך שביטל לגמרי את הפתח — \u0003בני מבוי מעכבין עליו\u0004 אם רוצה לפתוח אותו מחדש. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא: תניא דמסייע\u0004 \u0005[שנויה\u0006 ברייתא \u0005המסייעת]\u0006 \u0003לך:\u0004"],["\u0003בית\u0004 שהיה פתחו \u0003סתום\u0004 — למרות זאת \u0003יש לו ארבע אמות\u0004 בחלקו בחצר, אבל אם \u0003פרץ את פצימיו\u0004 של אותו פתח שסתמו — \u0003אין לו\u0004 עוד \u0003ארבע אמות.\u0004","וכן אמרו לענין הלכות טומאת המת: \u0003קבר שפתחו סתום\u0004 — \u0003אינו מטמא\u0004 את \u0003כל סביביו,\u0004 שהטומאה יוצאת דרך הפתח. אבל אם \u0003פרץ את פצימיו וסתמו\u0004 — אז \u0003מטמא\u0004 את \u0003כל סביביו,\u0004 שטומאה שאין לה פתח לצאת בוקעת מכל צד. וכן \u0003בית סתום\u0004 שהיה מת מצוי בו — \u0003אינו מטמא\u0004 את \u0003כל סביביו\u0004 אלא במקום הפתח, ואם \u0003פרץ את פצימיו\u0004 — הריהו \u0003מטמא\u0004 את \u0003כל סביביו.\u0004","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: מבואות המפולשות\u0004 (הפתוחים) \u0003לעיר אחרת\u0004 שיוצאים דרכם לעיר אחרת, \u0003ובקשו בני העיר לסותמן\u0004 — \u0003בני אותה העיר\u0004 אליה פתוחים אותם מבואות \u0003מעכבין עליהן,\u0004 שזכותם להגיע בדרך זו לעירם. ומסבירים: \u0003לא מיבעי\u0004 \u0005[נצרכה]\u0006 לומר \u0003כי ליכא דרכא אחרינא דמעכבי\u0004 \u0005[כאשר אין דרך אחרת\u0006 להגיע לעירם \u0005ש\u0006הם יכולים \u0005לעכב],\u0006 \u0003אלא אפילו כי איכא דרכא אחרינא, נמי מעכבי\u0004 \u0005[כאשר יש דרך אחרת, גם כן יכולים\u0006 הם \u0005לעכב],\u0006","\u0003משום\u0004 הסברה של \u0003רב יהודה אמר רב,\u0004 ש\u0003אמר: מצר שהחזיקו בו רבים,\u0004 שאם היו רבים רגילים ללכת בנתיב מסויים — \u0003אסור לקלקלו,\u0004 כלומר, לבטלו מלשמש עוד כמעבר. וכדברי \u0003רב גידל,\u0004 ש\u0003אמר ר' גידל: רבים שבררו דרך לעצמן\u0004 והולכים בה — \u0003מה שבררו בררו\u0004 ואי אפשר לקחת אותה זכות מעבר מהם.","\u0003אמר רב ענן אמר שמואל: מבואות המפולשין\u0004 (הפתוחים) \u0003לרשות הרבים ובקשו בני מבואות להעמיד להן דלתות\u0004 למבוא שלהם — \u0003בני רשות הרבים מעכבין עליהן.\u0004","ומסופר: \u0003סבור מינה\u0004 \u0005[היו סבורים\u0006 בני הישיבה\u0005]\u0006 ש\u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא \u0003בארבע אמות, כ\u0004דברי \u0003ר' זירא אמר רב נחמן,\u0004 ש\u0003אמר ר' זירא אמר רב נחמן: ארבע אמות הסמוכות לרשות הרבים\u0004 בקצה המבוי הרי \u0003כרשות הרבים\u0004 \u0003דמיין\u0004 \u0005[\u0006הן \u0005נחשבות],\u0006 ומשום כך יש לשטח הזה דין רשות הרבים. \u0003ולא היא\u0004 (ואינו כן), \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003לענין טומאה\u0004 ואז רק ארבע אמות ראשונות נחשבות כרשות הרבים, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 לענין הילוך \u0003זימנין דדחקי\u0004 \u0005[פעמים שדוחקים]\u0006 \u0003בני רשות הרבים ועיילי טובא\u0004 \u0005[ונכנסים הרבה]\u0006 בתוך המבוי, יותר מארבע אמות.","שנינו במשנה: \u0003ולא\u0004 מחלקים \u0003את השדה\u0004 — \u0003עד שיהא בה\u0004 לאחר חלוקה \u0003תשעה קבין לזה ותשעה קבין לזה.\u0004 ואילו ר' יהודה חולק ואומר שהשיעור הוא תשעה חצאי קבין. ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין\u0006 הם \u0005חלוקים]\u0006 בעקרון, אלא \u0003מר כי אתריה ומר כי אתריה\u0004 \u0005[חכם זה\u0006 הולך","\u0005לפי מקומו וחכם זה\u0006 הולך \u0005לפי מקומו],\u0006 שבמקומו של ר' יהודה נחשבה אף חלקה קטנה יותר כשדה שלם. ושואלים: משנתנו נשנתה בארץ ישראל, \u0003בבבל מאי\u0004 \u0005[מה]\u0006 המנהג שצריך לנהוג בחלוקה כזו? \u0003אמר רב יוסף: בי רדו יומא\u0004 \u0005[בית חרישת יום],\u0006 כלומר, שטח שחורשים בו במשך יום אחד הוא הנחשב שדה לעצמו, ובפחות מזה לכל אחד מהם אין חולקים.","ושואלים: \u0003מאי \"בי רדו יומא\"\u0004 \u0005[מה\u0006 פירוש \u0005\"בית חרישת יום\"]?\u0006 \u0003אי יומא זרעא\u0004 \u0005[אם\u0006 מדובר על \u0005יום\u0006 חריש בעונת \u0005הזריעה,\u0006 בחורף\u0005],\u0006 \u0003תרי יומא כרבא לא הוי\u0004 \u0005[שני ימים\u0006 מלאים \u0005של חרישה\u0006 בקיץ \u0005אין\u0006 כאן\u0005]\u0006 ונמצא שצריך לשלם לפועל החורש בקיץ שכר עבודה של יומיים שלמים עבור עבודת יום ומשהו, \u0003אי יומא כרבא\u0004 \u0005[אם\u0006 מדובר על \u0005יום חרישה\u0006 של קיץ\u0005],\u0006 אם כן \u0003יומא דזרעא לא הוי\u0004 \u0005[אין הוא יום\u0006 חריש שלם","\u0005של זריעה\u0006 בחורף\u0005]!\u0006 ומשיבים: \u0003אי בעית אימא יומא דכרבא\u0004 \u0005[אם תרצה אמור יום חרישה]\u0006 ועדיין יש בכך עבודה ליום זריעה שלם — \u0003דכריב ותני\u0004 \u0005[שחורש ושונה]\u0006 לאחר שזורע. \u0003ואי בעית אימא יומא דזרעא\u0004 \u0005[ואם תרצה אמור יום של זריעה]\u0006 ועדיין יש בכך שני ימי חרישה מלאים — \u0003בהדורי\u0004 \u0005[במקום טרשים].\u0006","ואגב ענין זה מבררים: \u0003דוולא,\u0004 בור השותפים שדולים ממנו מים, מתי יש בו דין חלוקה? \u0003אמר רב נחמן:\u0004 כאשר יש בו \u0003בי דאלו יומא\u0004 \u0005[בית\u0006 שיעור \u0005דליית יום]\u0006 לכל אחד לצורך השקיית שדותיו. שיעור חלוקה של \u0003פרדסא\u0004 \u0005[פרדס],\u0006 \u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל:\u0004 \u0003בת שלשת קבין\u0004 לכל אחד, שליש משיעור חלוקה של שדה.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003האומר לחבירו: \"מנת\u0004 (מנה) \u0003בכרם אני מוכר לך\"\u0004 ולא פירש מה שיעורה — \u0003סומכוס אומר: לא יפחות משלשה קבין. אמר ר' יוסי: אין אלו אלא דברי נביאות,\u0004 קביעת שיעור ללא נימוק כלל, כאילו היו אלה דברי נבואה, גזירה משמים, שהרי לא קבע לכך שיעור, אלא אמר רק באופן כללי \"מנה בכרם\". ושואלים: \u0003בבבל מאי\u0004 \u0005[מהו]\u0006 השיעור לענין זה? \u0003אמר רבא בר קסנא: תלת אציאתה בני תריסר גופני\u0004 \u0005[שלוש שורות בנות שתים עשרה גפנים],\u0006 \u0003כי היכי דרפיק גברא ביומא\u0004 \u0005[כמו\u0006 השטח \u0005שעודר אדם ב\u0006משך \u0005יום\u0006 אחד\u0005].\u0006","אגב מה שאמר ר' יוסי \"אין אלו אלא דברי נביאות\", מביאים מה ש\u0003אמר ר' אבדימי\u0004 ש\u0003מן חיפה: מיום שחרב בית המקדש, ניטלה נבואה מן הנביאים וניתנה לחכמים.\u0004 ותוהים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003חכם לאו\u0004 \u0005[לא]\u0006 \u0003נביא הוא,\u0004 וכי אין החכם ראוי להיות נביא? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אף על פי שניטלה\u0004 הנבואה \u0003מן הנביאים,\u0004 מכל מקום \u0003מן החכמים לא ניטלה.\u0004","\u0003אמר אמימר:\u0004 \u0003וחכם עדיף מנביא, שנאמר: \"ונבא לבב חכמה\"\u0004 (תהלים צ, יב), כלומר, לנביא יש לב חכמה, וכרגיל כאשר משווים דבר לחבירו \u0003מי נתלה במי?\u0004 \u0003הוי אומר: קטן נתלה\u0004 ומושווה \u0003בגדול,\u0004 אף כאן, הנבואה מושווית לחכמה, משמע שחכמה גדולה מנבואה.","\u0003אמר אביי: תדע\u0004 שכן הוא, שעדיין יש נבואה בין החכמים, \u0003דאמר גברא רבה מילתא\u0004 \u0005[שאומר אדם גדול דבר\u0006 הלכה\u0005],\u0006 \u0003ומתאמרא משמיה דגברא רבה אחרינא כוותיה\u0004 \u0005[ונאמרת\u0006 אותה שמועה \u0005משמו של אדם גדול אחר כשיטתו]\u0006 משמע שהחכם אומר את הדברים בכעין נבואה. \u0003אמר רבא: ומאי קושיא\u0004 \u0005[ומה הקושי\u0006 בזה\u0005]?\u0006 \u0003ודילמא תרוייהו בני חד מזלא נינהו\u0004 \u0005[ושמא שניהם בני מזל אחד הם],\u0006 ומפני שהם דומים זה לזה בתכונותיהם, לכן שיטותיהם מכוונות! \u0003אלא אמר רבא: תדע\u0004 שכן הוא, \u0003דאמר גברא רבה מילתא\u0004 \u0005[שאומר אדם גדול דבר],\u0006 \u0003ומתאמרא\u0004 \u0005[ונאמרת]\u0006 אותה שמועה"],["\u0003משמיה\u0004 \u0005[משמו]\u0006 של התנא הידוע \u0003ר' עקיבא בר יוסף כוותיה\u0004 \u0005[כשיטתו]\u0006 ובוודאי אי אפשר לומר שהוא דומה לר' עקיבא, אלא כיוון לדבריו במעין נבואה. \u0003אמר רב אשי: ומאי קושיא\u0004 \u0005[מה הקושי\u0006 שבדבר\u0005]?\u0006 \u0003דלמא להא מילתא בר מזליה\u0004 \u0005[שמא לדבר זה בן מזלו]\u0006 \u0003הוא,\u0004 שלענין הבנה בענין זה הוא דומה לו!","\u0003אלא אמר רב אשי: תדע, דאמר גברא רבה מילתא\u0004 \u0005[שאומר אדם גדול דבר\u0006 הלכה\u0005],\u0006 \u0003ומתאמרא\u0004 \u0005[ונאמרת]\u0006 \u0003הלכה למשה מסיני כוותיה\u0004 \u0005[כשיטתו]\u0006 ובזה ודאי שמכוון לדברים שנאמרו משמים, ואינם בכוחו של אדם. ואומרים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 הגיע לכך \u0003כסומא בארובה\u0004 במקרה, בלי להתכוון לכך, ואולי כיוון לדברים במקרה, ואין זו נבואה! ומשיבים: \u0003ולאו טעם יהיב\u0004 \u0005[וכי אינו נותן טעם,\u0006 מנמק את דבריו\u0005]?\u0006 ומכאן רואים שמתוך טעמו והבנתו הוא מכוון, כעין נבואה, לדברים שאי אפשר להגיע אליהם באופן אחר.","\u0003אמר ר' יוחנן: מיום שחרב בית המקדש, ניטלה נבואה מן הנביאים וניתנה לשוטים ולתינוקות.\u0004 ומסבירים: מה שנאמר שמשחרב בית המקדש ניתנה נבואה \u0003לשוטים, מאי היא\u0004 \u0005[מהו]?\u0006 — \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003מר בר רב אשי דהוה קאי ברסתקא\u0004 \u0005[שהיה עומד ברחוב]\u0006 של \u0003מחוזא, שמעיה לההוא שוטה דקאמר\u0004 \u0005[שמע שוטה אחד שאומר]:\u0006 \u0003ריש מתיבתא דמליך\u0004 \u0005[ראש הישיבה שימלוך,\u0006 שיתמנה\u0005]\u0006 \u0003במתא מחסיא\u0004 — \u0003\"טביומי\" חתים\u0004 \u0005[\u0006הוא \u0005חותם].\u0006 \u0003אמר\u0004 מר בר רב אשי לעצמו: \u0003מאן חתים\u0004 \u0005[מי\u0006 זה \u0005החותם]\u0006 \u0003\"טביומי\" ברבנן\u0004 \u0005[בין החכמים]?\u0006 — \u0003אנא\u0004 \u0005[אני],\u0006 \u0003שמע מינה לדידי קיימא לי שעתא\u0004 \u0005[למד מכאן שלי עומדת השעה]\u0006 ותהא לי עכשיו הצלחה בדבר הזה. \u0003קם אתא\u0004 \u0005[עמד\u0006 ו\u0005בא]\u0006 למתא מחסיא. \u0003אדאתא אימנו רבנן לאותביה\u0004 \u0005[עד שבא נמנו,\u0006 הסכימו, \u0005חכמים להושיב]\u0006 את \u0003רב אחא מדפתי ברישא\u0004 \u0005[בראשות\u0006 הישיבה\u0005].\u0006","\u0003כיון דשמעי דאתא\u0004 \u0005[ששמעו ש\u0006מר בר רב אשי \u0005בא],\u0006 אמרו שלא יעשו מינוי זה שלא מדעתו של חכם חשוב כמותו. \u0003שדור זוגא דרבנן לגביה לאימלוכי ביה\u0004 \u0005[שלחו זוג חכמים אליו להימלך בו],\u0006 \u0003עכביה\u0004 \u0005[עיכב]\u0006 את בני הזוג הזה. \u0003הדר שדור זוגא דרבנן אחרינא, עכביה גביה\u0004 \u0005[חזרו\u0006 ו\u0005שלחו זוג אחר\u0006 של \u0005חכמים\u0006 אצלו, ו\u0005עיכב\u0006 גם \u0005אותו אצלו],\u0006 \u0003עד דמלו בי עשרה\u0004 \u0005[שהשלימו מנין של עשרה\u0006 חכמים\u0005].\u0006 \u0003כיון דמלו בי\u0004 \u0005[שהשלימו כדי]\u0006 \u0003עשרה פתח הוא ותנא\u0004 \u0005[ושנה]\u0006 \u0003ודרש.\u0004 וטעם הדבר שלא פתח קודם, \u0003לפי שאין פותחין בכלה\u0004 (באסיפת חכמים) \u0003פחות מעשרה,\u0004 וכיון שכבר התחיל לדרוש ברבים נהיה הוא ראש הישיבה.","\u0003קרי\u0004 \u0005[קרא]\u0006 \u0003רב אחא\u0004 מדפתי \u0003אנפשיה\u0004 \u0005[על עצמו]\u0006 מה שאמרו חכמים: \u0003כל המריעין לו\u0004 — \u0003לא במהרה מטיבין לו, וכל המטיבין לו\u0004 — \u0003לא במהרה מריעין לו.\u0004 שהרי הרע לו מזלו שעמד להתמנות ולא נתמנה, ומאידך מר בר רב אשי היטיבו לו, שנתמנה.","ומה שנאמר שמשחרב בית המקדש ניתנה נבואה ל\u0003תנוקת\u0004 — \u0003מאי היא\u0004 \u0005[מהו]?\u0006 כלפי מה הדברים אמורים? — \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003בת רב חסדא\u0004 כשהיתה תינוקת \u0003הוה יתבה בכנפיה דאבוה\u0004 \u0005[היתה יושבת בחיקו של אביה]\u0006 כאשר היה יושב ומלמד, \u0003הוו יתבי קמיה\u0004 \u0005[היו יושבים לפניו]\u0006 \u0003רבא ורמי בר חמא. אמר לה\u0004 רב חסדא בצחוק לבתו: \u0003מאן מינייהו בעית\u0004 \u0005[\u0006את \u0005מי מהם היית רוצה]\u0006 כחתן? \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003תרוייהו\u0004 \u0005[\u0006את \u0005שניהם]\u0006 אני רוצה. \u0003אמר רבא: ואנא בתרא\u0004 \u0005[ואני\u0006 אהיה \u0005האחרון].\u0006 ואכן כך אירע, שנישאה קודם לרמי בר חמא, ואחרי מותו נישאה לרבא. כיון שהבאנו דבר אחד בשם ר' אבדימי דמן חיפה מביאים דבר נוסף משמו.","\u0003אמר ר' אבדימי דמן חיפה: קודם שיאכל אדם וישתה יש לו שתי לבבות,\u0004 כלומר, אין ליבו שלם, שהוא טרוד מפני שהוא רעב. \u0003לאחר שאוכל ושותה\u0004 — \u0003אין לו אלא לב אחד. שנאמר: \"\u0004ו\u0003איש נבוב ילבב\"\u0004 (איוב יא, יב), \u0003ו\u0004מה עניינו של \"נבוב\"? — \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"נבוב לחת\"\u0004 (שמות כז, ח), \u0003ומתרגמינן\u0004 \u0005[ומתרגמים אנו]:\u0006 \u0003חליל לוחין\u0004 \u0005[חלול לוחות],\u0006 אם כן, איש חלול, כלומר, מי שעדיין לא אכל — \"ילבב\", יש לו שני לבבות.","ועוד בענין משמעות זו של \"נבוב\" מביאים: \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: הרגיל ביין, אפילו לבו אטום כבתולה,\u0004 כמו בתולה זו שפיתחה אטום — \u0003יין מפקחו, שנאמר: \"ותירוש ינובב בתלות\"\u0004 (זכריה ט, יז), והוא מפרש באותו אופן: \"ינובב\" = עושה חלל בתוך דבר, שאף אם היה ליבו אטום הריהו נפתח להבנה.","ועוד בענייני חלוקת נכסים. \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: פשיטא\u0004 \u0005[פשוט\u0006 הוא\u0005]\u0006 שאדם שירש וקיבל בירושה \u0003חלק בכור\u0004 (שמקבל חלק נוסף על אחיו) \u0003וחלק פשוט\u0004 (שמקבל כאחד מאחיו) — \u0003יהבינן ליה אחד מצרא\u0004 \u0005[נותנים לו\u0006 את שני החלקים \u0005על מצר אחד]\u0006 שיהיו סמוכים זה לזה, שחלק אחד הם. ושאלו: \u0003יבם\u0004 האח שמייבם את אשת אחיו, שלפי הדין מקבל בירושת אביו גם את חלקו של אחיו שמת, \u0003מאי\u0004 \u0005[מה]\u0006 דינו לענין זה?","\u0003אמר אביי: היא היא\u0004 \u0005[הוא הוא].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003\"בכור\" קרייה רחמנא\u0004 \u0005[קראה אותו התורה]\u0006 ולכן דנים בו כבכור לכל דבר, ואת אותו חלק כפול שמקבל בירושה נותנים לו כיחידה אחת. ואילו \u0003רבא אמר: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והיה הבכור\"\u0004 (דברים כה, ו), אמנם \u0003הוייתו,\u0004 לענין עצם הירושה — הרי הוא \u0003כבכור, ו\u0004אולם \u0003אין\u0004 דרך \u0003חלוקתו\u0004 בפועל \u0003כבכור,\u0004 שאין האחים חייבים לצרף לו את שני החלקים.","מסופר: \u0003ההוא דזבן ארעא אמצרא דבי נשיה\u0004 \u0005[אדם אחד קנה קרקע על המיצר של בית אביו],\u0006 ולאחר זמן מת אביו. \u0003כי קא פלגו\u0004 \u0005[כאשר חלקו]\u0006 האחים קיבל גם הוא חלק, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003פליגו\u0004 \u0005[תחלקו]\u0006 \u0003לי\u0004 \u0003אמצראי\u0004 \u0005[על המצר שלי].\u0006 \u0003אמר רבה: כגון זה כופין על מדת סדום,\u0004 שהרי לאחים לא חשוב באיזה מקום יקחו את חלקם, שכל אחד זוכה בחלק שווה בערכו, ולו עדיף שיהיה חלקו בירושה ליד החלקה שכבר קנה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף:\u0004 זו אינה מדת סדום, שהאחים האחרים יכולים לתת טעם לסירובם, \u0003אמרי ליה אחי\u0004 \u0005[אומרים לו האחים]:\u0006 \u0003מעלינן ליה עלויא\u0004 \u0005[אנו אומדים את השדה הזה\u0006 שאתה מבקשה לעצמך \u0005כמשובח]\u0006 \u0003כי נכסי דבי\u0004 \u0005[כמו נכסיו של בית]\u0006 \u0003בר מריון,\u0004 שחלקה זו מעולה משאר הנכסים ואין אנו רוצים לתיתה לאח זה. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 בענין זה \u0003כרב יוסף\u0004 שהאחים יכולים לעכב.","אם היו \u0003תרי ארעתא אתרי נגרי\u0004 \u0005[שתי\u0006 חלקות \u0005קרקע על שתי תעלות]\u0006 ולאחד שדה משלו ליד אחת מהן — \u0003אמר רבה: כגון זה כופין על מדת סדום,\u0004 שיקבל את זו הסמוכה לשלו. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף,\u0004 אם האח השני מעכב ורוצה בחלקה זו — אין זו מדת סדום, אלא טעם יש בדבר, \u0003זמנין דהאי מדויל והאי לא מדויל\u0004 \u0005[פעמים ש\u0006תעלה \u0005זו נדלית\u0006 היטב \u0005וזו\u0006 השניה \u0005אינה נדלית\u0006 היטב\u0005]\u0006 ולכן רוצה חלקות שתהיינה להן תעלות סמוכות משני צדדים. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כרב יוסף.\u0004","אם היו \u0003תרתי אחד נגרא\u0004 \u0005[שתיים\u0006 שתי חלקות \u0005על תעלה אחת]\u0006 ואחד האחים יש לו חלקה סמוכה לתעלה זו — \u0003אמר רב יוסף: כגון זה כופין על מדת סדום\u0004 אם האחר אינו מסכים שתהא חלקת אחיו ליד שדה שקנה כבר. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003אביי, מצי אמר\u0004 \u0005[יכול לומר\u0006 לו\u0005]:\u0006 \u0003בעינא דאפיש אריסי\u0004 \u0005[רצוני שיתרבו אריסים],\u0006 שיהיו לך חלקות קרקע בשני הצדדים ותצטרך להוסיף אריסים גם לחלקה האחרת, ועל ידי כך תהא לי שמירה יותר טובה לשדותי! ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כרב יוסף, אפושי לאו מילתא היא\u0004 \u0005[הוספת\u0006 אריסים \u0005אינה\u0006 נחשבת \u0005דבר].\u0006"],["אם היו \u0003חד גיסא נגרא\u0004 \u0005[\u0006ב\u0005צד אחד\u0006 של השדה \u0005תעלה]\u0006 \u0003וחד גיסא נהרא\u0004 \u0005[ובצד אחד נהר]\u0006 — \u0003פלגין לה בקרנא זול\u0004 \u0005[חולקין אותו באלכסון]\u0006 כך שיקבלו שניהם חלקות הסמוכות הן לתעלה והן לנהר.","\u0003ועוד\u0004 שנינו ש\u0003לא\u0004 חולקים \u0003את הטרקלין\u0004 ודברים אחרים אלא אם כן יהיה בהם כדי לשמש בשימוש זה לכל אחד מהם, אם ייחלקו. ושואלים: אם \u0003אין בהן כדי לזה וכדי לזה, מהו?\u0004 מה עושים במקרה זה כאשר אחד מן השותפים אינו רוצה להמשיך בשותפות? \u0003רב יהודה אמר: אית דינא ד\"גוד או אגוד\"\u0004 \u0005[יש\u0006 כאן \u0005דין של \"קצוץ או אקצוץ\"],\u0006 כלומר, שיכול אחד מהם לומר לחבירו: או קנה, או מכור לי. \u0003רב נחמן אמר: לית דינא\u0004 \u0005[אין דין]\u0006 של \u0003\"גוד או אגוד\"\u0004 \u0005[\"קצוץ או אקצוץ\"],\u0006 אלא ישתמשו שניהם בשותפות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: לדידך דאמרת לית דינא ד\"גוד או אגוד\"\u0004 \u0005[לשיטתך שאתה אומר\u0006 ש\u0005אין\u0006 כאן \u0005דין של \"קצוץ או אקצוץ\"],\u0006 אם היו אח \u0003בכור ו\u0004אח \u0003פשוט שהניח להן אביהן\u0004 בירושה \u0003עבד ובהמה טמאה,\u0004 שדברים אלה אינם כבהמה טהורה שאפשר לשוחטה ושכל אחד יקבל ממנה חלק מסויים, \u0003כיצד עושין? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שאני אומר: עובד לזה\u0004 (לפשוט) \u0003יום אחד ולזה\u0004 (לבכור) \u0003שני ימים.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת רב יהודה, ממה ששנינו: \u0003מי שחציו עבד וחציו בן חורין\u0004 (כגון שהיה בבעלותם של שני שותפים ושחררו אחד מהם ), \u0003עובד את רבו\u0004 (אדוניו) \u0003יום אחד ואת עצמו יום אחד,\u0004 אלו \u0003דברי בית הלל. בית שמאי אומרים: תקנתם\u0004 בכך \u0003את רבו,\u0004 שמצד סדרי העבודה הענין מסודר, אבל \u0003את עצמו לא תקנתם,\u0004 ומדוע? \u0003לישא שפחה אינו יכול\u0004 שהרי בן חורין הוא במקצת ואסור בכך, ומנגד גם \u0003לישא בת חורין אינו יכול\u0004 משום שהוא עבד במקצת, וכי \u0003יבטל\u0004 מנישואין? \u0003והלא לא נברא העולם אלא לפריה ורביה, שנאמר: \"לא תהו בראה לשבת יצרה\"\u0004 (ישעיה מה, יח)!","\u0003אלא\u0004 כך עושים: \u0003כופין את רבו ועושין אותו בן חורין\u0004 שישחרר את חציו המשועבד, \u0003וכותבין שטר על חצי דמיו\u0004 והעבד ישלם לאדון את חצי מחיר עצמו. ואומרים: \u0003וחזרו בית הלל\u0004 מדבריהם \u0003להורות כדברי בית שמאי!\u0004 משמע שרק במקרה זה, משום טעם מיוחד זה של ביטול פריה ורביה, כופים את האחר לוותר על חלקו ואין אומרים שימשיכו בשותפות, אבל במקרה אחר — אין אומרים \"גוד או אגוד\"!","ומשיבים: \u0003שאני הכא ד\"אגוד\" איכא, \"גוד\" ליכא\u0004 \u0005[שונה כאן ש\"אקצוץ\" יש\u0006 כאן, \"\u0005קצוץ\" אין\u0006 כאן\u0005],\u0006 כלומר, העבד אינו יכול להציע למכור את עצמו, שמשום חלקו היהודי אינו יכול להימכר כעבד כנעני. ולכן אינו יכול לכפות על האדון למכור לו את חלקו. אבל במקום שיכולים שניהם לקנות — יכול אחד לחייב את שותפו לקנות או למכור את חלקו.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת לדבר ממה ששנינו: \u0003שני אחין\u0004 שהיה \u0003אחד\u0004 מהם \u0003עני ואחד עשיר, והניח להן אביהן\u0004 בירושה \u0003מרחץ ובית הבד,\u0004 אם \u0003עשאן\u0004 האב \u0003לשכר\u0004 (להשכירם לאחרים) — הרי \u0003השכר לאמצע,\u0004 כלומר, שכר ההשכרה מתחלק בין שני האחים, אם \u0003עשאן ל\u0004שימוש \u0003עצמו\u0004 ולא להשכיר לאחרים — \u0003הרי\u0004 האח ה\u0003עשיר אומר ל\u0004אח ה\u0003עני:\u0004"],["\u0003\"קח לך עבדים וירחצו במרחץ\", \"קח לך זיתים ובא ועשה בבית הבד\"!\u0004 ואין העני יכול לומר לאחיו: \"קנה את חלקי\"! ודוחים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 \u0003\"גוד\" איכא\u0004 \u0005[\"קצוץ\" יש\u0006 כאן\u0005],\u0006 שאכן יכול האח העשיר לקנות מאחיו, ואולם \u0003\"אגוד\" ליכא\u0004 \u0005[\"אקצוץ\" אין\u0006 כאן\u0005],\u0006 שהרי אין האח העני יכול להציע לקנות את חלקו של האח העשיר.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממקום אחר, ששנינו בברייתא: \u0003כל שאילו יחלק ו\u0004עדיין ישאר \u0003שמו עליו\u0004 — \u0003חולקין,\u0004 ו\u0003אם לאו\u0004 \u0005[לא],\u0006 שנשתנה שמו כתוצאה מהחלוקה — \u0003מעלין\u0004 (מעריכים) \u0003אותו בדמים\u0004 (בכסף), ומשמע שעושים זאת משום \"גוד או אגוד\", שיקנה האחד את הכל! ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אם היה מקום שאין בו כדי חלוקה לשנים ואמר אחד לחבירו: \u0003\"טול אתה שיעור\u0004 הראוי לחלוקה, כגון ארבע אמות שלמות, \u0003ואני פחות\"\u0004 — \u0003שומעין לו, רבן שמעון בן גמליאל אומר: אין שומעין לו.\u0004","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא כדתני\u0004 \u0005[אם תאמר כפי ששנויה]\u0006 בדיוק — \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבן שמעון בן גמליאל,\u0004 מדוע אין שומעים לו אם הוא מסתפק בפחות? \u0003אלא לאו חסורי מחסרא\u0004 \u0005[האם לא\u0006 נאמר ש\u0005חסרה\u0006 הברייתא\u0005]\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמור,\u0006 כך יש לשנותה\u0005]:\u0006 \u0003\"טול אתה שיעור ואני פחות\"\u0004 — \u0003שומעין לו\u0004 לדעת הכל. והוסיף התנא של הברייתא: \u0003ו\"גוד או אגוד\"\u0004 \u0005[\"קצוץ או אקצוץ\"]\u0006 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003שומעין לו, ואתא\u0004 \u0005[ובא]\u0006 \u0003רבן שמעון בן גמליאל למימר\u0004 \u0005[לומר]:\u0006 במקרה הראשון אכן שומעים לו, ואולם במקרה של \"גוד או אגוד\" \u0003אין שומעין לו,\u0004 ואם כן מחלוקת תנאים היא זו!","ודוחים: \u0003לא, לעולם\u0004 תפרש \u0003כדקתני\u0004 \u0005[כפי ששנה]\u0006 בדיוק, \u0003ודקאמרת\u0004 \u0005[ומה שאמרת]\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבן שמעון בן גמליאל\u0004 שאין אחד מהם יכול לומר שיחלקו ויסתפק הוא בפחות? — \u0003משום דאמר ליה\u0004 \u0005[שיכול לומר לו]\u0006 השני: \u0003אי בדמי\u0004 \u0005[אם בדמים],\u0006 שאתה רוצה שאוסיף לך על מה שאקבל יותר ממך — \u0003לית לי דמי למיתן\u0004 \u0005[אין לי כסף לתת]\u0006 \u0003לך,\u0004 ואם רצונך לתת לי \u0003במתנה\u0004 — \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושונא מתנת יחיה\"\u0004 (משלי טו, כז). הרי הוכחנו מן הברייתא שאכן יש דין \"גוד או אגוד\", וכדברי רב יהודה.","ובהמשך לדברים אלו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 שאמר \u0003רב יהודה\u0004 — של \u0003שמואל\u0004 רבו \u0003היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003וכתבי הקודש, אף על פי ששניהם רוצים\u0004 לחלק — \u0003לא יחלוקו. ואמר שמואל: לא שנו אלא\u0004 שהם \u0003בכרך אחד, אבל\u0004 כאשר הם \u0003בשני כריכות\u0004 — \u0003חולקין,\u0004 וכל אחד מן השותפים נוטל אחד מהם לחלקו. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר \u0003לית דינא\u0004 \u0005[\u0006ש\u0005אין דין]\u0006 של \u0003\"גוד או אגוד\"\u0004 \u0005[\"קצוץ או אקצוץ\"],\u0006 \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דוקא\u0005]\u0006 \u0003בכרך אחד? אפילו בשני כריכין נמי\u0004 \u0005[גם כן]\u0006 לא יחלקו, שהרי אין החלקים שווים ובהכרח צריך אחד להוסיף!","\u0003תרגמא\u0004 \u0005[תרגם,\u0006 הסביר זאת\u0005]\u0006 \u0003רב שלמן:\u0004 כאן מדובר \u0003בששניהן רוצין\u0004 ואז מחלקים, אבל אם רק אחד מהם רוצה — אין מכאן הוכחה שיכול לכפות את חבירו.","\u0003אמר אמימר, הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003אית דינא ד\"גוד או אגוד\"\u0004 \u0005[יש,\u0006 מקבלים אנו את \u0005הדין של \"קצוץ או אקצוץ\"],\u0006 וכדברי רב יהודה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: הא\u0004 \u0005[זו]\u0006 שאמר \u0003רב נחמן\u0004 החולק על רב יהודה, והוא סבור שאין דין \"גוד או אגוד\", \u0003מאי\u0004 \u0005[מה]\u0006 יהיה איתה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא שמיעא לי\u0004 \u0005[שמעתי אותה],\u0006 \u0003כלומר,\u0004 כוונתו היתה: \u0003לא סבירא לי\u0004 \u0005[איני סבור כן].\u0006 ושואלים: \u0003ולא?\u0004 האם אין ההלכה כך? \u0003והא\u0004 \u0005[והרי]\u0006 מעשה היה ש\u0003רבין בר חיננא ורב דימי בר חיננא שבק להו אבוה תרתי אמהתא\u0004 \u0005[הניח להם אביהם שתי שפחות],\u0006 \u0003חדא ידעא אפיא ובשולי\u0004 \u0005[אחת\u0006 מהן \u0005יודעת לאפות ולבשל],\u0006 \u0003וחדא ידעא פילכא ונוולא\u0004 \u0005[ואחת\u0006 מהן \u0005יודעת\u0006 לעבוד \u0005בפלך ובאריגה],\u0006 ורצה אחד מן האחים שיטול כל אחד מהם שפחה שתהא כולה שלו, תמורת חלקו בשפחה השניה, \u0003ואתו לקמיה\u0004 \u0005[ובאו לפני]\u0006 \u0003רבא, ואמר להו\u0004 \u0005[להם]:\u0006 \u0003לית דינא\u0004 \u0005[אין דין]\u0006 של \u0003\"גוד או אגוד\"\u0004 \u0005[\"קצוץ או אקצוץ\"]!\u0006","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דלמר מיבעי ליה תרוייהו ולמר מיבעי ליה תרוייהו\u0004 \u0005[שלזה נחוצות לו שתיהם ולזה נחוצות לו שתיהן],\u0006 ולכן \u0003כי קאמר ליה\u0004 \u0005[כאשר הוא אומר לו]\u0006 אחד האחים לאחיו: \u0003שקול את חדא ואנא חדא\u0004 \u0005[קח אתה אחת ואני אחת]\u0006 — \u0003לאו \"גוד או אגוד\"\u0004 \u0005[לא \"קצוץ או אקצוץ\"]\u0006 \u0003הוא.\u0004 ושואלים: \u0003וכי לא מצי למימר הכי\u0004 \u0005[אי אפשר לומר כך]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כתבי הקדש דתרוייהו מיבעי להו\u0004 \u0005[ששניהם צריכים אותם]\u0006 \u0003ואמר שמואל: לא שנו אלא בכרך אחד, אבל בשני כריכין\u0004 — \u0003חולקין,\u0004 אף שאין שני הכרכים שווים בתוכנם! ומשיבים: \u0003הא תרגמא\u0004 \u0005[הרי\u0006 כבר \u0005תרגם,\u0006 הסביר זאת\u0005]\u0006 \u0003רב שלמן\u0004 שמדובר כאן \u0003בשרצו\u0004 לחלק.","ומכאן עוברים לענין ספרי הקודש בכלל. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מדביק אדם תורה נביאים וכתובים כאחד\u0004 ועושה אותם ספר אחד, אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 כורך \u0003תורה בפני עצמה, נביאים בפני עצמן, וכתובים בפני עצמן. וחכמים אומרים: כל אחד ואחד\u0004 מספרי נביאים וכתובים נכרך \u0003בפני עצמו.\u0004","\u0003ואמר ר' יהודה: מעשה בביתוס בן זונין, שהיו לו שמנה\u0004 ספרי \u0003נביאים מדובקין כאחד\u0004 בכרך אחד, והוא עשה זאת \u0003על פי ר' אלעזר בן עזריה. ויש אומרים\u0004 ש\u0003לא היו לו אלא\u0004 כל \u0003אחד אחד\u0004 היה כרוך \u0003בפני עצמו,\u0004 כדברי חכמים. \u0003אמר רבי: מעשה והביאו לפנינו תורה נביאים וכתובים מדובקים כאחד, והכשרנום,\u0004 שפסק כדעת ר' מאיר.","ואומרים: כשהספרים כרוכים יחד צריך שיהיה \u0003בין חומש לחומש של תורה\u0004 — \u0003ארבעה שיטין\u0004 (שורות) ריקות לרווח, \u0003וכן בין כל נביא לנביא\u0004 רווח ארבע שורות, \u0003ובנביא של שנים עשר\u0004 (תרי עשר) מכיון שהם נחשבים לספר אחד — מניח רק \u0003שלש שיטין\u0004 (שורות) הבדל בין נביא לנביא. \u0003ומסיים מלמטה,\u0004 כלומר, יכול לסיים את הספר מלמטה בסוף הדף, \u0003ומתחיל\u0004 את הספר הבא \u0003מלמעלה\u0004 בראש העמוד הבא, בלי לעשות רווח.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרוצה לדבק תורה נביאים וכתובים כאחד\u0004 — \u0003מדבק\u0004 את כולם יחד, \u0003ועושה בראשו\u0004 של הכרך הזה חלק ריק בלא כתיבה, רחב דיו \u0003כדי לגול\u0004 (לגלול) חלק זה על גבי \u0003עמוד\u0004 שכורך עליו את ראש הספר. \u0003ובסופו\u0004 משאיר דף חלק גדול \u0003כדי לגול היקף,\u0004 כלומר, עד שיכול לגלול בדף זה את כל היקפו של הספר. \u0003ומסיים\u0004 ספר \u0003מלמטה\u0004 בסוף העמוד \u0003ומתחיל מלמעלה,\u0004"]]};
